/* ==============================
   MVP PODIUM
================================ */

.mvpPodiumSection {
  padding: 22px 22px 0;

  border: 1px solid #303844;
  border-radius: 18px;

  background:
    radial-gradient(
      circle at 50% 0%,
      rgba(217, 174, 75, 0.11),
      transparent 46%
    ),
    #151a21;
}

.mvpPodiumHeader {
  text-align: center;
}

.mvpPodiumHeader > span,
.mvpLeaderboardHeader > span {
  color: #d9ae4b;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.mvpPodiumHeader h3,
.mvpLeaderboardHeader h3 {
  margin: 4px 0 0;

  font-size: 25px;
}

.mvpPodium {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
  align-items: end;
  gap: 14px;

  max-width: 900px;
  margin: 30px auto 0;
}

.mvpPodiumSlot {
  display: grid;
  grid-template-rows:
    auto auto auto;
  align-items: end;

  min-width: 0;
}

.mvpPodiumPlayer {
  position: relative;

  display: grid;
  justify-items: center;
  gap: 4px;

  padding: 17px 12px 14px;

  border: 1px solid #313a46;
  border-radius: 15px 15px 0 0;

  background: #1b212a;

  text-align: center;
}

.mvpPodiumPlayer > strong {
  max-width: 100%;

  overflow: hidden;

  font-size: 22px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mvpPodiumPlayer > small {
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.09em;
}

.mvpMedal {
  display: grid;
  place-items: center;

  width: 38px;
  height: 38px;

  margin-top: -37px;

  border: 3px solid #151a21;
  border-radius: 50%;

  background: #596473;
  color: #f5f7fa;

  font-size: 16px;
  font-weight: 950;
}

.mvpPodiumScore {
  display: grid;
  justify-items: center;

  padding: 13px 10px;

  border-right: 1px solid #313a46;
  border-left: 1px solid #313a46;

  background: #11151b;
}

.mvpPodiumScore strong {
  font-size: 31px;
  line-height: 1;
}

.mvpPodiumScore span {
  margin-top: 4px;

  color: #7e8997;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.mvpPodiumBlock {
  display: grid;
  place-items: center;

  min-height: 128px;

  border-radius: 0 0 10px 10px;

  background:
