/* ==============================
   STANDARD ROUND — QUICK RANK
   Round CSS.
================================ */

.standardModeBar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;

  max-width: 760px;
  margin: 0 auto 18px;
  padding: 14px 16px;

  border: 1px solid #2c3540;
  border-radius: 15px;

  background: #151a21;
}

.standardModeBar > div {
  display: grid;
  gap: 3px;
}

.standardModeBar > div > span {
  color: #7f8b99;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.standardModeBar > div > strong {
  font-size: 16px;
}

.standardModeButton {
  flex: 0 0 auto;

  min-height: 40px;
  padding: 0 14px;

  border: 1px solid #3a4552;
  border-radius: 10px;

  background: #252d38;
  color: #dfe5eb;

  font-size: 11px;
  font-weight: 850;
}

.quickRankPanel {
  position: relative;

  max-width: 760px;
  margin: 0 auto 18px;
}

.quickRankList {
  display: grid;

  margin: 0;
  padding: 0;

  list-style: none;
}

.quickRankItem {
  position: relative;

  margin: 0;
  padding: 0;

  list-style: none;

  touch-action: none;
}

.quickRankCard {
  display: grid;
  grid-template-columns:
    54px minmax(0, 1fr) auto 30px;
  align-items: center;
  gap: 13px;

  min-height: 84px;
  padding: 12px 16px;

  border: 1px solid #303a46;
  border-radius: 16px;

  background: #1a2028;

  cursor: grab;
  user-select: none;
}

.quickRankCard:active {
  cursor: grabbing;
}

.quickRankNumber {
  display: grid;
  place-items: center;

  width: 42px;
  height: 42px;

  border-radius: 12px;

  background: #252e39;
  color: #9ba8b6;

  font-size: 17px;
  font-weight: 950;
}

.quickRankPlayer {
  display: grid;
  gap: 3px;

  min-width: 0;
}

.quickRankPlayer strong {
  overflow: hidden;

  font-size: 22px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.quickRankPlayer span {
  color: #778493;

  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.quickRankPoints {
  display: grid;
  justify-items: end;
}

.quickRankPoints strong {
  font-size: 25px;
}

.quickRankPoints span {
  color: #788493;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.quickRankDrag {
  color: #647181;

  font-size: 20px;
  font-weight: 900;
}

/*
  The small divider between cards is
  the "connect these two" control.
*/
.rankTieConnector {
  position: relative;
  z-index: 3;

  display: grid;
  place-items: center;

  width: calc(100% - 36px);
  height: 24px;
  margin: -1px 18px;

