.hideStageBreakdown > span {
  color: #a891c5;

  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.hideStageBreakdown > div {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 5px;
}

.hideStageBreakdown small {
  color: #8f7ba8;
  font-size: 11px;
}

.hideStageBreakdown strong {
  color: #d0b7ef;
}

/* AWARDS */

.historyAwards {
  display: grid;
  gap: 18px;
}

.awardsIntro {
  padding: 5px 2px 2px;
}

.awardsIntro > span {
  color: #d9ae4b;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.awardsIntro h2 {
  margin: 5px 0 6px;

  font-size: 31px;
}

.awardsIntro p {
  max-width: 620px;
  margin: 0;

  color: #8994a2;
  line-height: 1.5;
}

.awardGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.awardCard {
  min-width: 0;

  padding: 20px;

  border: 1px solid #303844;
  border-radius: 18px;

  background: #171c24;
}

.awardCard > span {
  color: #d9ae4b;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.awardCard h3 {
  margin: 8px 0 4px;

  overflow-wrap: anywhere;

  font-size: 27px;
}

.awardCard > strong {
  color: #b5c0cd;

  font-size: 15px;
}

.awardCard p {
  margin: 11px 0 0;

  color: #7f8b99;

  font-size: 13px;
  line-height: 1.4;
}

@media (max-width: 700px) {
  .historySessionMeta {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .playerStatSectionLabel {
    font-size: 13px;
  }

  .playerStatGrid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .playerStatGrid span,
  .hideStageBreakdown > span {
    font-size: 11px;
  }

  .awardGrid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .historySessionSummary {
    align-items: flex-start;
  }

  .historySessionSummaryRight {
    flex-direction: column;
    align-items: flex-end;
    gap: 5px;
  }

  .hideStageBreakdown {
    grid-template-columns:
      1fr 1fr;
  }

  .hideStageBreakdown > span {
    grid-column: 1 / -1;
  }
}


/* ==============================
   SESSION AWARDS
================================ */

.sessionAwardsSection {
  margin-top: 20px;
  padding-top: 18px;

  border-top: 1px solid #29313b;
}

.sessionAwardsHeader {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;

  margin-bottom: 12px;
}

.sessionAwardsHeader span {
  color: #d9ae4b;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.sessionAwardsHeader strong {
  color: #8994a2;

  font-size: 13px;
}

.sessionAwardGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 9px;
}

.sessionAwardCard {
  padding: 15px;

  background: #141920;
}

.sessionAwardCard > span {
  font-size: 9px;
}

.sessionAwardCard h3 {
  margin: 6px 0 3px;

  font-size: 21px;
}

.sessionAwardCard > strong {
  font-size: 13px;
}

.sessionAwardCard p {
  margin-top: 8px;

  font-size: 12px;
}

@media (max-width: 600px) {
  .sessionAwardGrid {
    grid-template-columns: 1fr;
  }

  .sessionAwardsHeader {
    align-items: flex-start;
    flex-direction: column;
    gap: 3px;
  }
