.mvpMethodNote {
  padding: 15px 17px;

  border: 1px solid #2c3540;
  border-radius: 14px;

  background: #131820;
}

.mvpMethodNote strong {
  color: #9aa6b5;

  font-size: 10px;
  letter-spacing: 0.09em;
}

.mvpMethodNote p {
  margin: 6px 0 0;

  color: #778493;

  font-size: 12px;
  line-height: 1.5;
}

@media (max-width: 850px) {
  .mvpIntro {
    align-items: flex-start;
    flex-direction: column;
  }

  .mvpComponents {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .mvpEligibility {
    align-items: flex-start;
    flex-direction: column;
  }

  .mvpEligibility p {
    text-align: left;
  }
}

@media (max-width: 600px) {
  .historyTabs {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .mvpComponents {
    grid-template-columns: 1fr;
  }

  .mvpCard > header {
    align-items: flex-start;
  }

  .mvpScore strong {
    font-size: 30px;
