/* ==============================
   DELETE SAVED SESSION
================================ */

.historyDeleteArea {
  display: flex;
  justify-content: flex-end;

  margin-top: 11px;
}

.historyDeleteArea > span {
  color: #697583;

  font-size: 10px;
  font-weight: 750;
}

.historyDeleteButton {
  min-height: 38px;
  padding: 0 13px;

  border: 1px solid #51353a;
  border-radius: 10px;

  background: transparent;
  color: #bd727b;

  font-size: 11px;
  font-weight: 850;
}

.historyDeleteButton:hover {
  border-color: #70434a;

  background: #291b1e;
  color: #e0929b;
}

/* Confirmation */

.historyDeleteOverlay {
  position: fixed;
  inset: 0;
  z-index: 1100;

  display: grid;
  place-items: center;

  padding: 22px;

  background:
    rgba(5, 8, 12, 0.78);

  backdrop-filter:
    blur(8px);
}

.historyDeleteDialog {
  width: min(
    100%,
    540px
  );

  padding: 28px;

  border:
    1px solid #51343a;
  border-radius: 22px;

  background: #171c24;

  box-shadow:
    0 24px 70px
    rgba(0, 0, 0, 0.48);
}

.historyDeleteLabel {
  color: #dc7d87;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.historyDeleteDialog h2 {
  margin: 7px 0 8px;

  font-size: 30px;
}

.historyDeleteDialog > p {
  margin:
    0 0 20px;

  color: #8b97a5;

  font-size: 13px;
  line-height: 1.5;
}

.historyDeleteSummary {
  display: grid;
  grid-template-columns:
    repeat(2, 1fr);
  gap: 9px;

  margin-bottom: 20px;
}

.historyDeleteSummary > div {
  padding: 14px 15px;

  border-radius: 13px;

  background: #11151b;
}

.historyDeleteSummary span {
  display: block;

  margin-bottom: 4px;

