}

.playerEditorNicknames {
  margin-top: 19px;
}

.playerEditorNicknames > p {
  margin: 2px 0;

  color: #687483;

  font-size: 12px;
}

.nicknameChipList {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.nicknameChip {
  display: inline-flex;
  align-items: center;

  overflow: hidden;

  border:
    1px solid #3a4755;
  border-radius: 10px;

  background: #202832;
}

.nicknameChip strong {
  padding: 7px 9px;

  font-size: 12px;
}

.nicknameChip button {
  align-self: stretch;

  min-width: 31px;

  border: 0;
  border-left:
