}

.playerEditorActions {
  display: grid;
  grid-template-columns:
    1fr 1.4fr;
  gap: 9px;

  margin-top: 19px;
}

.playerEditorActions button {
  min-height: 55px;

  border-radius: 13px;

  font-size: 14px;
  font-weight: 850;
}

.playerEditorCancel {
  border:
    1px solid #39434f;

  background: #232a33;
