  color: #f2f5f8;

  font-size: 21px;
  line-height: 1.08;
}

.cardTriviaWinner small {
  display: block;

  margin-top: 4px;

  color: #738294;

  font-size: 10px;
  font-weight: 700;
}

.cardTriviaCard > strong {
  display: block;

  margin-top: 17px;

  color: #dcecff;

  font-size: 30px;
