/* =========================================
   ROUND EDITOR — UI POLISH
   Append to the VERY BOTTOM of index.css

   - Standard result: drag to reorder
   - Jim result: custom choice buttons
========================================= */

/* ---------- STANDARD: DRAG RANKING ---------- */

.roundEditDragList {
  display: grid;
  gap: 7px;

  margin: 0;
  padding: 0;

  list-style: none;
}

.roundEditDragItem {
  margin: 0;
  padding: 0;

  list-style: none;

  cursor: grab;
  user-select: none;
  -webkit-user-select: none;
}

.roundEditDragItem:active {
  cursor: grabbing;
}

.roundEditDragRow {
  display: grid;
  grid-template-columns:
    32px minmax(0, 1fr) 38px;
  align-items: center;
  gap: 10px;

  min-height: 50px;
  padding: 7px 9px 7px 12px;

  border: 1px solid #34404c;
  border-radius: 11px;

  background: #161c23;

  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.02);
}

.roundEditDragItem:active
.roundEditDragRow {
  border-color: #5b6b7d;

  background: #1d252f;

  box-shadow:
    0 10px 28px
    rgba(0, 0, 0, 0.3);
}

.roundEditDragPosition {
  display: grid;
  place-items: center;

  width: 26px;
  height: 26px;

  border-radius: 8px;

  background: #222b35;
  color: #9ca9b7;

  font-size: 11px;
  font-weight: 900;
}

.roundEditDragRow > strong {
  overflow: hidden;

  color: #edf1f4;

  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.roundEditDragHandle {
  display: grid;
  place-items: center;

  width: 34px;
  height: 34px;

  border: 1px solid #3e4a57;
  border-radius: 9px;

  background: #222a34;
  color: #aab6c2;

  font-size: 16px;
  font-weight: 900;
}

.roundEditDragHint {
  margin-top: -3px;

  color: #6f7c89;

  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.025em;
}

/* ---------- JIM: CUSTOM CHOICE CONTROLS ---------- */

.roundEditChoiceField {
  display: grid;
  gap: 7px;
}

.roundEditChoiceField > span {
  color: #7f8b99;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.roundEditChoiceGrid {
  display: grid;
  grid-template-columns:
    repeat(
      auto-fit,
      minmax(120px, 1fr)
    );
  gap: 7px;
}

.roundEditChoiceGrid button,
.roundEditNumberChoices button,
.roundEditHideChoices button {
  min-height: 42px;
  padding: 0 12px;

  border: 1px solid #38434f;
  border-radius: 10px;

  background: #1c232c;
  color: #9da9b6;

  font: inherit;
  font-size: 11px;
  font-weight: 850;

  transition:
    border-color 120ms ease,
    background 120ms ease,
    color 120ms ease,
    transform 120ms ease;
}

.roundEditChoiceGrid button:hover,
.roundEditNumberChoices button:hover,
.roundEditHideChoices button:hover {
  border-color: #536273;

  background: #232c36;
  color: #dce2e8;
}

.roundEditChoiceGrid button:active,
.roundEditNumberChoices button:active,
.roundEditHideChoices button:active {
  transform: translateY(1px);
}

/* Generic selected state */
.roundEditChoiceGrid button.active,
.roundEditNumberChoices button.active,
.roundEditHideChoices button.active {
  border-color: #637487;

  background: #2a3542;
  color: #eef2f5;

  box-shadow:
    inset 0 0 0 1px
    rgba(255, 255, 255, 0.025);
}

/* Catcher selection */
.roundEditChoiceGrid button.active.caught {
  border-color: #754852;

  background: #3a242a;
  color: #ef98a2;
}

/* Hide selection */
.roundEditHideChoices button.active.hide {
  border-color: #765a98;

  background: #30253f;
  color: #d8baf5;
}

/* 0–5 stages */
.roundEditNumberChoices {
  display: grid;
  grid-template-columns:
    repeat(6, minmax(0, 1fr));
  gap: 6px;
}

.roundEditNumberChoices button {
  padding: 0;

  font-size: 13px;
}

/* No Hide + stages 2–5 */
.roundEditHideChoices {
  display: grid;
  grid-template-columns:
    repeat(5, minmax(0, 1fr));
  gap: 6px;
}

/* ---------- SMALL SCREENS ---------- */

@media (max-width: 620px) {
  .roundEditDragRow {
    grid-template-columns:
      30px minmax(0, 1fr) 36px;

    min-height: 48px;
  }

  .roundEditChoiceGrid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .roundEditNumberChoices {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }

  .roundEditHideChoices {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .roundEditHideChoices
  button:first-child {
    grid-column: 1 / -1;
  }
}

/* =========================================
   ROUND EDITOR — QUICK-RANK STYLE TIES
   Append to the VERY BOTTOM of index.css
========================================= */

/* Let the connector occupy the gap between
   the ranking cards. */
.roundEditDragList {
  gap: 0 !important;
}

.roundEditDragItem {
  display: grid;
  padding-bottom: 7px;
}

.roundEditDragItem.hasTieConnector {
  padding-bottom: 0;
}

/* The small divider between positions is
   now the tie control, matching Quick Rank. */
.roundEditTieConnector {
  position: relative;
  z-index: 3;

  display: grid;
  place-items: center;

  width: calc(100% - 36px);
  height: 24px;
  margin: -1px 18px;
  padding: 0;

  border: 0;

  background: transparent;

  cursor: pointer;
  touch-action: manipulation;
}

.roundEditTieConnector::before {
  content: '';

  position: absolute;
  left: 0;
  right: 0;
  top: 50%;

  height: 1px;

  background: #27303a;
}

.roundEditTieConnector > span {
  position: relative;
  z-index: 1;

  display: grid;
  place-items: center;

  min-width: 30px;
  height: 20px;
  padding: 0 7px;

  border: 1px solid #34404d;
  border-radius: 999px;

  background: #11161c;
  color: #7e8997;

  font-size: 10px;
  font-weight: 950;
  letter-spacing: 0.05em;
}

.roundEditTieConnector:hover > span {
  border-color: #526071;
  color: #a8b3c0;
}

/* Active tie: same purple connector language
   as the normal Standard Quick Rank screen. */
.roundEditTieConnector.active {
  height: 30px;
  margin-top: -4px;
  margin-bottom: -4px;

  border-right: 2px solid #856fd0;
  border-left: 2px solid #856fd0;

  background: rgba(133, 111, 208, 0.08);
}

.roundEditTieConnector.active::before {
  background: #856fd0;
}

.roundEditTieConnector.active > span {
  border-color: #856fd0;

  background: #302747;
  color: #c9b8f3;
}

/* Highlight the two cards belonging to the
   active tie. */
.roundEditDragRow.tiedWithNext,
.roundEditDragRow.tiedWithPrevious {
  border-color: #6757a1;

  background:
    linear-gradient(
      90deg,
      rgba(116, 91, 180, 0.08),
      #161c23 45%
    );
}

.roundEditDragRow.tiedWithNext {
  border-bottom-right-radius: 8px;
  border-bottom-left-radius: 8px;
}

.roundEditDragRow.tiedWithPrevious {
  border-top-right-radius: 8px;
  border-top-left-radius: 8px;
}

.roundEditDragRow.tiedWithNext
.roundEditDragPosition,
.roundEditDragRow.tiedWithPrevious
.roundEditDragPosition {
  background: #302747;
  color: #c9b8f3;
}

/* Replace the old one-line hint with the
   compact Quick Rank-style legend. */
.roundEditDragHint {
  display: flex !important;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 16px;

  margin-top: 7px !important;

  color: #74808e;

  font-size: 10px !important;
  font-weight: 750 !important;
}

@media (max-width: 620px) {
  .roundEditTieConnector {
    width: calc(100% - 24px);
    margin-right: 12px;
    margin-left: 12px;
  }

  .roundEditDragHint {
    gap: 5px 12px;
  }
}

/* =========================================
   SCOREBOARD — JIM WIN STAR / HIDE MARKER
   Append to the VERY BOTTOM of index.css

   Gold star = Jim win
   Purple ring = Hide was used for that win
   No ring = hideless Jim win
========================================= */

.jimWinStars {
  gap: 3px !important;
}

.jimWinStars > .jimWinStar {
  display: inline-grid;
  place-items: center;

  width: 21px;
  height: 21px;

  box-sizing: border-box;

  border: 1px solid transparent;
  border-radius: 50%;

  color: #e3b64b;

  font-size: 14px;
  line-height: 1;

  filter:
    drop-shadow(
      0 0 4px
      rgba(227, 182, 75, 0.15)
    );
}

/* Jim win where Hide was used. */
.jimWinStars >
.jimWinStar.usedHide {
  border-color: #8d6ac0;

  background:
    rgba(141, 106, 192, 0.07);

  box-shadow:
    inset 0 0 0 1px
      rgba(141, 106, 192, 0.08),
    0 0 5px
      rgba(141, 106, 192, 0.15);
}

/* Keep identical dimensions so stars
   remain perfectly aligned. */
.jimWinStars >
.jimWinStar.hideless {
  border-color: transparent;
}

@media (max-width: 620px) {
  .jimWinStars >
  .jimWinStar {
    width: 19px;
    height: 19px;

    font-size: 13px;
  }
}

/* =========================================
   JIM HIDE MARKERS — TRANSITION + PREVIOUS WINNER
   Append to the VERY BOTTOM of index.css

   Gold star only = hideless Jim
   Gold star + purple ring = Hide used
========================================= */

/* ---------- SCORE TRANSITION ---------- */

.scoreJimStars {
  gap: 3px !important;
}

.scoreJimStars >
.scoreJimStar {
  display: inline-grid;
  place-items: center;

  width: 19px;
  height: 19px;

  box-sizing: border-box;

  border: 1px solid transparent;
  border-radius: 50%;

  color: #e3b64b;

  font-size: 13px;
  line-height: 1;
}

.scoreJimStars >
.scoreJimStar.usedHide {
  border-color: #8d6ac0;

  background:
    rgba(141, 106, 192, 0.07);

  box-shadow:
    inset 0 0 0 1px
      rgba(141, 106, 192, 0.08),
    0 0 5px
      rgba(141, 106, 192, 0.14);
}

/* Reward bubble shown when a fresh Jim win
   is awarded during the transition. */
.rewardStar {
  display: inline-grid;
  place-items: center;

  width: 21px;
  height: 21px;

  box-sizing: border-box;

  border: 1px solid transparent;
  border-radius: 50%;
}

.rewardStar.usedHide {
  border-color: #8d6ac0;

  background:
    rgba(141, 106, 192, 0.08);

  box-shadow:
    0 0 5px
      rgba(141, 106, 192, 0.15);
}

/* ---------- PREVIOUS ROUND WINNER ---------- */

/* Keep the existing gold Jim appearance.
   Only add purple language when that Jim
   round used Hide. */
.previousWinnerIcon.jim.usedHide {
  border: 1px solid #8d6ac0;

  box-shadow:
    inset 0 0 0 1px
      rgba(141, 106, 192, 0.08),
    0 0 6px
      rgba(141, 106, 192, 0.16);
}

@media (max-width: 620px) {
  .scoreJimStars >
  .scoreJimStar {
    width: 18px;
    height: 18px;

    font-size: 12px;
  }

  .rewardStar {
    width: 20px;
    height: 20px;
  }
}

/* =========================================
   JIM CATCH / JIM SLAYER — SCISSORS
   Append to the VERY BOTTOM of index.css

   ✂︎ = caught Jim
   ★ = Jim win
   Purple ring on ★ = Hide used
========================================= */

/* MAIN SCOREBOARD */

.jimCatchScissors {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2px;

  line-height: 1;
}

.jimCatchScissor {
  display: inline-grid;
  place-items: center;

  width: 21px;
  height: 21px;

  color: #ef8f99;

  font-family:
    "Noto Sans Symbols 2",
    "Segoe UI Symbol",
    sans-serif;

  font-size: 15px;
  font-weight: 700;
  line-height: 1;

  text-shadow:
    0 0 5px
    rgba(239, 143, 153, 0.14);
}


/* ROUND TRANSITION */

.scoreJimScissors {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2px;

  line-height: 1;
}

.scoreJimScissor {
  display: inline-grid;
  place-items: center;

  width: 19px;
  height: 19px;

  color: #ef8f99;

  font-family:
    "Noto Sans Symbols 2",
    "Segoe UI Symbol",
    sans-serif;

  font-size: 14px;
  font-weight: 700;
  line-height: 1;
}

.scoreJimScissors.pop {
  animation:
    achievementPop
    650ms
    cubic-bezier(
      0.22,
      1.4,
      0.36,
      1
    );
}

.rewardScissors {
  display: inline-grid;
  place-items: center;

  width: 21px;
  height: 21px;

  color: #ef9aa2;

  font-family:
    "Noto Sans Symbols 2",
    "Segoe UI Symbol",
    sans-serif;

  font-size: 15px;
  font-weight: 700;
  line-height: 1;
}


/* PREVIOUS WINNER */

.previousWinnerIcon.jim.caught {
  border-color: #754852 !important;

  background: #3a242a !important;
  color: #ef9aa2 !important;

  font-family:
    "Noto Sans Symbols 2",
    "Segoe UI Symbol",
    sans-serif;

  box-shadow:
    inset 0 0 0 1px
      rgba(239, 154, 162, 0.04),
    0 0 7px
      rgba(239, 154, 162, 0.13)
      !important;
}


/* TABLET */

@media (max-width: 620px) {
  .jimCatchScissor {
    width: 19px;
    height: 19px;

    font-size: 13px;
  }

  .scoreJimScissor {
    width: 18px;
    height: 18px;

    font-size: 13px;
  }

  .rewardScissors {
    width: 20px;
    height: 20px;

    font-size: 14px;
  }
}

/* =========================================
   HEADER CLOCK — ISOLATED TIMER VERSION
   Append to the VERY BOTTOM of index.css

   Big current-time clock lives below ROUND.
   Small elapsed timer stays below buttons.
========================================= */

/* Left header column */
.gameRoundArea {
  justify-self: start;

  display: grid;
  justify-items: start;
  gap: 10px;
}


/* Big readable live clock */
.roundLiveClock {
  display: flex;
  align-items: baseline;
  gap: 8px;

  min-width: 224px;

  padding: 10px 13px;

  border: 1px solid #35495f;
  border-radius: 12px;

  background:
    linear-gradient(
      180deg,
      #18222d,
      #141b23
    );

  font-variant-numeric:
    tabular-nums;
}

.roundLiveClock > strong {
  color: #d6ebff;

  font-size: 29px;
  font-weight: 950;
  line-height: 1;

  letter-spacing: 0.045em;

  text-shadow:
    0 0 12px
    rgba(156, 199, 238, 0.15);
}

.roundLiveClock > span {
  color: #9cc7ee;

  font-size: 11px;
  font-weight: 950;
  line-height: 1;

  letter-spacing: 0.08em;
}


/* Right header column */
.gameHeaderTools {
  justify-self: end;

  display: grid;
  justify-items: end;
  gap: 7px;
}


/* Preserve the original button row */
.gameHeaderPolished
.gameHeaderTools
.gameHeaderActions {
  justify-self: end;

  display: flex;
  align-items: center;
  gap: 9px;
}


/* Small session-duration readout */
.sessionElapsedMini {
  display: flex;
  align-items: baseline;
  gap: 8px;

  width: fit-content;

  padding: 5px 9px;

  border: 1px solid #4a4029;
  border-radius: 9px;

  background: #151b23;

  font-variant-numeric:
    tabular-nums;
}

.sessionElapsedMini > span {
  color: #81785f;

  font-size: 7px;
  font-weight: 950;
  letter-spacing: 0.12em;
}

.sessionElapsedMini > strong {
  color: #e2bb62;

  font-size: 11px;
  font-weight: 900;
  line-height: 1;

  letter-spacing: 0.035em;
}


/* Tablet layout:
   logo remains centered on row 1,
   round + clock on lower-left,
   buttons + elapsed on lower-right. */
@media (max-width: 820px) {
  .gameRoundArea {
    grid-column: 1;
    grid-row: 2;

    justify-self: start;
  }

  .gameHeaderTools {
    grid-column: 2;
    grid-row: 2;

    justify-self: end;
  }

  .gameHeaderPolished
  .gameHeaderTools
  .gameHeaderActions {
    grid-column: auto;
    grid-row: auto;
  }

  .roundLiveClock {
    min-width: 210px;
  }

  .roundLiveClock > strong {
    font-size: 27px;
  }
}


@media (max-width: 620px) {
  .gameRoundArea {
    gap: 7px;
  }

  .roundLiveClock {
    min-width: 176px;

    padding: 8px 10px;
    gap: 6px;
  }

  .roundLiveClock > strong {
    font-size: 22px;
  }

  .roundLiveClock > span {
    font-size: 9px;
  }

  .gameHeaderPolished
  .gameHeaderTools
  .gameHeaderActions {
    gap: 5px;
  }

  .sessionElapsedMini {
    padding: 4px 7px;
  }

  .sessionElapsedMini > strong {
    font-size: 10px;
  }
}

/* =========================================
   CLOCK BOX — FIT CONTENT
   Append to the VERY BOTTOM of index.css
========================================= */

.roundLiveClock {
  width: fit-content;
  min-width: 0;

  padding-left: 13px;
  padding-right: 13px;
}

/* CLASSIC ARTETA — distinct warm red */

.awardTone-arteta {
  --award-color: #df646c;
}

/* =========================================
   CUSTOM "PLAYING AS" PICKER
   Append to the VERY BOTTOM of index.css

   Replaces the browser-native <select>
   with a JIMRAMI-styled picker.
========================================= */

.sessionAliasPicker {
  grid-column: 1 / -1;

  display: grid;
  grid-template-columns:
    auto minmax(0, 1fr);
  align-items: start;
  gap: 12px;

  padding: 10px 14px;

  border-top:
    1px solid #303a47;

  background: #121923;
}

.sessionAliasLabel {
  align-self: center;

  color: #8290a0;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.sessionAliasControl {
  display: grid;
  gap: 6px;

  min-width: 0;
}


/* SELECTED VALUE */

.sessionAliasTrigger {
  display: grid;
  grid-template-columns:
    minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;

  width: 100%;
  min-height: 42px;

  padding: 0 12px;

  border:
    1px solid #3b4858;
  border-radius: 10px;

  outline: none;

  background: #1d2631;
  color: #f4f6f8;

  text-align: left;

  transition:
    border-color 150ms ease,
    background 150ms ease,
    box-shadow 150ms ease;
}

.sessionAliasTrigger:hover {
  border-color: #50627a;
  background: #202b38;
}

.sessionAliasTrigger.open {
  border-color: #739ae0;

  background: #202b38;

  box-shadow:
    0 0 0 2px
    rgba(115, 154, 224, 0.12);
}

.sessionAliasCurrent {
  overflow: hidden;

  font-size: 14px;
  font-weight: 850;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.sessionAliasChevron {
  color: #9eb6d3;

  font-size: 12px;
  line-height: 1;
}


/* EXPANDED MENU */

.sessionAliasMenu {
  display: grid;
  gap: 4px;

  padding: 5px;

  border:
    1px solid #364454;
  border-radius: 11px;

  background: #171f29;

  box-shadow:
    0 12px 28px
    rgba(0, 0, 0, 0.28);
}

.sessionAliasOption {
  display: grid;
  grid-template-columns:
    22px minmax(0, 1fr) auto;
  align-items: center;
  gap: 9px;

  width: 100%;
  min-height: 43px;

  padding: 7px 10px;

  border: 0;
  border-radius: 8px;

  background: transparent;
  color: #dce3eb;

  text-align: left;

  transition:
    background 120ms ease,
    color 120ms ease;
}

.sessionAliasOption:hover {
  background: #222d3a;
  color: #ffffff;
}

.sessionAliasOption.selected {
  background: #26364a;
  color: #ffffff;
}

.sessionAliasCheck {
  display: grid;
  place-items: center;

  width: 22px;
  height: 22px;

  border-radius: 7px;

  color: #93baff;

  font-size: 14px;
  font-weight: 950;
}

.sessionAliasOption.selected
.sessionAliasCheck {
  background:
    rgba(115, 154, 224, 0.13);
}

.sessionAliasOption strong {
  overflow: hidden;

  font-size: 14px;
  font-weight: 850;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.sessionAliasOption small {
  color: #697889;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.1em;

  white-space: nowrap;
}

.sessionAliasOption.selected small {
  color: #92a9c6;
}


/* Disable old native-select styling if it
   remains anywhere in cached CSS. */
.sessionAliasPicker select {
  display: none;
}


/* TABLET / SMALL SCREEN */

@media (max-width: 600px) {
  .sessionAliasPicker {
    grid-template-columns: 1fr;
    gap: 6px;
  }

  .sessionAliasLabel {
    align-self: auto;
  }

  .sessionAliasTrigger {
    min-height: 44px;
  }

  .sessionAliasOption {
    min-height: 46px;
  }
}
/* =========================================
   CUSTOM PLAYING-AS PICKER — COMPACT OVERLAY
   Append to the VERY BOTTOM of index.css

   Keeps the picker compact and makes the
   option list float instead of expanding
   the whole player card.
========================================= */

.sessionAliasPicker {
  grid-template-columns:
    auto minmax(0, 1fr);

  gap: 9px;

  padding:
    7px 12px;
}

.sessionAliasControl {
  position: relative;

  gap: 0;
}

.sessionAliasTrigger {
  min-height: 36px;

  padding:
    0 10px;
}

.sessionAliasCurrent {
  font-size: 13px;
}

.sessionAliasMenu {
  position: absolute;
  top: calc(100% + 5px);
  left: 0;
  right: 0;

  z-index: 80;

  gap: 2px;

  padding: 4px;

  border-radius: 9px;

  box-shadow:
    0 14px 32px
    rgba(0, 0, 0, 0.42);
}

.sessionAliasOption {
  min-height: 36px;

  padding:
    5px 8px;

  grid-template-columns:
    20px minmax(0, 1fr) auto;

  gap: 7px;
}

.sessionAliasCheck {
  width: 20px;
  height: 20px;

  font-size: 12px;
}

.sessionAliasOption strong {
  font-size: 13px;
}

.sessionAliasOption small {
  font-size: 7px;
}


/* Keep the open menu above the next player row. */
.playerSelect:has(
  .sessionAliasTrigger.open
) {
  position: relative;

  z-index: 20;
}


/* Tablet / phone */
@media (max-width: 600px) {
  .sessionAliasPicker {
    grid-template-columns:
      auto minmax(0, 1fr);

    gap: 8px;
  }

  .sessionAliasTrigger {
    min-height: 38px;
  }

  .sessionAliasOption {
    min-height: 38px;
  }
}

/* =========================================
   PLAYING-AS DROPDOWN — CLIPPING FIX
   Append to the VERY BOTTOM of index.css
========================================= */

/*
  .playerSelect normally uses overflow:hidden
  for its rounded card shape.

  The compact nickname menu is positioned
  outside that card, so it was being clipped.
  Only allow overflow while the picker is open.
*/
.playerSelect:has(
  .sessionAliasTrigger.open
) {
  overflow: visible !important;
  position: relative;
  z-index: 100;
}

/* Keep the floating menu above following rows. */
.sessionAliasMenu {
  z-index: 200;
}

/* =========================================
   PLAYER TAB — GROUPED SORT PICKER
   Append to the VERY BOTTOM of index.css
========================================= */

.playerSortPicker {
  position: relative;

  width: min(100%, 320px);
  flex: 0 1 320px;
}

.playerSortTrigger {
  display: grid;
  grid-template-columns:
    minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;

  width: 100%;
  min-height: 44px;

  padding: 0 13px;

  border: 1px solid #364252;
  border-radius: 11px;

  background: #202832;
  color: #f3f6f9;

  text-align: left;

  transition:
    border-color 140ms ease,
    background 140ms ease,
    box-shadow 140ms ease;
}

.playerSortTrigger:hover {
  border-color: #4b5b6f;
  background: #242e3a;
}

.playerSortTrigger.open {
  border-color: #7089aa;
  background: #242e3a;

  box-shadow:
    0 0 0 2px
      rgba(112, 137, 170, 0.12);
}

.playerSortTrigger > span {
  overflow: hidden;

  font-size: 13px;
  font-weight: 850;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.playerSortTrigger > b {
  color: #97a9be;

  font-size: 12px;
  line-height: 1;
}


/* Floating menu so 12 options do not make
   the History page permanently taller. */
.playerSortMenu {
  position: absolute;
  top: calc(100% + 7px);
  right: 0;

  z-index: 300;

  width: min(360px, 88vw);
  max-height: min(540px, 68vh);
  overflow-y: auto;

  padding: 7px;

  border: 1px solid #344152;
  border-radius: 13px;

  background: #171f29;

  box-shadow:
    0 18px 46px
      rgba(0, 0, 0, 0.48);
}

.playerSortGroup {
  padding: 5px;
}

.playerSortGroup +
.playerSortGroup {
  border-top:
    1px solid #293442;
}

.playerSortGroupLabel {
  display: block;

  padding:
    5px 8px 6px;

  color: #6f7e90;

  font-size: 8px;
  font-weight: 950;
  letter-spacing: 0.13em;
}

.playerSortGroup > div {
  display: grid;
  gap: 2px;
}

.playerSortOption {
  display: grid;
  grid-template-columns:
    22px minmax(0, 1fr);
  align-items: center;
  gap: 8px;

  width: 100%;
  min-height: 38px;

  padding: 6px 9px;

  border: 0;
  border-radius: 8px;

  background: transparent;
  color: #cfd7e1;

  text-align: left;
}

.playerSortOption:hover {
  background: #222d39;
  color: #ffffff;
}

.playerSortOption.selected {
  background: #2a394b;
  color: #ffffff;
}

.playerSortCheck {
  display: grid;
  place-items: center;

  width: 22px;
  height: 22px;

  border-radius: 7px;

  color: #f0c75e;

  font-size: 13px;
  font-weight: 950;
}

.playerSortOption.selected
.playerSortCheck {
  background:
    rgba(222, 181, 88, 0.11);
}

.playerSortOption strong {
  overflow: hidden;

  font-size: 12px;
  font-weight: 800;

  text-overflow: ellipsis;
  white-space: nowrap;
}


/* Keep the dropdown above the player cards. */
.playerSortPanel {
  position: relative;
  z-index: 40;
}

.playerStatsList {
  position: relative;
  z-index: 1;
}


/* Tablet */
@media (max-width: 800px) {
  .playerSortPicker {
    width: 100%;
    flex-basis: auto;
  }

  .playerSortMenu {
    left: 0;
    right: auto;

    width: min(100%, 360px);
  }
}


/* Small phone */
@media (max-width: 520px) {
  .playerSortMenu {
    width: 100%;
  }

  .playerSortTrigger {
    min-height: 42px;
  }

  .playerSortOption {
    min-height: 40px;
  }
}

/* =========================================
   WELCOME PLAYER CARD — OPEN PICKER CORNERS
   Append to the VERY BOTTOM of index.css

   The player card must use overflow:visible
   while the custom nickname menu is open.
   That exposes the square background corners
   of the PLAYING AS row. Round that row itself
   so it still follows the card shape.
========================================= */

.playerSelect.selected
.sessionAliasPicker {
  border-radius:
    0 0 15px 15px;
}

/* Keep the same clean card silhouette
   while the floating menu is open. */
.playerSelect:has(
  .sessionAliasTrigger.open
)
.sessionAliasPicker {
  border-radius:
    0 0 15px 15px;
}

/* Slightly inset the floating menu so its
   edges visually line up with the field
   instead of fighting the outer card border. */
.playerSelect:has(
  .sessionAliasTrigger.open
)
.sessionAliasMenu {
  left: 1px;
  right: 1px;
}

/* =========================================
   SESSION HISTORY — PLAYER DETAILS
   Append to the VERY BOTTOM of index.css
========================================= */

/* Clickable session standing */
.historyStandingInteractive {
  cursor: pointer;

  outline: none;

  transition:
    background 140ms ease,
    border-color 140ms ease,
    transform 140ms ease;

  border:
    1px solid transparent;
}

.historyStandingInteractive:hover {
  background: #252e3a;

  border-color: #374558;
}

.historyStandingInteractive:focus-visible {
  border-color: #7e9fd4;

  box-shadow:
    0 0 0 2px
    rgba(126, 159, 212, 0.14);
}

.historyStandingInteractive:active {
  transform: scale(0.997);
}


/* Scoreboard-style achievements inside
   each session standing row. */
.historyStandingAchievements {
  display: flex !important;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px 10px !important;

  min-height: 18px;
  margin-top: 2px;
}

.historyStandingAchievements
.standardWinTally,
.historyStandingAchievements
.jimWinStars,
.historyStandingAchievements
.jimCatchScissors {
