  box-shadow:
    inset 0 0 0 1px
    rgba(213, 167, 56, 0.12);
}

.goalpostCustomSetup {
  display: grid;
  grid-template-columns:
    auto minmax(0, 180px) 1fr;
  align-items: center;
  gap: 10px;

  padding-top: 2px;
}

.goalpostCustomSetup input {
  min-height: 42px;

  padding: 0 12px;

  border: 1px solid #3a4656;
  border-radius: 10px;

  outline: none;

  background: #10151c;
  color: #f4f6f8;

  font: inherit;
  font-weight: 850;
}

.goalpostCustomSetup input:focus {
  border-color: #d0a13a;
}

.goalpostCustomSetup small {
  color: #b2777d;
  font-size: 10px;
}


/* ---------- ACTIVE HEADER ---------- */

.gameGoalpostChip {
  display: grid;
  grid-template-columns: auto auto;
  align-items: baseline;
  gap: 7px;

  width: fit-content;

  padding: 6px 10px;

  border: 1px solid #695522;
  border-radius: 10px;

  background: #211c10;
