}

.goalpostDialog.deuce
.goalpostEyebrow {
  color: #df8094;
}

.goalpostHeroMark {
  margin: 12px auto 2px;

  color: #d9879a;

  font-size: 38px;
  font-weight: 900;
  line-height: 1;
  text-align: center;
}

.goalpostHeroMark.crown {
  color: #e1b44b;

  font-size: 48px;
}

.goalpostDialog h2,
.goalpostDialog h1 {
  margin: 7px 0 0;

  color: #f4f6f8;

  font-size: 34px;
  line-height: 1.05;
  text-align: center;
}

.goalpostLead {
