  background: #211c10;
  color: #9c844b;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.goalpostTargetChip strong {
  color: #e3b74f;
  font-size: 13px;
}


/* Podium includes fourth place */
.goalpostPodium {
  display: grid;
  gap: 7px;
}

.goalpostPodiumRow {
  display: grid;
  grid-template-columns:
