    rgba(30, 25, 13, 0.9);
}

.raceFutureGoalpostBadge span {
  color: #9e874e;

  font-size: 8px;
  font-weight: 950;
  letter-spacing: 0.08em;
}

.raceFutureGoalpostBadge strong {
