  scrollbar-width: none;
  -ms-overflow-style: none;
}

.goalpostDialog::-webkit-scrollbar {
  width: 0;
  height: 0;
  display: none;
}


/* ---------- TABLET / PHONE ---------- */

@media (max-width: 720px) {
  .goalpostPresetGrid {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }

  .goalpostSetupHeader {
    align-items: start;
