  color: #9e8b90;

  font-size: 11px;
  line-height: 1.45;
}

.goalpostFinishConfirm
> div:last-child {
  display: grid;
  grid-template-columns:
    1fr 1.4fr;
  gap: 8px;
}

.goalpostFinishConfirm button {
  min-height: 44px;

  border-radius: 10px;

  font-size: 12px;
  font-weight: 900;
}

.goalpostFinishBack {
  border:
    1px solid #3e4855;

  background: #252d37;
  color: #b8c1cb;
}

.goalpostFinishYes {
  border:
    1px solid #7b4650;

  background: #65313b;
  color: #f5dfe4;
}

/* =========================================
   GOALPOST PODIUM — STRONGER HEIGHT / GAPS
   + LEFT-ALIGNED ACCOLADES
   Append to the VERY BOTTOM of index.css
========================================= */

/* Make the spacing change obvious. */
.goalpostPodium {
  gap: 24px !important;

  padding-top: 30px !important;
  padding-left: 8px;
  padding-right: 8px;
}


/* Taller blocks, especially 1st–4th. */
.goalpostPodiumColumn.rank-1
.goalpostPodiumStage {
  height: 245px !important;
}

.goalpostPodiumColumn.rank-2
.goalpostPodiumStage {
  height: 195px !important;
}

.goalpostPodiumColumn.rank-3
.goalpostPodiumStage {
  height: 160px !important;
}

.goalpostPodiumColumn.rank-4
.goalpostPodiumStage {
  height: 132px !important;
}

.goalpostPodiumColumn.rank-5
.goalpostPodiumStage {
  height: 116px !important;
}

.goalpostPodiumColumn.rank-6
.goalpostPodiumStage {
  height: 104px !important;
}


/* Give the inside of the podium more room. */
.goalpostPodiumStage {
  align-content: start !important;

  gap: 18px !important;

  padding:
    16px 14px 14px !important;
}


/* Rank remains centered. */
.goalpostPodiumRank {
  width: 100%;

  text-align: center;
}


/* Accolades no longer sit as one centered clump.
   Standard, Jim and Catch each get their own
   left-aligned row. */
.goalpostPodiumAccolades {
  width: 100%;

  display: flex !important;
  flex-direction: column;
  flex-wrap: nowrap !important;
  align-items: flex-start !important;
  justify-content: flex-start !important;

  gap: 10px !important;

  min-height: 0 !important;

  padding-top: 2px;
}


/* Force every accolade type to begin at the
   same left edge of the podium. */
.goalpostPodiumAccolades
.standardWinTally,
.goalpostPodiumAccolades
.jimWinStars,
.goalpostPodiumAccolades
.jimCatchScissors {
  width: auto;

  margin: 0 !important;

  justify-content: flex-start !important;
}


/* Standard tally group itself should also
   start from the left instead of centering. */
.goalpostPodiumAccolades
.tallyGroups {
  justify-content: flex-start !important;
}


/* Keep stars/scissors comfortably separated. */
.goalpostPodiumAccolades
.jimWinStars,
.goalpostPodiumAccolades
.jimCatchScissors {
  gap: 5px;
}


/* Slightly more breathing space between
   player name, score and podium block. */
.goalpostPodiumName {
  padding-bottom: 10px !important;
}

.goalpostPodiumScore {
  padding-bottom: 14px !important;
}


/* Tablet: still visibly separated, but avoid
   making the row absurdly wide. */
@media (max-width: 900px) {
  .goalpostPodium {
    gap: 18px !important;
  }
}

@media (max-width: 600px) {
  .goalpostPodium {
    gap: 14px !important;
  }
}

/* =========================================
   GOALPOST PODIUM — CENTER EACH ACCOLADE ROW
   Append to the VERY BOTTOM of index.css
========================================= */

/*
  Keep Standard / Jim / Catch on separate rows,
  but center EACH row independently.
*/
.goalpostPodiumAccolades {
  width: 100% !important;

  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: flex-start !important;

  gap: 0px !important;
}

.goalpostPodiumAccolades
.standardWinTally,
.goalpostPodiumAccolades
.jimWinStars,
.goalpostPodiumAccolades
.jimCatchScissors {
  width: 100% !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  margin: 0 !important;
}

.goalpostPodiumAccolades
.tallyGroups {
  width: 100% !important;

  justify-content: center !important;
}

/* =========================================
   GOALPOST FINISH CONFIRM — CANCEL ANIMATION FIX
   Append to the VERY BOTTOM of index.css
========================================= */

/*
  The Finish Session button is conditionally
  unmounted while the confirmation panel is open.

  When Back is pressed, the button mounts again.
  Its old 680 ms delayed entrance animation then
  replayed, which caused the awkward empty pause.

  Keep the main Goalpost popup animation, but do
  not animate this button every time it remounts.
*/
.goalpostDialog.reached
.goalpostFinishButton {
  animation: none !important;
  opacity: 1 !important;
  transform: none !important;
}


/* The confirmation itself can still enter quickly,
   so the interaction does not feel completely flat. */
.goalpostFinishConfirm {
  animation:
    goalpostFinishConfirmQuickIn
    150ms ease-out both;
}

@keyframes goalpostFinishConfirmQuickIn {
  from {
    opacity: 0;
    transform:
      translateY(4px);
  }

  to {
    opacity: 1;
    transform:
      translateY(0);
  }
}

/* =========================================
   SESSION AWARDS — WIN STREAK
   Append to the VERY BOTTOM of index.css
========================================= */

.awardTone-streak {
  --award-color: #79b8e8;
}

/* =========================================
   WIN STREAK RECORD — STREAK PATH
   Append to the VERY BOTTOM of index.css
========================================= */

.sessionRecordWinner
.winStreakPath {
  grid-column: 1 / -1;

  display: flex;
  flex-wrap: wrap;
  align-items: center;

  gap: 5px;

  width: 100%;

  margin-top: 8px;
  padding-top: 8px;

  border-top:
    1px solid rgba(
      121,
      184,
      232,
      0.12
    );
}

.winStreakPathStep {
  display: flex;
  align-items: center;
  gap: 5px;
}

.winStreakPathArrow {
  color: #566678;

  font-size: 11px;
  font-weight: 900;
}

.winStreakPathGroup {
  display: inline-flex;
  align-items: center;

  gap: 2px;

  min-height: 22px;
}


/* Standard win: repeated bars render naturally
   as ||, |||, etc. */
.winStreakStandard {
  color: #88add7;

  font-size: 18px;
  font-weight: 950;
  line-height: 1;
}


/* Catch Jim */
.winStreakCatch {
  color: #e98591;

  font-size: 17px;
  line-height: 1;
}


/* Jim win */
.winStreakJim {
  display: inline-grid;
  place-items: center;

  width: 20px;
  height: 20px;

  color: #e3b64b;

  border:
    1px solid transparent;
  border-radius: 50%;

  font-size: 14px;
  line-height: 1;
}

.winStreakJim.usedHide {
  border-color: #9a75ca;
}


/* Let longer records wrap cleanly rather than
   shrinking the symbols. */
@media (max-width: 620px) {
  .sessionRecordWinner
  .winStreakPath {
    gap: 4px;
  }

  .winStreakPathArrow {
    font-size: 10px;
  }
}

/* =========================================
   WIN STREAK PATH — COMPACT STANDARD TALLIES
   Append to the VERY BOTTOM of index.css
========================================= */

/* Consecutive Standard wins now render as one
   compact string: ||, |||, ||||, etc. */
.winStreakStandardRun {
  display: inline-block;

  color: #88add7;

  font-family: ui-monospace,
    SFMono-Regular,
    Menlo,
    Consolas,
    monospace;

  font-size: 18px;
  font-weight: 950;
  line-height: 1;

  letter-spacing: -2px;

  white-space: nowrap;
}

/* =========================================
   WIN STREAK PATH — TRUE 5-BAR TALLY
   Append to the VERY BOTTOM of index.css
========================================= */

.winStreakStandardTallies {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.winStreakTallyGroup {
  position: relative;

  display: inline-flex;
  align-items: center;
  gap: 3px;

  height: 20px;
}

.winStreakTallyMark {
  display: block;

  width: 2px;
  height: 18px;

  border-radius: 2px;

  background: #88add7;
}

/* Fifth win crosses the first four,
   matching the familiar tally-mark style. */
.winStreakTallyStrike {
  position: absolute;

  left: 0;
  top: 9px;

  width: 100%;
  height: 2px;

  border-radius: 2px;

  background: #88add7;

  transform:
    rotate(-24deg);

  transform-origin: center;
}

/* =========================================
   WIN STREAK RECORD — NAME LAYOUT FIX
   Append to the VERY BOTTOM of index.css
========================================= */

/*
  The streak path became a third flex child of
  .sessionRecordWinner, so it was stealing width
  from the player name and forcing "H...".

  Rows containing a streak path use a 2-column
  grid instead:
    name | date
    streak path across the full row
*/
.sessionRecordWinner:has(
  .winStreakPath
) {
  display: grid !important;

  grid-template-columns:
    minmax(0, 1fr) auto;

  align-items: center !important;
  column-gap: 14px !important;
  row-gap: 7px !important;
}


/* Player name keeps the full first column. */
.sessionRecordWinner:has(
  .winStreakPath
) h3 {
  width: auto !important;
  min-width: 0;

  overflow: hidden;

  text-overflow: ellipsis;
  white-space: nowrap;
}


/* Date stays compact on the right. */
.sessionRecordWinner:has(
  .winStreakPath
) > span {
  grid-column: 2;

  justify-self: end;
}


/* Streak sequence gets its own full-width row. */
.sessionRecordWinner:has(
  .winStreakPath
) .winStreakPath {
  grid-column: 1 / -1;

  width: 100%;

  margin-top: 0;
}

/* =========================================
   JIM DATA — CLOUD SYNC STATUS
   Append to the bottom of index.css
========================================= */

.cloudStatusOption {
  align-items: start;
}

.cloudStatusLine {
  display: flex;
  align-items: center;
  gap: 8px;

  margin-top: 8px;

  color: #aeb8c5;

  font-size: 14px;
  font-weight: 850;
}

.cloudStatusDot {
  font-size: 13px;
  line-height: 1;
}

.cloudStatusLine.connected {
  color: #78c89a;
}

.cloudStatusLine.pending {
  color: #d8b66a;
}

.cloudStatusLine.offline {
  color: #d58b82;
}

.cloudStatusLine.local,
.cloudStatusLine.signedOut {
  color: #8994a2;
}

.cloudStatusOption p + p {
