* {
  box-sizing: border-box;
}

:root {
  font-family:
    Inter,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;

  color: #f5f7fa;
  background: #0d1015;
  font-synthesis: none;
}

html,
body,
#root {
  width: 100%;
  min-width: 320px;
  min-height: 100%;
  margin: 0;
  overscroll-behavior-y: none;
}

body {
  background: #0d1015;
}

button,
input {
  font: inherit;
}

button {
  cursor: pointer;
}

.app {
  width: 100%;
  max-width: 1000px;
  margin: 0 auto;
  padding: 28px;
}

/* HEADER */

.setupHeader {
  display: grid;
  grid-template-columns:
    1fr auto 1fr;
  align-items: center;
  gap: 20px;
  margin-bottom: 28px;
}

.setupHeader > h1 {
  grid-column: 2;
  justify-self: center;

  margin: 0;
  font-size: 44px;
  letter-spacing: -0.045em;
  text-align: center;
}

.setupHeaderActions {
  grid-column: 3;
  justify-self: end;
}


@media (max-width: 700px) {
  .setupHeader {
    grid-template-columns:
      1fr auto;
    gap: 14px;
  }

  .setupHeader > h1 {
    grid-column: 1 / -1;
    grid-row: 1;
  }

  .setupHeaderActions {
    grid-column: 2;
    grid-row: 2;
  }
}

/* ADD PLAYER */

.addPlayer {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  margin-bottom: 24px;
}

.addPlayer input {
  min-width: 0;
  min-height: 60px;
  padding: 0 18px;
  border: 1px solid #303844;
  border-radius: 15px;
  outline: none;
  background: #171c24;
  color: white;
  font-size: 18px;
}

.addPlayer input:focus {
  border-color: #8faeff;
}

.addPlayer button {
  min-width: 140px;
  border: 0;
  border-radius: 15px;
  background: #f2f4f6;
  color: #101419;
  font-weight: 800;
}

/* PLAYER LIST */

.playerLibrary {
  display: grid;
  gap: 11px;
}

.emptyPlayers {
  padding: 30px;
  border: 1px dashed #303844;
  border-radius: 16px;
  color: #7f8997;
  text-align: center;
}

.playerSelect {
  display: grid;
  grid-template-columns: 1fr 94px;
  min-height: 78px;
  overflow: hidden;
  border: 2px solid #272e38;
  border-radius: 17px;
  background: #171c24;
}

.playerSelect.selected {
  border-color: #8faeff;
  background: #1b2230;
}

.playerSelectMain {
  display: grid;
  grid-template-columns: 48px 1fr auto;
  align-items: center;
  gap: 14px;
  min-width: 0;
  padding: 14px 18px;
  border: 0;
  background: transparent;
  color: white;
  text-align: left;
}

.playerSelectMain strong {
  overflow: hidden;
  font-size: 21px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.playerSelectMain > span {
  color: #778493;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.playerSelect.selected .playerSelectMain > span {
  color: #aebcce;
}

.selectionNumber {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border: 1px solid #38414e;
  border-radius: 11px;
  color: #8b96a5;
  font-weight: 900;
}

.playerSelect.selected .selectionNumber {
  background: #f3f5f7;
  color: #101419;
}

.deletePlayer {
  border: 0;
  border-left: 1px solid #29313c;
  background: transparent;
  color: #687382;
  font-size: 25px;
}

.deletePlayer:hover {
  color: white;
}

/* SESSION SUMMARY */

.sessionSummary {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-top: 22px;
}

.sessionSummary > div {
  padding: 17px;
  border: 1px solid #272e38;
  border-radius: 15px;
  background: #13171d;
}

.sessionSummary span {
  display: block;
  margin-bottom: 5px;
  color: #778392;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.sessionSummary strong {
  font-size: 27px;
}

/* START */

.startSession {
  width: 100%;
  min-height: 72px;
  margin-top: 16px;
  border: 0;
  border-radius: 17px;
  background: #f2f4f6;
  color: #101419;
  font-size: 18px;
  font-weight: 850;
}

.startSession:disabled {
  background: #242a33;
  color: #606b78;
  cursor: not-allowed;
}

@media (max-width: 600px) {
  .app {
    padding: 18px;
  }

  .addPlayer {
    grid-template-columns: 1fr;
  }

  .addPlayer button {
    min-height: 56px;
  }

  .playerSelectMain {
    grid-template-columns: 42px 1fr;
  }

  .playerSelectMain > span {
    grid-column: 2;
  }
}
/* ---------- ACTIVE GAME ---------- */

.gameHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 28px;
}

.gameHeader h1 {
  margin: 0 0 8px;
  font-size: 48px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.gameRound {
  color: #808b99;
  font-size: 17px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.endSession {
  min-height: 48px;
  padding: 0 18px;
  border: 1px solid #39414c;
  border-radius: 13px;
  background: transparent;
  color: #aab3be;
  font-weight: 750;
}

.gameScoreboard {
  display: grid;
  gap: 10px;
}

.standingRow {
  position: relative;

  display: grid;
  grid-template-columns:
    54px minmax(0, 1fr) 105px;
  align-items: center;

  min-height: 104px;
  padding: 16px 22px;

  border: 1px solid #282f39;
  border-radius: 18px;
  background: #171c24;

  transition:
    border-color 160ms ease,
    background 160ms ease;
}

.standingRank {
  display: grid;
  place-items: center;

  width: 38px;
  height: 38px;

  border-radius: 11px;

  background: #202731;
  color: #8390a0;

  font-size: 18px;
  font-weight: 950;
}

.standingPlayer {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.standingPlayer > div {
  min-width: 0;
}

.standingPlayer h2 {
  margin: 0;
  font-size: 27px;
}

.standingPlayer p {
  margin: 6px 0 0;

  color: #758293;

  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.035em;
}

.standingPoints {
  display: grid;
  justify-items: end;
  align-content: center;
  gap: 2px;
}

.standingPoints strong {
  font-size: 49px;
  line-height: 0.9;
}

.standingPoints span {
  color: #7a8796;

  font-size: 9px;
  font-weight: 950;
  letter-spacing: 0.12em;
}

.gameWaiting {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;

  min-height: 56px;
  margin-top: 12px;
  padding: 13px 18px;

  border: 1px solid #2b3440;
  border-radius: 13px;
  background: #151b22;
}

.gameWaiting span {
  color: #778596;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.gameWaiting strong {
  color: #edf2f7;
  font-size: 14px;
  text-align: right;
}

.gameActions {
  display: grid !important;
  grid-template-columns:
    repeat(3, minmax(0, 1fr)) !important;

  gap: 10px !important;
  margin-top: 20px;
}

.gameActions button {
  min-height: 76px;
  border: 0;
  border-radius: 18px;
  background: #f2f4f6;
  color: #101419;
  font-size: 18px;
  font-weight: 850;
}

.gameActions .jimAction {
  background: #d9ae4b;
}

.gameActions button:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.nextFeature {
  margin: 12px 0 0;
  color: #626d79;
  font-size: 12px;
  text-align: center;
}

@media (max-width: 600px) {
  .standingRow {
    grid-template-columns:
