.roundPlayers {
  display: grid;
  grid-template-columns:
    1fr 1fr;
  gap: 12px;
}

.roundPlayerCard {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;

  width: 100%;
  min-height: 125px;

  padding: 20px;

  border: 2px solid #282f39;
  border-radius: 18px;

  background: #171c24;
  color: white;

  text-align: left;
}

.roundPlayerCard.active {
  border-color: #8faeff;
  background: #1c2330;
}

.roundPlayerCard strong {
  font-size: 23px;
}

.roundPlayerScore {
  min-width: 60px;
  text-align: right;
  font-size: 42px;
  font-weight: 850;
