}

/* TIE DIALOG */

.tieOverlay {
  position: fixed;
  inset: 0;
  z-index: 50;

  display: grid;
  place-items: center;

  padding: 24px;

  background:
    rgba(5, 7, 10, 0.84);
}

.tieDialog {
  width: min(
    100%,
    470px
  );

  padding: 28px;

  border: 1px solid #323b47;
