}

.tieLabel {
  color: #d9ae4b;

  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.tieDialog h2 {
  margin: 8px 0 4px;
  font-size: 32px;
}

.tieDialog p {
  margin: 0 0 20px;
  color: #9aa5b3;
}

.tieChoices {
  display: grid;
  gap: 10px;
}

.tieChoices button {
  min-height: 64px;

  border: 1px solid #323b47;
  border-radius: 14px;

  background: #222a35;
  color: white;

  font-size: 19px;
  font-weight: 800;
}

@media (max-width: 760px) {
  .roundEntryLayout {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .roundPlayers {
    grid-template-columns: 1fr;
  }
}

/* ==============================
   TITLE RACE
================================ */

.raceAction {
  background: #2d3541 !important;
  color: #f5f7fa !important;
}

.racePage {
  max-width: 1200px;
}

.raceHeader {
  display: grid;
  grid-template-columns:
    auto 1fr auto;
  align-items: center;
  gap: 18px;
  margin-bottom: 22px;
}

.raceHeader > div > span {
  color: #7e8998;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.raceHeader h1 {
  margin: 3px 0 0;
  font-size: 34px;
}

.racePlay {
