}

.raceSpeed:active {
  background: #252d39;
}

/* ==============================
   DATA / BACKUP
================================ */

.gameHeaderActions,
.setupHeaderActions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.dataButton {
  min-height: 48px;
  padding: 0 18px;

  border: 1px solid #39414c;
  border-radius: 13px;

  background: #171c24;
