/* ==============================
   TABLET QUICK-RANK DRAG FIX
   Prevent browser pull-to-refresh
   from stealing reorder gestures.
================================ */

/*
  JIMRAMI is an app-like interface.
  Native pull-to-refresh is more
  harmful than useful here.
*/
/*
  The entire Quick Rank interaction
  belongs to the reorder gesture,
  not page scrolling.
*/
.quickRankPanel,
.quickRankList,
.quickRankItem,
.quickRankCard {
  touch-action: none !important;
  overscroll-behavior: none;
}

/*
  Avoid long-press text/image selection
  while dragging on Android.
*/
.quickRankList,
.quickRankItem,
.quickRankCard {
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
}

/* ==============================
   SCOREBOARD — LAST WINNER,
   TALLIES, JIM STARS & STATUS
================================ */

/* ---------- PREVIOUS WINNER ---------- */

.previousWinnerBar {
  display: grid;
  grid-template-columns:
    minmax(150px, auto)
    minmax(0, 1fr)
    38px;
  align-items: center;
  gap: 18px;

  margin-bottom: 12px;
  padding: 11px 15px;

  border:
    1px solid #343c47;
  border-radius: 13px;

  background:
    linear-gradient(
      90deg,
      #151b22,
      #12171d
    );
}

.previousWinnerLabel {
  display: grid;
  gap: 2px;
}

.previousWinnerLabel > span {
  color: #7d8997;

  font-size: 9px;
  font-weight: 950;
  letter-spacing: 0.11em;
}

.previousWinnerLabel > small {
  color: #65717f;

  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.04em;
}

.previousWinnerBar > strong {
  overflow: hidden;

  color: #f2f5f8;

  font-size: 18px;
  font-weight: 950;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.previousWinnerIcon {
  display: grid;
  place-items: center;

  width: 32px;
  height: 32px;

  border-radius: 10px;

  font-size: 15px;
  font-weight: 950;
}

.previousWinnerIcon.standard {
  background: #1c2b3a;
  color: #83b9e8;
}

.previousWinnerIcon.jim {
  background: #332a16;
  color: #e2b64e;
}

/* ---------- PLAYING / WAITING ---------- */

.playerStatusTag {
  flex: 0 0 auto;

  padding: 5px 8px;

  border-radius: 7px;

  font-size: 8px;
  font-weight: 950;
  letter-spacing: 0.1em;
}

.playerStatusTag.playing {
  border:
    1px solid #28533a;

  background: #183324;
  color: #72cf93;
}

.playerStatusTag.waiting {
  border:
    1px solid #5a4920;

  background: #342a16;
  color: #e2bd61;
}

/* ---------- ACHIEVEMENTS ---------- */

.standingAchievements {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 11px;

  min-height: 22px;
  margin-top: 6px;
}

.standardWinTally {
  display: flex;
  align-items: center;
  gap: 7px;

  min-width: 0;
}

.winMetaLabel {
  color: #718092;

  font-size: 8px;
  font-weight: 950;
  letter-spacing: 0.08em;
}

.tallyGroups {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
}

.tallyGroup {
  position: relative;

  display: flex;
  align-items: center;
  gap: 3px;

  height: 18px;
  min-width: 4px;
}

.tallyMark {
  display: block;

  width: 2px;
  height: 15px;

  border-radius: 2px;

  background: #8fb7df;

  transform:
    rotate(-2deg);
}

.tallyStrike {
  position: absolute;
  top: 8px;
  left: -2px;

  display: block;

  width: 22px;
  height: 2px;

  border-radius: 2px;

  background: #8fb7df;

  transform:
    rotate(-31deg);
  transform-origin: center;
}

.jimWinStars {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2px;

  max-width: 170px;

  line-height: 1;
}

.jimWinStars > span {
  color: #e3b64b;

  font-size: 15px;

  filter:
    drop-shadow(
      0 0 4px
      rgba(227, 182, 75, 0.15)
    );
}

/* ---------- SMALLER SCREENS ---------- */

@media (max-width: 620px) {
  .previousWinnerBar {
    grid-template-columns:
      1fr auto;
    gap: 8px 12px;
  }

  .previousWinnerLabel {
    grid-column: 1;
  }

  .previousWinnerBar > strong {
    grid-column: 1;
    grid-row: 2;

    font-size: 17px;
  }

  .previousWinnerIcon {
    grid-column: 2;
    grid-row: 1 / 3;
  }

  .standingAchievements {
    gap: 8px;
  }

  .winMetaLabel {
    font-size: 7px;
  }

  .tallyMark {
    height: 13px;
  }

  .tallyGroup {
    height: 16px;
  }

  .tallyStrike {
    top: 7px;

    width: 20px;
  }

  .jimWinStars > span {
    font-size: 13px;
  }

  .playerStatusTag {
    padding: 4px 6px;

    font-size: 7px;
  }
}

/* ==============================
   SCORE TRANSITION — CURRENT
================================ */

/* Kill visual leftovers from the
   previous transition experiment. */
.cleanTransitionPage {
  gap: 20px;
}

.cleanTransitionHeader {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;

  margin-bottom: 18px;
}

.cleanTransitionHeader > div {
  display: grid;
  gap: 4px;
}

.cleanTransitionHeader span {
  color: #758398;

  font-size: 10px;
  font-weight: 950;
  letter-spacing: 0.12em;
}

.cleanTransitionHeader h1 {
  margin: 0;

  color: #f4f7fb;

  font-size: 42px;
  font-weight: 1000;
  line-height: 1;
}

.cleanTransitionHeader button {
  min-height: 40px;
  padding: 0 14px;

  border: 1px solid #364252;
  border-radius: 11px;

  background: #202936;
  color: #eef3f8;

  font-size: 11px;
  font-weight: 900;
}

/* ---------- BOARD ---------- */

.cleanTransitionBoard {
  position: relative;

  width: 100%;
}

.cleanTransitionRow {
  position: absolute;
  left: 0;
  right: 0;

  box-sizing: border-box;

  display: grid;
  grid-template-columns:
    50px
    minmax(0, 1fr)
    92px;

  align-items: center;
  gap: 16px;

  height: 94px;
  padding: 15px 20px;

  overflow: visible;

  border: 1px solid #2a3441;
  border-radius: 17px;

  background: #171e27;

  transition:
    top 900ms
      cubic-bezier(
        0.22,
        1,
        0.36,
        1
      ),
    border-color
      300ms ease,
    transform
      300ms ease;
}

.cleanTransitionRow.settled {
  border-color: #344151;
}

.cleanTransitionRank {
  color: #8291a5;

  font-size: 23px;
  font-weight: 950;

  text-align: center;
}

.cleanTransitionMain {
  min-width: 0;
}

.cleanTransitionNameLine {
  display: flex;
  align-items: center;
  gap: 9px;

  min-width: 0;
}

.cleanTransitionNameLine h2 {
  margin: 0;

  overflow: hidden;

  color: #f6f8fb;

  font-size: 22px;
  font-weight: 950;

  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---------- STATUS ---------- */

.cleanTransitionPage
.playerStatusTag {
  flex: 0 0 auto;

  padding: 4px 7px;

  border-radius: 7px;

  font-size: 7px;
  font-weight: 950;
  letter-spacing: 0.09em;
}

.cleanTransitionPage
.playerStatusTag.playing {
  border: 1px solid #28533a;

  background: #183324;
  color: #72cf93;
}

.cleanTransitionPage
.playerStatusTag.waiting {
  border: 1px solid #5a4920;

  background: #342a16;
  color: #e2bd61;
}

/* ---------- ACHIEVEMENTS ---------- */

.cleanTransitionMeta {
  display: flex;
  align-items: center;
  gap: 9px;

  min-height: 17px;
  margin-top: 6px;
}

.scoreTally {
  display: flex;
  align-items: center;
  gap: 5px;
}

.scoreTallyGroup {
  position: relative;

  display: flex;
  align-items: center;
  gap: 3px;

  height: 16px;
}

.scoreTallyMark {
  display: block;

  width: 2px;
  height: 13px;

  border-radius: 2px;

  background: #8eb7e0;
}

.scoreTallyStrike {
  position: absolute;
  top: 7px;
  left: -2px;

  width: 20px;
  height: 2px;

  border-radius: 2px;

  background: #8eb7e0;

  transform:
    rotate(-31deg);
}

.scoreJimStars {
  display: flex;
  align-items: center;
  gap: 2px;
}

.scoreJimStars > span {
  color: #e3b64b;

  font-size: 13px;
  line-height: 1;
}

.scoreTally.pop,
.scoreJimStars.pop {
  animation:
    achievementPop
    650ms
    cubic-bezier(
      0.22,
      1.4,
      0.36,
      1
    );
}

@keyframes achievementPop {
  0% {
    transform:
      scale(0.72);
    opacity: 0.35;
  }

  60% {
    transform:
      scale(1.18);
    opacity: 1;
  }

  100% {
    transform:
      scale(1);
    opacity: 1;
  }
}

/* ---------- POINTS ---------- */

.cleanTransitionPoints {
  display: grid;
  justify-items: end;
  align-content: center;
  gap: 2px;
}

.cleanTransitionPoints strong {
  color: #f4f7fa;

  font-size: 44px;
  font-weight: 1000;
  line-height: 0.9;
}

.cleanTransitionPoints span {
  color: #8290a2;

  font-size: 8px;
  font-weight: 950;
  letter-spacing: 0.1em;
}

/* ---------- REWARD POP ---------- */

.cleanRewardBubble {
  position: absolute;
  top: 10px;
  right: 104px;
  z-index: 5;

  display: flex;
  align-items: center;
  gap: 7px;

  padding: 5px 9px;

  border-radius: 10px;

  pointer-events: none;

  animation:
    rewardIn
      300ms ease-out,
    rewardOut
      600ms ease-in
      7.0s forwards;
}

.cleanRewardBubble.gain {
  border: 1px solid #2c6546;

  background: #183a29;
  color: #83d7a1;
}

.cleanRewardBubble.loss {
  border: 1px solid #71404a;

  background: #41242a;
  color: #ef99a4;
}

.cleanRewardBubble strong {
  font-size: 17px;
  font-weight: 1000;
  line-height: 1;
}

.rewardTally {
  color: #9cc3ea;

  font-size: 17px;
  font-weight: 1000;
  line-height: 1;
}

.rewardStar {
  color: #e3b64b;

  font-size: 15px;
  line-height: 1;
}

@keyframes rewardIn {
  from {
    opacity: 0;
    transform:
      translateY(5px)
      scale(0.88);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }
}

@keyframes rewardOut {
  to {
    opacity: 0;
    transform:
      translateY(-8px)
      scale(0.96);
  }
}

/* ---------- TABLET ---------- */

@media (
  max-width: 700px
) {
  .cleanTransitionHeader h1 {
    font-size: 35px;
  }

  .cleanTransitionRow {
    grid-template-columns:
      38px
      minmax(0, 1fr)
      70px;

    gap: 9px;

    padding:
      13px 12px;
  }

  .cleanTransitionRank {
    font-size: 18px;
  }

  .cleanTransitionNameLine h2 {
    font-size: 18px;
  }

  .cleanTransitionPoints strong {
    font-size: 35px;
  }

  .cleanRewardBubble {
    right: 76px;
  }
}

/* Very small phones: stack History tabs only when truly necessary. */
@media (max-width: 420px) {
  .historyTabs {
    grid-template-columns:
      1fr;
  }
}

* {
  box-sizing: border-box;
}

:root {
  font-family:
    Inter,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;

  color: #f5f7fa;
  background: #0d1015;
  font-synthesis: none;
}

html,
body,
#root {
  width: 100%;
  min-width: 320px;
  min-height: 100%;
  margin: 0;
  overscroll-behavior-y: none;
}

body {
  background: #0d1015;
}

button,
input {
  font: inherit;
}

button {
  cursor: pointer;
}

.app {
  width: 100%;
  max-width: 1000px;
  margin: 0 auto;
  padding: 28px;
}

/* HEADER */

.setupHeader {
  display: grid;
  grid-template-columns:
    1fr auto 1fr;
  align-items: center;
  gap: 20px;
  margin-bottom: 28px;
}

.setupHeader > h1 {
  grid-column: 2;
  justify-self: center;

  margin: 0;
  font-size: 44px;
  letter-spacing: -0.045em;
  text-align: center;
}

.setupHeaderActions {
  grid-column: 3;
  justify-self: end;
}


@media (max-width: 700px) {
  .setupHeader {
    grid-template-columns:
      1fr auto;
    gap: 14px;
  }

  .setupHeader > h1 {
    grid-column: 1 / -1;
    grid-row: 1;
  }

  .setupHeaderActions {
    grid-column: 2;
    grid-row: 2;
  }
}

/* ADD PLAYER */

.addPlayer {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  margin-bottom: 24px;
}

.addPlayer input {
  min-width: 0;
  min-height: 60px;
  padding: 0 18px;
  border: 1px solid #303844;
  border-radius: 15px;
  outline: none;
  background: #171c24;
  color: white;
  font-size: 18px;
}

.addPlayer input:focus {
  border-color: #8faeff;
}

.addPlayer button {
  min-width: 140px;
  border: 0;
  border-radius: 15px;
  background: #f2f4f6;
  color: #101419;
  font-weight: 800;
}

/* PLAYER LIST */

.playerLibrary {
  display: grid;
  gap: 11px;
}

.emptyPlayers {
  padding: 30px;
  border: 1px dashed #303844;
  border-radius: 16px;
  color: #7f8997;
  text-align: center;
}

.playerSelect {
  display: grid;
  grid-template-columns: 1fr 94px;
  min-height: 78px;
  overflow: hidden;
  border: 2px solid #272e38;
  border-radius: 17px;
  background: #171c24;
}

.playerSelect.selected {
  border-color: #8faeff;
  background: #1b2230;
}

.playerSelectMain {
  display: grid;
  grid-template-columns: 48px 1fr auto;
  align-items: center;
  gap: 14px;
  min-width: 0;
  padding: 14px 18px;
  border: 0;
  background: transparent;
  color: white;
  text-align: left;
}

.playerSelectMain strong {
  overflow: hidden;
  font-size: 21px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.playerSelectMain > span {
  color: #778493;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.playerSelect.selected .playerSelectMain > span {
  color: #aebcce;
}

.selectionNumber {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border: 1px solid #38414e;
  border-radius: 11px;
  color: #8b96a5;
  font-weight: 900;
}

.playerSelect.selected .selectionNumber {
  background: #f3f5f7;
  color: #101419;
}

.deletePlayer {
  border: 0;
  border-left: 1px solid #29313c;
  background: transparent;
  color: #687382;
  font-size: 25px;
}

.deletePlayer:hover {
  color: white;
}

/* SESSION SUMMARY */

.sessionSummary {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-top: 22px;
}

.sessionSummary > div {
  padding: 17px;
  border: 1px solid #272e38;
  border-radius: 15px;
  background: #13171d;
}

.sessionSummary span {
  display: block;
  margin-bottom: 5px;
  color: #778392;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.sessionSummary strong {
  font-size: 27px;
}

/* START */

.startSession {
  width: 100%;
  min-height: 72px;
  margin-top: 16px;
  border: 0;
  border-radius: 17px;
  background: #f2f4f6;
  color: #101419;
  font-size: 18px;
  font-weight: 850;
}

.startSession:disabled {
  background: #242a33;
  color: #606b78;
  cursor: not-allowed;
}

@media (max-width: 600px) {
  .app {
    padding: 18px;
  }

  .addPlayer {
    grid-template-columns: 1fr;
  }

  .addPlayer button {
    min-height: 56px;
  }

  .playerSelectMain {
    grid-template-columns: 42px 1fr;
  }

  .playerSelectMain > span {
    grid-column: 2;
  }
}
/* ---------- ACTIVE GAME ---------- */

.gameHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 28px;
}

.gameHeader h1 {
