}

.penaltyPlayer {
  display: flex;
  align-items: center;
  justify-content: space-between;

  min-height: 84px;
  padding: 15px 20px;

  border: 1px solid #303844;
  border-radius: 16px;

  background: #171c24;
  color: white;

  text-align: left;
}

.penaltyPlayer > div {
  display: grid;
  gap: 5px;
}

.penaltyPlayer strong {
  font-size: 22px;
  font-weight: 700;
}

.penaltyPlayer span {
  color: #858f9c;

  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.penaltyPlayer b {
  font-size: 30px;
}

.penaltyPlayer:active {
  transform: scale(0.985);
}

.penaltyAction {
  background: #47272b !important;
  color: #f1a0a7 !important;
}


/* ==============================
   JIM ROUND
================================ */

.jimRoundPage {
  width: 100%;
  max-width: 1000px;
  margin: 0 auto;
}

.jimPanel {
  width: 100%;
  max-width: 760px;
  margin: 0 auto;

  display: grid;
  gap: 24px;
}

/* ---------- HEADINGS ---------- */

.jimSectionTitle,
.jimCurrentPlayer,
.jimWinTitle {
  display: grid;
  gap: 5px;
}

.jimSectionTitle span,
.jimCurrentPlayer span,
.jimWinTitle > span {
  color: #8290a2;

  font-size: 11px;
  font-weight: 700;

  letter-spacing: 0.08em;
}

.jimSectionTitle h2,
.jimCurrentPlayer h2,
.jimWinTitle h2 {
  margin: 0;

  color: #f5f7fa;

  font-size: 30px;
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

/* ---------- PLAYER CHOICES ---------- */

.jimPlayerChoices {
  width: 100%;

  display: grid !important;

  grid-template-columns:
    repeat(2, minmax(0, 1fr)) !important;

  gap: 12px !important;
}

.jimPlayerChoice {
  width: 100% !important;
  min-width: 0 !important;

  min-height: 82px;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 14px 18px;

  border: 1px solid #303946 !important;
  border-radius: 16px !important;

  background: #171d25 !important;
  color: #f5f7fa !important;

  font: inherit;
  font-size: 22px !important;
  font-weight: 700 !important;

  text-align: center;

  cursor: pointer;
}

.jimPlayerChoice:hover {
  background: #1d242e !important;
}

.jimPlayerChoice:active {
  transform: scale(0.985);
}

.jimPlayerChoice.selected {
  border-color: #d5ad53 !important;

  background: #332c1f !important;
  color: #f3ce77 !important;
}

/* ---------- PROGRESS ---------- */

.jimProgress {
  width: 100%;

  padding: 24px 20px 22px;

  border: 1px solid #2b333e;
  border-radius: 22px;

  background: #151a21;
}

.jimProgressTop {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  gap: 8px;
  margin-bottom: 22px;

  text-align: center;
}

.jimProgressTop span {
  color: #8290a2;

  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.jimProgressTop strong {
  color: #f5f7fa;

  font-size: 38px;
  line-height: 1;
}

/* ---------- SIX JIM STAGES ---------- */

.jimStages {
  width: 100%;

  display: grid !important;

  grid-template-columns:
    repeat(6, minmax(0, 1fr)) !important;

  gap: 12px !important;

  justify-items: center;
  align-items: start;
  padding-bottom: 20px;
}

.jimStage {
  position: relative;

  width: 72px;
  height: 72px;
  min-width: 72px;
  min-height: 72px;

  display: grid;
  place-items: center;

  border: 2px solid #303946;
  border-radius: 999px;

  background: #10151b;
  color: #697585;

  font-size: 22px;
  font-weight: 700;

  box-shadow:
    inset 0 0 0 1px rgba(255,255,255,0.02);
}

.jimStage.survived {
  border-color: #315940;

  background: #1e3828;
  color: #8fd6a3;
}

.jimStage.current {
  border-color: #d6ae55;

  background: #2b2417;
  color: #f1cc74;
}

.jimStage.hidden {
  border-color: #9171c1;

  background: #302640;
  color: #caadf0;
}

.jimStage small {
  position: absolute;

  left: 50%;
  bottom: -18px;

  transform: translateX(-50%);

  padding: 2px 6px;

  border-radius: 999px;

  background: #5a4680;
  color: #f1e9ff;

  text-align: center;

  font-size: 8px;
  font-weight: 900;
  line-height: 1;

  letter-spacing: 0.08em;
  white-space: nowrap;
}
/* ---------- HIDE ---------- */

.jimHideArea {
  width: 100%;
}

.jimHideButton {
  width: 100% !important;

  min-height: 68px;

  border: 1px solid #8867b7 !important;
  border-radius: 15px !important;

  background: #2c233c !important;
  color: #cbb0ef !important;

  font: inherit;
  font-size: 17px !important;
  font-weight: 700 !important;

  letter-spacing: 0.04em;
}

.jimHideButton:disabled {
  border-color: #2b333e !important;

  background: #171c23 !important;
  color: #606c7b !important;
}

.jimHideUsed {
  width: 100%;
  min-height: 68px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 20px;

  border: 1px solid #8867b7;
  border-radius: 15px;

  background: #2c233c;
  color: #cbb0ef;
}

.jimHideUsed span {
  font-size: 11px;
  font-weight: 900;

  letter-spacing: 0.1em;
}

.jimHideUsed strong {
  font-size: 21px;
}

/* ---------- MAIN JIM BUTTONS ---------- */

.jimMainActions {
  width: 100%;

  display: grid !important;

  grid-template-columns:
    2fr 1fr !important;

  gap: 12px !important;
}

.jimSurvivedButton,
.jimCaughtButton,
.jimConfirmButton {
  width: 100% !important;

  min-height: 70px;

  border: 0 !important;
  border-radius: 15px !important;

  font: inherit;
  font-size: 17px !important;
  font-weight: 700 !important;

  cursor: pointer;
}

.jimSurvivedButton {
  background: #f0f2f5 !important;
  color: #101318 !important;
}

.jimCaughtButton {
  background: #47272c !important;
  color: #f1a0a8 !important;
}

/* ---------- RESULT SUMMARY ---------- */

.jimOutcomeSummary {
  width: 100%;

  display: grid !important;

  grid-template-columns:
    repeat(4, minmax(0, 1fr)) !important;

  gap: 10px !important;
}

.jimOutcomeSummary > div {
  min-width: 0;

  padding: 16px;

  border: 1px solid #29313b;
  border-radius: 14px;

  background: #151a21;
}

.jimOutcomeSummary span {
  display: block;

  margin-bottom: 6px;

  color: #7f8b9a;

  font-size: 9px;
  font-weight: 900;

  letter-spacing: 0.09em;
}

.jimOutcomeSummary strong {
  display: block;

  color: #f5f7fa;

  font-size: 22px;
}

/* ---------- CONFIRM ---------- */

.jimConfirmButton {
  background: #eef1f5 !important;
  color: #101318 !important;
}

.jimConfirmButton:disabled {
  opacity: 0.4;
}

.jimWinConfirm {
  background: #d2ab50 !important;
  color: #17130b !important;
}

/* ---------- WIN ---------- */

.jimWinTitle > strong {
  margin-top: 4px;

  color: #d8b45d;

  font-size: 48px;
  line-height: 1;
}

/* ---------- ROTATION NOTE ---------- */

.jimRotationNote {
  margin: 0;

  color: #909ba8;

  font-size: 15px;
}

/* ---------- SMALLER SCREENS ---------- */

@media (max-width: 600px) {
  .jimPanel {
    gap: 18px;
  }

  .jimPlayerChoices {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }

  .jimPlayerChoice {
    min-height: 72px;

    font-size: 19px !important;
  }

  .jimStages {
    gap: 5px !important;
  }

.jimStage {
  width: 56px;
  height: 56px;
  min-width: 56px;
  min-height: 56px;

  font-size: 18px;
}
  .jimOutcomeSummary {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }

  .jimMainActions {
    grid-template-columns: 1fr !important;
  }
}

/* ==============================
   HISTORY & STATS
================================ */

.historyPage {
  max-width: 1100px;
}

.historyHeader {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-bottom: 26px;
}

.historyHeader > div > span {
  color: #7f8997;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.historyHeader h1 {
  margin: 3px 0 0;
  font-size: 34px;
}

.historyTabs {
  display: grid;
  grid-template-columns:
    repeat(4, 1fr);
  gap: 7px;

  margin-bottom: 22px;
  padding: 6px;

  border-radius: 16px;
  background: #13171d;
}

.historyTabs button {
  min-height: 52px;

  border: 0;
  border-radius: 12px;

  background: transparent;
  color: #7f8997;

  font-weight: 800;
}

.historyTabs button.active {
  background: #29323e;
  color: #f5f7fa;
}

/* SESSION HISTORY */

.historySessionList {
  display: grid;
  gap: 12px;
}

.historySession {
  overflow: hidden;

  border: 1px solid #29313b;
  border-radius: 18px;

  background: #171c24;
}

.historySessionSummary {
  width: 100%;
  min-height: 88px;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  padding: 16px 20px;

  border: 0;

  background: transparent;
  color: #f5f7fa;

  text-align: left;
}

.historySessionSummary > div:first-child {
  display: grid;
  gap: 4px;
}

.historySessionSummary > div:first-child strong {
  font-size: 20px;
}

.historySessionSummary > div:first-child span,
.historySessionSummaryRight > span {
  color: #8793a1;
  font-size: 13px;
}

.historySessionSummaryRight {
  display: flex;
  align-items: center;
  gap: 12px;
}

.historySessionSummaryRight b {
  padding: 5px 8px;

  border-radius: 7px;

  background: #29323d;
  color: #9eabb9;

  font-size: 10px;
  letter-spacing: 0.08em;
}

.historySessionSummaryRight b.active {
  background: #20372a;
  color: #81d499;
}

.historySessionDetails {
  padding: 18px 20px 20px;

  border-top: 1px solid #29313b;
}

.historySessionMeta {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 9px;

  margin-bottom: 16px;
}

.historySessionMeta > div {
  min-width: 0;

  padding: 14px;

  border-radius: 13px;

  background: #11151b;
}

.historySessionMeta span {
  display: block;

  margin-bottom: 5px;

  color: #778392;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.historySessionMeta strong {
  display: block;

  overflow: hidden;

  font-size: 18px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.historyStandings {
  display: grid;
  gap: 7px;
}

.historyStanding {
  display: grid;
  grid-template-columns:
    38px minmax(0, 1fr) auto;
  align-items: center;

  min-height: 62px;

  padding: 8px 14px;

  border-radius: 12px;

  background: #202731;
}

.historyStanding > span {
  color: #788391;
  font-weight: 850;
}

.historyStanding > div {
  display: grid;
  gap: 3px;

  min-width: 0;
}

.historyStanding > div > strong {
  overflow: hidden;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.historyStanding small {
  color: #8994a2;
}

.historyStanding > b {
  font-size: 22px;
}

.historyRaceButton {
  width: 100%;
  min-height: 58px;

  margin-top: 14px;

  border: 0;
  border-radius: 14px;

  background: #303946;
  color: #f5f7fa;

  font-weight: 850;
}

.historyEmpty {
  padding: 50px 20px;

  border: 1px dashed #303844;
  border-radius: 17px;

  color: #7f8997;

  text-align: center;
}

/* PLAYER STATS */

.playerStatsList {
  display: grid;
  gap: 14px;
}

.playerStatsCard {
  padding: 20px;

  border: 1px solid #29313b;
  border-radius: 18px;

  background: #171c24;
}

.playerStatsCard > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  margin-bottom: 18px;
}

.playerStatsCard > header > div {
  display: grid;
  gap: 3px;
}

.playerStatsCard h2 {
  margin: 0;

  font-size: 27px;
}

.playerStatsCard > header span {
  color: #8994a2;
  font-size: 13px;
}

.playerStatsCard > header > strong {
  font-size: 21px;
}

.playerStatSectionLabel {
  margin: 17px 2px 8px;

  color: #7c8795;

  font-size: 14px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.playerStatGrid {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.playerStatGrid > div {
  min-width: 0;

  padding: 14px;

  border-radius: 13px;

  background: #11151b;
}

.playerStatGrid span {
  display: block;

  min-height: 24px;
  margin-bottom: 5px;

  color: #778392;

  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.07em;
}

.playerStatGrid strong {
  font-size: 23px;
}

.hideStageBreakdown {
  display: grid;
  grid-template-columns:
    auto repeat(4, 1fr);
  align-items: center;
  gap: 8px;

  margin-top: 10px;
  padding: 11px 13px;

  border: 1px solid #3c3250;
  border-radius: 13px;

  background: #1d1827;
}

.hideStageBreakdown > span {
  color: #a891c5;

  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.hideStageBreakdown > div {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 5px;
}

.hideStageBreakdown small {
  color: #8f7ba8;
  font-size: 11px;
}

.hideStageBreakdown strong {
  color: #d0b7ef;
}

/* AWARDS */

.historyAwards {
  display: grid;
  gap: 18px;
}

.awardsIntro {
  padding: 5px 2px 2px;
}

.awardsIntro > span {
  color: #d9ae4b;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.awardsIntro h2 {
  margin: 5px 0 6px;

  font-size: 31px;
}

.awardsIntro p {
  max-width: 620px;
  margin: 0;

  color: #8994a2;
  line-height: 1.5;
}

.awardGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.awardCard {
  min-width: 0;

  padding: 20px;

  border: 1px solid #303844;
  border-radius: 18px;

  background: #171c24;
}

.awardCard > span {
  color: #d9ae4b;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.awardCard h3 {
  margin: 8px 0 4px;

  overflow-wrap: anywhere;

  font-size: 27px;
}

.awardCard > strong {
  color: #b5c0cd;

  font-size: 15px;
}

.awardCard p {
  margin: 11px 0 0;

  color: #7f8b99;

  font-size: 13px;
  line-height: 1.4;
}

@media (max-width: 700px) {
  .historySessionMeta {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .playerStatSectionLabel {
    font-size: 13px;
  }

  .playerStatGrid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .playerStatGrid span,
  .hideStageBreakdown > span {
    font-size: 11px;
  }

  .awardGrid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .historySessionSummary {
    align-items: flex-start;
  }

  .historySessionSummaryRight {
    flex-direction: column;
    align-items: flex-end;
    gap: 5px;
  }

  .hideStageBreakdown {
    grid-template-columns:
      1fr 1fr;
  }

  .hideStageBreakdown > span {
    grid-column: 1 / -1;
  }
}


/* ==============================
   SESSION AWARDS
================================ */

.sessionAwardsSection {
  margin-top: 20px;
  padding-top: 18px;

  border-top: 1px solid #29313b;
}

.sessionAwardsHeader {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;

  margin-bottom: 12px;
}

.sessionAwardsHeader span {
  color: #d9ae4b;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.sessionAwardsHeader strong {
  color: #8994a2;

  font-size: 13px;
}

.sessionAwardGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 9px;
}

.sessionAwardCard {
  padding: 15px;

  background: #141920;
}

.sessionAwardCard > span {
  font-size: 9px;
}

.sessionAwardCard h3 {
  margin: 6px 0 3px;

  font-size: 21px;
}

.sessionAwardCard > strong {
  font-size: 13px;
}

.sessionAwardCard p {
  margin-top: 8px;

  font-size: 12px;
}

@media (max-width: 600px) {
  .sessionAwardGrid {
    grid-template-columns: 1fr;
  }

  .sessionAwardsHeader {
    align-items: flex-start;
    flex-direction: column;
    gap: 3px;
  }
}

/* ==============================
   AWARD COLORS + BIGGER TITLES
   History / Session Awards CSS.
================================ */

.awardCard {
  --award-color: #d9ae4b;

  border-left:
    4px solid var(--award-color);
}

.awardCard > span {
  color: var(--award-color);

  font-size: 15px;
  font-weight: 950;
  letter-spacing: 0.08em;
}

.awardCard > strong {
  color: var(--award-color);
}

/* Session cards are smaller overall,
   but the award name should still
   be obvious at a glance. */

.sessionAwardCard > span {
  font-size: 13px;
}

.sessionAwardCard h3 {
  font-size: 23px;
}

/* Each family title gets its own
   stable visual identity. */

.awardTone-cuci {
  --award-color: #6fc8d4;
}

.awardTone-slayer {
  --award-color: #ef7f89;
}

.awardTone-tuah {
  --award-color: #e0b65c;
}

.awardTone-malang {
  --award-color: #b491df;
}

.awardTone-standard {
  --award-color: #79a7f2;
}

.awardTone-jim {
  --award-color: #e79a61;
}

.awardTone-hide {
  --award-color: #bd8fe9;
}

.awardTone-denda {
  --award-color: #e88b9c;
}

.awardTone-survivor {
  --award-color: #7fcf95;
}

.awardTone-comeback {
  --award-color: #67c5b3;
}

.awardTone-jatuh {
  --award-color: #d7838f;
}

.awardTone-default {
  --award-color: #aab5c2;
}

@media (max-width: 600px) {
  .awardCard > span {
    font-size: 14px;
  }

  .sessionAwardCard > span {
    font-size: 12px;
  }
}

/* ==============================
   HISTORY V3
   History / Awards CSS.
================================ */

/* SESSION DETAILS */

.historySessionMetaExpanded {
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
}

/* PLAYER SORTING */

.playerSortPanel {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;

  margin-bottom: 14px;
  padding: 16px 18px;

  border: 1px solid #29313b;
  border-radius: 16px;

  background: #151a21;
}

.playerSortPanel > div:first-child {
  display: grid;
  gap: 3px;

  flex: 0 0 auto;
}

.playerSortPanel > div:first-child span {
  color: #788493;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.playerSortPanel > div:first-child strong {
  font-size: 17px;
}

.playerSortButtons {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 7px;
}

.playerSortButtons button {
  min-height: 38px;
  padding: 0 12px;

  border: 1px solid #303945;
  border-radius: 10px;

  background: #202630;
  color: #8f9aa7;

  font-size: 11px;
  font-weight: 850;
}

.playerSortButtons button.active {
  border-color: #59697d;

  background: #344152;
  color: #f5f7fa;
}

.playerStatsIdentity {
