    linear-gradient(
      135deg,
      rgba(222, 181, 88, 0.12),
      rgba(17, 21, 27, 0.78)
    );
}

.playerStatsHeadline.sortStatHighlight
strong {
  color: #f0c75e;
}

.playerStatsHeadline.sortStatHighlight
span {
  color: #c7a755;
}

/* ==============================
   MVP TAB
================================ */

.mvpPage {
  display: grid;
  gap: 18px;
}

.mvpIntro {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 30px;

  padding: 4px 2px 2px;
}

.mvpIntro > div:first-child > span {
  color: #e0b65c;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.mvpIntro h2 {
  margin: 5px 0 6px;

  font-size: 31px;
}

.mvpIntro p {
  max-width: 650px;
  margin: 0;

  color: #8994a2;
  line-height: 1.5;
}

.mvpFormula {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, auto));
  gap: 6px 14px;

  padding: 14px 16px;

  border: 1px solid #303844;
  border-radius: 14px;

  background: #151a21;
}

.mvpFormula > span {
  grid-column: 1 / -1;

  color: #7c8795;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.mvpFormula strong {
  color: #c9d2dc;

  font-size: 12px;
}

.mvpEligibility {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 22px;

  padding: 14px 16px;

  border: 1px solid #3a3322;
  border-radius: 14px;

  background: #1b1913;
}

.mvpEligibility span {
  flex: 0 0 auto;

  color: #d9ae4b;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.mvpEligibility p {
  margin: 0;

  color: #9a8d6c;

  font-size: 12px;
  line-height: 1.45;
  text-align: right;
}

.mvpLeaderboard {
  display: grid;
  gap: 13px;
}

.mvpCard {
  padding: 20px;

  border: 1px solid #2d3641;
  border-radius: 18px;

  background: #171c24;
}

.mvpCard.mvpLeader {
  border-color: #5d4d27;

  box-shadow:
    inset 4px 0 0 #d9ae4b;
}

.mvpCard > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  margin-bottom: 16px;
}

.mvpIdentity {
  display: flex;
  align-items: center;
  gap: 13px;
}

.mvpIdentity > span {
  display: grid;
  place-items: center;

  width: 42px;
  height: 42px;

  border-radius: 12px;

  background: #252d37;
  color: #9aa6b5;

  font-size: 13px;
  font-weight: 900;
}

.mvpIdentity h3 {
  margin: 0 0 3px;

  font-size: 26px;
}

.mvpIdentity small {
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.09em;
}

.mvpProvisional {
  color: #c99963;
}

.mvpQualified {
  color: #75c895;
}

.mvpScore {
  display: grid;
  justify-items: end;
}

.mvpScore strong {
  color: #e0b65c;

  font-size: 36px;
  line-height: 1;
}

.mvpScore span {
  margin-top: 3px;

  color: #9d8245;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.mvpComponents {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.mvpComponents > div {
  min-width: 0;

  padding: 14px;

  border-radius: 13px;

  background: #11151b;
}

.mvpComponents span {
  display: block;

  margin-bottom: 5px;

  color: #788493;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.09em;
}

.mvpComponents strong {
  display: block;

  margin-bottom: 4px;

  font-size: 23px;
}

.mvpComponents small {
  color: #7f8b99;

  font-size: 10px;
  line-height: 1.35;
}

.mvpSample {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;

  margin-top: 11px;
}

.mvpSample span {
  padding: 5px 8px;

  border-radius: 8px;

  background: #222a34;
  color: #8d99a7;

  font-size: 10px;
  font-weight: 800;
}

.mvpMethodNote {
  padding: 15px 17px;

  border: 1px solid #2c3540;
  border-radius: 14px;

  background: #131820;
}

.mvpMethodNote strong {
  color: #9aa6b5;

  font-size: 10px;
  letter-spacing: 0.09em;
}

.mvpMethodNote p {
  margin: 6px 0 0;

  color: #778493;

  font-size: 12px;
  line-height: 1.5;
}

@media (max-width: 850px) {
  .mvpIntro {
    align-items: flex-start;
    flex-direction: column;
  }

  .mvpComponents {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .mvpEligibility {
    align-items: flex-start;
    flex-direction: column;
  }

  .mvpEligibility p {
    text-align: left;
  }
}

@media (max-width: 600px) {
  .historyTabs {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .mvpComponents {
    grid-template-columns: 1fr;
  }

  .mvpCard > header {
    align-items: flex-start;
  }

  .mvpScore strong {
    font-size: 30px;
  }
}

