.standardModeBar > div {
  display: grid;
  gap: 3px;
}

.standardModeBar > div > span {
  color: #7f8b99;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.standardModeBar > div > strong {
  font-size: 16px;
}

.standardModeButton {
  flex: 0 0 auto;

  min-height: 40px;
  padding: 0 14px;

  border: 1px solid #3a4552;
  border-radius: 10px;

  background: #252d38;
