.quickRankPanel {
  position: relative;

  max-width: 760px;
  margin: 0 auto 18px;
}

.quickRankList {
  display: grid;

  margin: 0;
  padding: 0;

  list-style: none;
}

.quickRankItem {
  position: relative;

  margin: 0;
  padding: 0;

  list-style: none;

  touch-action: none;
}

.quickRankCard {
  display: grid;
  grid-template-columns:
    54px minmax(0, 1fr) auto 30px;
  align-items: center;
  gap: 13px;

  min-height: 84px;
  padding: 12px 16px;

  border: 1px solid #303a46;
  border-radius: 16px;

  background: #1a2028;

  cursor: grab;
  user-select: none;
}

.quickRankCard:active {
  cursor: grabbing;
}

.quickRankNumber {
  display: grid;
  place-items: center;

  width: 42px;
  height: 42px;

  border-radius: 12px;

  background: #252e39;
  color: #9ba8b6;

  font-size: 17px;
  font-weight: 950;
}

.quickRankPlayer {
  display: grid;
  gap: 3px;

  min-width: 0;
}

.quickRankPlayer strong {
  overflow: hidden;

  font-size: 22px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.quickRankPlayer span {
  color: #778493;

  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.quickRankPoints {
  display: grid;
  justify-items: end;
}

.quickRankPoints strong {
  font-size: 25px;
}

.quickRankPoints span {
  color: #788493;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.quickRankDrag {
  color: #647181;

  font-size: 20px;
  font-weight: 900;
}

/*
  The small divider between cards is
  the "connect these two" control.
*/
.rankTieConnector {
  position: relative;
  z-index: 3;

  display: grid;
  place-items: center;

  width: calc(100% - 36px);
  height: 24px;
  margin: -1px 18px;

  border: 0;

  background: transparent;
}

.rankTieConnector::before {
  content: '';

  position: absolute;

  left: 0;
  right: 0;
  top: 50%;

  height: 1px;

  background: #27303a;
}

.rankTieConnector > span {
  position: relative;
  z-index: 1;

  display: grid;
  place-items: center;

  min-width: 30px;
  height: 20px;
  padding: 0 7px;

  border: 1px solid #34404d;
  border-radius: 999px;

  background: #11161c;
  color: #7e8997;

  font-size: 10px;
  font-weight: 950;
  letter-spacing: 0.05em;
}

.rankTieConnector.active {
  height: 30px;

  margin-top: -4px;
  margin-bottom: -4px;

  border-right: 2px solid #856fd0;
  border-left: 2px solid #856fd0;

  background:
    rgba(133, 111, 208, 0.08);
}

.rankTieConnector.active::before {
  background: #856fd0;
}

.rankTieConnector.active > span {
  border-color: #856fd0;

  background: #302747;
  color: #c9b8f3;
}

.quickRankCard.tiedWithNext,
.quickRankCard.tiedWithPrevious {
  border-color: #6757a1;

  background:
    linear-gradient(
      90deg,
      rgba(116, 91, 180, 0.08),
      #1a2028 45%
    );
}

.quickRankCard.tiedWithNext {
  border-bottom-right-radius: 8px;
  border-bottom-left-radius: 8px;
}

.quickRankCard.tiedWithPrevious {
  border-top-right-radius: 8px;
  border-top-left-radius: 8px;
}

.quickRankCard.tiedWithNext
.quickRankPlayer span,
.quickRankCard.tiedWithPrevious
.quickRankPlayer span {
  color: #aa98db;
}

.quickRankHint {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 16px;

  margin-top: 13px;

  color: #74808e;

  font-size: 10px;
  font-weight: 750;
}

.quickRankToast {
  position: sticky;
  bottom: 18px;
  z-index: 10;

  width: fit-content;
  max-width: calc(100% - 24px);

  margin: 14px auto 0;
  padding: 9px 13px;

  border: 1px solid #5d4b8d;
  border-radius: 999px;

  background: #251f34;
  color: #cdbcf3;

  font-size: 11px;
  font-weight: 850;
  text-align: center;
}

/* The old exact-score mode remains
   secondary, not the default. */

.nextScorePlayer:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

@media (max-width: 620px) {
  .standardModeBar {
    align-items: flex-start;
    flex-direction: column;
  }

  .standardModeButton {
    width: 100%;
  }

  .quickRankCard {
    grid-template-columns:
      44px minmax(0, 1fr) auto 24px;

    min-height: 76px;
    padding: 10px 12px;
  }

  .quickRankNumber {
    width: 36px;
    height: 36px;

    font-size: 15px;
  }

  .quickRankPlayer strong {
    font-size: 18px;
  }

  .quickRankPoints strong {
    font-size: 21px;
  }
}

/* ==============================
   PENALTY CONFIRMATION MODAL
================================ */

.penaltyConfirmOverlay {
  position: fixed;
  inset: 0;
  z-index: 1000;

  display: grid;
  place-items: center;

  padding: 22px;

  background: rgba(5, 8, 12, 0.76);
  backdrop-filter: blur(8px);
}

.penaltyConfirmDialog {
  width: min(100%, 520px);
  padding: 28px;

  border: 1px solid #4a3035;
  border-radius: 22px;

  background: #171c24;

  box-shadow:
    0 24px 70px rgba(0, 0, 0, 0.45);
}

.penaltyConfirmLabel {
  color: #dc7d87;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.penaltyConfirmDialog h2 {
  margin: 8px 0 22px;

  font-size: 30px;
  line-height: 1.15;
}

.penaltyConfirmPoints {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 12px;

  margin-bottom: 22px;
}

.penaltyConfirmPoints > div:not(
  .penaltyConfirmArrow
) {
  padding: 16px;

  border-radius: 14px;

  background: #11151b;
}

.penaltyConfirmPoints span {
  display: block;

  margin-bottom: 5px;

  color: #7e8997;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.penaltyConfirmPoints strong {
  font-size: 30px;
}

.penaltyConfirmArrow {
  color: #697583;

  font-size: 22px;
  font-weight: 900;
}

.penaltyConfirmActions {
  display: grid;
  grid-template-columns: 1fr 1.4fr;
  gap: 10px;
}

.penaltyConfirmActions button {
  min-height: 58px;

  border-radius: 14px;

  font-size: 15px;
  font-weight: 850;
}

.penaltyCancelButton {
  border: 1px solid #39434f;

  background: #232a33;
  color: #b5bfca;
}

.penaltyConfirmButton {
  border: 0;

  background: #6a3037;
  color: #f4dfe2;
}

.penaltyConfirmButton:hover {
  background: #793740;
}

.penaltyConfirmActions button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

@media (max-width: 520px) {
  .penaltyConfirmDialog {
    padding: 22px;
  }

  .penaltyConfirmDialog h2 {
    font-size: 25px;
  }

  .penaltyConfirmActions {
    grid-template-columns: 1fr;
  }
}

/* ==============================
   MAIN SCOREBOARD POLISH
================================ */

/* ---------- HEADER ---------- */

.gameHeader.gameHeaderPolished {
  display: grid;
  grid-template-columns:
    minmax(190px, 1fr)
    auto
    minmax(190px, 1fr);

  align-items: center;
