  font-size: 45px !important;
  font-weight: 950;
  line-height: 1 !important;
  letter-spacing: -0.045em !important;
}

.gameHeaderPolished
.gameHeaderActions {
  justify-self: end;

  display: flex;
  align-items: center;
  gap: 9px;
}

.gameHeaderPolished
.gameHeaderActions button {
  min-height: 46px;
  padding: 0 17px;

  border-radius: 13px;

  font-size: 13px;
  font-weight: 800;
}

/* ---------- SCOREBOARD ---------- */

.standingRow.leader {
  border-color: #4b4330;

  background:
    linear-gradient(
      90deg,
      rgba(215, 174, 81, 0.075),
      #171c24 25%
    );
}

.standingRow.leader::before {
  content: '';

  position: absolute;
  top: 17px;
  bottom: 17px;
  left: -1px;

  width: 4px;

  border-radius: 0 999px 999px 0;

  background: #d9ae4b;
}

.standingRow.leader
.standingRank {
  background: #342d1e;
