}

.standingNameLine {
  display: flex;
  align-items: center;
  gap: 10px;

  min-width: 0;
}

.standingNameLine h2 {
  margin: 0;

  overflow: hidden;

  font-size: 26px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---------- WAITING ---------- */

.gameWaiting {
  min-height: 56px;

  margin-top: 12px;
  padding: 13px 18px;

  border-radius: 13px;
}

.gameWaiting span {
  font-size: 10px;
}

.gameWaiting strong {
  color: #aeb8c4;

  font-size: 14px;
}

/* ---------- MAIN ACTIONS ---------- */

.gameActions > button {
  min-height: 72px;

  border-radius: 17px;

  font-size: 17px;
  font-weight: 900;
}

.gameActions .penaltyAction {
  grid-column: 3;

  justify-self: end;

  width: min(100%, 185px);
  min-height: 48px;

  margin-top: 2px;

  border-radius: 13px;

  font-size: 13px;
}

/* ---------- NEW SESSION BRAND ---------- */

/* ---------- TABLET / MOBILE ---------- */

@media (max-width: 820px) {
  .gameHeader.gameHeaderPolished {
    grid-template-columns:
      1fr auto;
    gap: 16px;
  }

  .gameBrand {
    grid-column: 1 / -1;
    grid-row: 1;

    justify-self: center;
  }

  .gameRoundHero {
    grid-column: 1;
    grid-row: 2;
  }

