   Append to the VERY BOTTOM of index.css

   - Standard result: drag to reorder
   - Jim result: custom choice buttons
========================================= */

/* ---------- STANDARD: DRAG RANKING ---------- */

.roundEditDragList {
  display: grid;
  gap: 7px;

  margin: 0;
  padding: 0;

  list-style: none;
}

.roundEditDragItem {
  margin: 0;
  padding: 0;

  list-style: none;

  cursor: grab;
  user-select: none;
  -webkit-user-select: none;
}

.roundEditDragItem:active {
  cursor: grabbing;
}

.roundEditDragRow {
  display: grid;
  grid-template-columns:
    32px minmax(0, 1fr) 38px;
  align-items: center;
  gap: 10px;

  min-height: 50px;
  padding: 7px 9px 7px 12px;

  border: 1px solid #34404c;
  border-radius: 11px;

  background: #161c23;

  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.02);
}

.roundEditDragItem:active
.roundEditDragRow {
  border-color: #5b6b7d;

  background: #1d252f;

  box-shadow:
    0 10px 28px
    rgba(0, 0, 0, 0.3);
}

.roundEditDragPosition {
  display: grid;
  place-items: center;

  width: 26px;
  height: 26px;

  border-radius: 8px;

  background: #222b35;
  color: #9ca9b7;

  font-size: 11px;
  font-weight: 900;
}

.roundEditDragRow > strong {
  overflow: hidden;

  color: #edf1f4;

  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.roundEditDragHandle {
  display: grid;
  place-items: center;

  width: 34px;
  height: 34px;

  border: 1px solid #3e4a57;
  border-radius: 9px;

  background: #222a34;
  color: #aab6c2;

  font-size: 16px;
  font-weight: 900;
}

.roundEditDragHint {
  margin-top: -3px;

  color: #6f7c89;

  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.025em;
}

/* ---------- JIM: CUSTOM CHOICE CONTROLS ---------- */

.roundEditChoiceField {
  display: grid;
  gap: 7px;
}

.roundEditChoiceField > span {
  color: #7f8b99;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.roundEditChoiceGrid {
  display: grid;
  grid-template-columns:
    repeat(
      auto-fit,
      minmax(120px, 1fr)
    );
  gap: 7px;
}

.roundEditChoiceGrid button,
.roundEditNumberChoices button,
.roundEditHideChoices button {
  min-height: 42px;
  padding: 0 12px;

  border: 1px solid #38434f;
  border-radius: 10px;

  background: #1c232c;
  color: #9da9b6;

  font: inherit;
  font-size: 11px;
  font-weight: 850;

  transition:
    border-color 120ms ease,
    background 120ms ease,
    color 120ms ease,
    transform 120ms ease;
}

.roundEditChoiceGrid button:hover,
.roundEditNumberChoices button:hover,
.roundEditHideChoices button:hover {
  border-color: #536273;

  background: #232c36;
  color: #dce2e8;
}

.roundEditChoiceGrid button:active,
.roundEditNumberChoices button:active,
.roundEditHideChoices button:active {
  transform: translateY(1px);
}

/* Generic selected state */
.roundEditChoiceGrid button.active,
.roundEditNumberChoices button.active,
.roundEditHideChoices button.active {
  border-color: #637487;

  background: #2a3542;
  color: #eef2f5;

  box-shadow:
    inset 0 0 0 1px
    rgba(255, 255, 255, 0.025);
}

/* Catcher selection */
.roundEditChoiceGrid button.active.caught {
  border-color: #754852;

  background: #3a242a;
  color: #ef98a2;
}

/* Hide selection */
.roundEditHideChoices button.active.hide {
  border-color: #765a98;

  background: #30253f;
  color: #d8baf5;
}

/* 0–5 stages */
.roundEditNumberChoices {
  display: grid;
  grid-template-columns:
    repeat(6, minmax(0, 1fr));
  gap: 6px;
}

.roundEditNumberChoices button {
  padding: 0;

  font-size: 13px;
}

/* No Hide + stages 2–5 */
.roundEditHideChoices {
  display: grid;
  grid-template-columns:
    repeat(5, minmax(0, 1fr));
  gap: 6px;
}

/* ---------- SMALL SCREENS ---------- */

@media (max-width: 620px) {
  .roundEditDragRow {
    grid-template-columns:
      30px minmax(0, 1fr) 36px;

    min-height: 48px;
  }

  .roundEditChoiceGrid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .roundEditNumberChoices {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }

  .roundEditHideChoices {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .roundEditHideChoices
  button:first-child {
    grid-column: 1 / -1;
  }
}

/* =========================================
   ROUND EDITOR — QUICK-RANK STYLE TIES
   Append to the VERY BOTTOM of index.css
========================================= */

/* Let the connector occupy the gap between
   the ranking cards. */
.roundEditDragList {
  gap: 0 !important;
}

.roundEditDragItem {
  display: grid;
  padding-bottom: 7px;
}

.roundEditDragItem.hasTieConnector {
  padding-bottom: 0;
}

/* The small divider between positions is
   now the tie control, matching Quick Rank. */
.roundEditTieConnector {
  position: relative;
  z-index: 3;

  display: grid;
  place-items: center;

  width: calc(100% - 36px);
  height: 24px;
  margin: -1px 18px;
  padding: 0;

  border: 0;

  background: transparent;

  cursor: pointer;
  touch-action: manipulation;
}

.roundEditTieConnector::before {
  content: '';

  position: absolute;
  left: 0;
  right: 0;
  top: 50%;

  height: 1px;

  background: #27303a;
}

.roundEditTieConnector > span {
  position: relative;
  z-index: 1;

  display: grid;
  place-items: center;

  min-width: 30px;
  height: 20px;
  padding: 0 7px;

  border: 1px solid #34404d;
  border-radius: 999px;

  background: #11161c;
  color: #7e8997;

  font-size: 10px;
  font-weight: 950;
  letter-spacing: 0.05em;
}

.roundEditTieConnector:hover > span {
  border-color: #526071;
  color: #a8b3c0;
}

/* Active tie: same purple connector language
   as the normal Standard Quick Rank screen. */
.roundEditTieConnector.active {
  height: 30px;
  margin-top: -4px;
  margin-bottom: -4px;

  border-right: 2px solid #856fd0;
  border-left: 2px solid #856fd0;

  background: rgba(133, 111, 208, 0.08);
}

.roundEditTieConnector.active::before {
  background: #856fd0;
}

.roundEditTieConnector.active > span {
  border-color: #856fd0;

  background: #302747;
  color: #c9b8f3;
}

/* Highlight the two cards belonging to the
   active tie. */
.roundEditDragRow.tiedWithNext,
.roundEditDragRow.tiedWithPrevious {
  border-color: #6757a1;

  background:
    linear-gradient(
      90deg,
      rgba(116, 91, 180, 0.08),
      #161c23 45%
    );
}

.roundEditDragRow.tiedWithNext {
  border-bottom-right-radius: 8px;
  border-bottom-left-radius: 8px;
}

.roundEditDragRow.tiedWithPrevious {
  border-top-right-radius: 8px;
  border-top-left-radius: 8px;
}

.roundEditDragRow.tiedWithNext
.roundEditDragPosition,
.roundEditDragRow.tiedWithPrevious
.roundEditDragPosition {
  background: #302747;
  color: #c9b8f3;
}

/* Replace the old one-line hint with the
   compact Quick Rank-style legend. */
.roundEditDragHint {
  display: flex !important;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 16px;

  margin-top: 7px !important;

  color: #74808e;

  font-size: 10px !important;
  font-weight: 750 !important;
}

@media (max-width: 620px) {
  .roundEditTieConnector {
    width: calc(100% - 24px);
    margin-right: 12px;
    margin-left: 12px;
  }

  .roundEditDragHint {
    gap: 5px 12px;
  }
}

/* =========================================
   SCOREBOARD — JIM WIN STAR / HIDE MARKER
   Append to the VERY BOTTOM of index.css

   Gold star = Jim win
   Purple ring = Hide was used for that win
   No ring = hideless Jim win
========================================= */

.jimWinStars {
  gap: 3px !important;
}

.jimWinStars > .jimWinStar {
  display: inline-grid;
  place-items: center;

  width: 21px;
  height: 21px;

  box-sizing: border-box;

  border: 1px solid transparent;
  border-radius: 50%;

  color: #e3b64b;

  font-size: 14px;
  line-height: 1;

  filter:
    drop-shadow(
      0 0 4px
      rgba(227, 182, 75, 0.15)
    );
}

/* Jim win where Hide was used. */
.jimWinStars >
.jimWinStar.usedHide {
  border-color: #8d6ac0;

  background:
    rgba(141, 106, 192, 0.07);

  box-shadow:
    inset 0 0 0 1px
      rgba(141, 106, 192, 0.08),
    0 0 5px
      rgba(141, 106, 192, 0.15);
}

/* Keep identical dimensions so stars
   remain perfectly aligned. */
.jimWinStars >
.jimWinStar.hideless {
  border-color: transparent;
}

@media (max-width: 620px) {
  .jimWinStars >
  .jimWinStar {
    width: 19px;
    height: 19px;

    font-size: 13px;
  }
}

/* =========================================
   JIM HIDE MARKERS — TRANSITION + PREVIOUS WINNER
   Append to the VERY BOTTOM of index.css

   Gold star only = hideless Jim
   Gold star + purple ring = Hide used
========================================= */

/* ---------- SCORE TRANSITION ---------- */

.scoreJimStars {
  gap: 3px !important;
}

.scoreJimStars >
.scoreJimStar {
  display: inline-grid;
  place-items: center;

  width: 19px;
  height: 19px;

  box-sizing: border-box;

  border: 1px solid transparent;
  border-radius: 50%;

  color: #e3b64b;

  font-size: 13px;
  line-height: 1;
}

.scoreJimStars >
.scoreJimStar.usedHide {
  border-color: #8d6ac0;

  background:
    rgba(141, 106, 192, 0.07);

  box-shadow:
    inset 0 0 0 1px
      rgba(141, 106, 192, 0.08),
    0 0 5px
      rgba(141, 106, 192, 0.14);
}

/* Reward bubble shown when a fresh Jim win
   is awarded during the transition. */
.rewardStar {
  display: inline-grid;
  place-items: center;

  width: 21px;
  height: 21px;

  box-sizing: border-box;

  border: 1px solid transparent;
  border-radius: 50%;
}

.rewardStar.usedHide {
  border-color: #8d6ac0;

  background:
    rgba(141, 106, 192, 0.08);

  box-shadow:
    0 0 5px
      rgba(141, 106, 192, 0.15);
}

/* ---------- PREVIOUS ROUND WINNER ---------- */

/* Keep the existing gold Jim appearance.
   Only add purple language when that Jim
   round used Hide. */
.previousWinnerIcon.jim.usedHide {
  border: 1px solid #8d6ac0;

  box-shadow:
    inset 0 0 0 1px
      rgba(141, 106, 192, 0.08),
    0 0 6px
      rgba(141, 106, 192, 0.16);
}

@media (max-width: 620px) {
  .scoreJimStars >
  .scoreJimStar {
    width: 18px;
    height: 18px;

    font-size: 12px;
  }

  .rewardStar {
    width: 20px;
    height: 20px;
  }
}

/* ==============================
   JIMRAMI IN-APP DIALOGS
================================ */

.jimDialogOverlay {
  position: fixed;
  inset: 0;
  z-index: 220;

  display: grid;
  place-items: center;

  padding: 22px;

  background:
    rgba(4, 6, 9, 0.7);
}

.jimDialog {
  width: min(
    100%,
    420px
  );

  padding: 24px;

  border: 1px solid #39414c;
  border-radius: 20px;

  background: #202731;
  color: #f2f4f6;

  box-shadow:
    0 24px 70px
    rgba(0, 0, 0, 0.45);
}

.jimDialog h3 {
  margin: 0;

  font-size: 22px;
}

.jimDialog p {
  margin: 12px 0 0;

  color: #a4adba;

  font-size: 15px;
  line-height: 1.5;
  white-space: pre-line;
}

.jimDialogActions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;

  margin-top: 24px;
}

.jimDialogActions button {
  min-width: 96px;
  min-height: 46px;

  padding: 0 16px;

  border-radius: 13px;

  cursor: pointer;
  font-weight: 850;
}

.jimDialogPrimary {
  border: 0;

  background: #f2f4f6;
  color: #101419;
}

.jimDialogSecondary {
  border: 1px solid #3a4350;

  background: #171c24;
  color: #f2f4f6;
}

@media (max-width: 520px) {
  .jimDialogActions {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .jimDialogActions button {
    width: 100%;
  }
}

* {
  box-sizing: border-box;
}

:root {
  font-family:
    Inter,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;

  color: #f5f7fa;
  background: #0d1015;
  font-synthesis: none;
}

html,
body,
#root {
  width: 100%;
  min-width: 320px;
  min-height: 100%;
  margin: 0;
  overscroll-behavior-y: none;
}

body {
  background: #0d1015;
}

button,
input {
  font: inherit;
}

button {
  cursor: pointer;
}

.app {
  width: 100%;
  max-width: 1000px;
  margin: 0 auto;
  padding: 28px;
}

/* HEADER */

.setupHeader {
  display: grid;
  grid-template-columns:
    1fr auto 1fr;
  align-items: center;
  gap: 20px;
  margin-bottom: 28px;
}

.setupHeader > h1 {
  grid-column: 2;
  justify-self: center;

  margin: 0;
  font-size: 44px;
  letter-spacing: -0.045em;
  text-align: center;
}

.setupHeaderActions {
  grid-column: 3;
  justify-self: end;
}


@media (max-width: 700px) {
  .setupHeader {
    grid-template-columns:
      1fr auto;
    gap: 14px;
  }

  .setupHeader > h1 {
    grid-column: 1 / -1;
    grid-row: 1;
  }

  .setupHeaderActions {
    grid-column: 2;
    grid-row: 2;
  }
}

/* ADD PLAYER */

.addPlayer {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  margin-bottom: 24px;
}

.addPlayer input {
  min-width: 0;
  min-height: 60px;
  padding: 0 18px;
  border: 1px solid #303844;
  border-radius: 15px;
  outline: none;
  background: #171c24;
  color: white;
  font-size: 18px;
}

.addPlayer input:focus {
  border-color: #8faeff;
}

.addPlayer button {
  min-width: 140px;
  border: 0;
  border-radius: 15px;
  background: #f2f4f6;
  color: #101419;
  font-weight: 800;
}

/* PLAYER LIST */

.playerLibrary {
  display: grid;
  gap: 11px;
}

.emptyPlayers {
  padding: 30px;
  border: 1px dashed #303844;
  border-radius: 16px;
  color: #7f8997;
  text-align: center;
}

.playerSelect {
  display: grid;
  grid-template-columns: 1fr 94px;
  min-height: 78px;
  overflow: hidden;
  border: 2px solid #272e38;
  border-radius: 17px;
  background: #171c24;
}

.playerSelect.selected {
  border-color: #8faeff;
  background: #1b2230;
}

.playerSelectMain {
  display: grid;
  grid-template-columns: 48px 1fr auto;
  align-items: center;
  gap: 14px;
  min-width: 0;
  padding: 14px 18px;
  border: 0;
  background: transparent;
  color: white;
  text-align: left;
}

.playerSelectMain strong {
  overflow: hidden;
  font-size: 21px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.playerSelectMain > span {
  color: #778493;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.playerSelect.selected .playerSelectMain > span {
  color: #aebcce;
}

.selectionNumber {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border: 1px solid #38414e;
  border-radius: 11px;
  color: #8b96a5;
  font-weight: 900;
}

.playerSelect.selected .selectionNumber {
  background: #f3f5f7;
  color: #101419;
}

.deletePlayer {
  border: 0;
  border-left: 1px solid #29313c;
  background: transparent;
  color: #687382;
  font-size: 25px;
}

.deletePlayer:hover {
  color: white;
}

/* SESSION SUMMARY */

.sessionSummary {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-top: 22px;
}

.sessionSummary > div {
  padding: 17px;
  border: 1px solid #272e38;
  border-radius: 15px;
  background: #13171d;
}

.sessionSummary span {
  display: block;
  margin-bottom: 5px;
  color: #778392;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.sessionSummary strong {
  font-size: 27px;
}

/* START */

.startSession {
  width: 100%;
  min-height: 72px;
  margin-top: 16px;
  border: 0;
  border-radius: 17px;
  background: #f2f4f6;
  color: #101419;
  font-size: 18px;
  font-weight: 850;
}

.startSession:disabled {
  background: #242a33;
  color: #606b78;
  cursor: not-allowed;
}

@media (max-width: 600px) {
  .app {
    padding: 18px;
  }

  .addPlayer {
    grid-template-columns: 1fr;
  }

  .addPlayer button {
    min-height: 56px;
  }

  .playerSelectMain {
    grid-template-columns: 42px 1fr;
  }

  .playerSelectMain > span {
    grid-column: 2;
  }
}
/* ---------- ACTIVE GAME ---------- */

.gameHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 28px;
}

.gameHeader h1 {
  margin: 0 0 8px;
  font-size: 48px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.gameRound {
  color: #808b99;
  font-size: 17px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.endSession {
  min-height: 48px;
  padding: 0 18px;
  border: 1px solid #39414c;
  border-radius: 13px;
  background: transparent;
  color: #aab3be;
  font-weight: 750;
}

.gameScoreboard {
  display: grid;
  gap: 10px;
}

.standingRow {
  position: relative;

  display: grid;
  grid-template-columns:
    54px minmax(0, 1fr) 105px;
  align-items: center;

  min-height: 104px;
  padding: 16px 22px;

  border: 1px solid #282f39;
  border-radius: 18px;
  background: #171c24;

  transition:
    border-color 160ms ease,
    background 160ms ease;
}

.standingRank {
  display: grid;
  place-items: center;

  width: 38px;
  height: 38px;

  border-radius: 11px;

  background: #202731;
  color: #8390a0;

  font-size: 18px;
  font-weight: 950;
}

.standingPlayer {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.standingPlayer > div {
  min-width: 0;
}

.standingPlayer h2 {
  margin: 0;
  font-size: 27px;
}

.standingPlayer p {
  margin: 6px 0 0;

  color: #758293;

  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.035em;
}

.standingPoints {
  display: grid;
  justify-items: end;
  align-content: center;
  gap: 2px;
}

.standingPoints strong {
  font-size: 49px;
  line-height: 0.9;
}

.standingPoints span {
  color: #7a8796;

  font-size: 9px;
  font-weight: 950;
  letter-spacing: 0.12em;
}

.gameWaiting {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;

  min-height: 56px;
  margin-top: 12px;
  padding: 13px 18px;

  border: 1px solid #2b3440;
  border-radius: 13px;
  background: #151b22;
}

.gameWaiting span {
  color: #778596;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.gameWaiting strong {
  color: #edf2f7;
  font-size: 14px;
  text-align: right;
}

.gameActions {
  display: grid !important;
  grid-template-columns:
    repeat(3, minmax(0, 1fr)) !important;

  gap: 10px !important;
  margin-top: 20px;
}

.gameActions button {
  min-height: 76px;
  border: 0;
  border-radius: 18px;
  background: #f2f4f6;
  color: #101419;
  font-size: 18px;
  font-weight: 850;
}

.gameActions .jimAction {
  background: #d9ae4b;
}

.gameActions button:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.nextFeature {
  margin: 12px 0 0;
  color: #626d79;
  font-size: 12px;
  text-align: center;
}

@media (max-width: 600px) {
  .standingRow {
    grid-template-columns:
      42px minmax(0, 1fr) auto;
    padding: 16px;
  }

  .standingPlayer h2 {
    font-size: 22px;
  }

  .standingPoints strong {
    font-size: 40px;
  }

  .gameActions {
    grid-template-columns: 1fr;
  }
}

/* ==============================
   STANDARD ROUND ENTRY
================================ */

.roundEntryHeader {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-bottom: 28px;
}

.roundEntryHeader h1 {
  margin: 3px 0 0;
  font-size: 34px;
}

.roundEntryHeader span {
  color: #7f8997;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.1em;
}


/* SHARED ROUND / ACTION HEADER */

.roundHeader {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-bottom: 28px;
}

.roundHeader > div {
  min-width: 0;
}

.roundHeader > div > span {
  color: #7f8997;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.roundHeader h1 {
  margin: 3px 0 0;
  font-size: 34px;
}

.roundBack {
  width: 54px;
  height: 54px;
  flex: 0 0 auto;
  border: 1px solid #2d3540;
  border-radius: 15px;
  background: #171c24;
  color: white;
  font-size: 25px;
}

.roundEntryLayout {
