  margin-top: 8px;
  padding: 4px 7px;

  border-radius: 6px;

  background: #29313d;
  color: #a8b4c2;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.cardTotal {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-top: 14px;
  padding: 22px 24px;

