  background: #171c24;
}

.cardTotal.valid {
  border-color: #4b9865;
}

.cardTotal > span {
  color: #8993a1;
  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.cardTotal strong {
  font-size: 38px;
}

.cardTotal small {
  color: #798493;
  font-size: 20px;
}

.roundMessage {
  min-height: 22px;
  margin: 12px 4px 0;
  color: #aab3bf;
  font-size: 14px;
}

/* KEYPAD */

.numberPadPanel {
  padding: 18px;

  border: 1px solid #282f39;
  border-radius: 18px;

  background: #171c24;
}

.numberPadPlayer {
  display: flex;
  align-items: baseline;
  justify-content: space-between;

  gap: 12px;
  margin-bottom: 14px;
}

.numberPadPlayer span {
  color: #7e8998;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.numberPadPlayer strong {
  font-size: 20px;
}

.numberPad {
  display: grid;
  grid-template-columns:
    repeat(4, 1fr);

  gap: 9px;
}

.numberPad button {
  min-height: 66px;

  border: 1px solid #303946;
  border-radius: 14px;

  background: #202731;
  color: white;

  font-size: 24px;
  font-weight: 800;
}

.numberPad button:active {
  background: #303a48;
}

.numberPad .numberPadSecondary {
  color: #aab4c1;
  font-size: 19px;
}

.nextScorePlayer {
  width: 100%;
  min-height: 58px;

  margin-top: 11px;

  border: 0;
  border-radius: 14px;

  background: #323b48;
  color: white;

  font-weight: 850;
}

.saveStandardRound {
  width: 100%;
  min-height: 76px;

  margin-top: 18px;

  border: 0;
  border-radius: 18px;

  background: #f2f4f6;
  color: #101419;

  font-size: 18px;
  font-weight: 850;
}

.saveStandardRound:disabled {
  background: #252b34;
  color: #5f6976;
