}

.tieLabel {
  color: #d9ae4b;

  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.tieDialog h2 {
  margin: 8px 0 4px;
  font-size: 32px;
}

.tieDialog p {
  margin: 0 0 20px;
  color: #9aa5b3;
}

.tieChoices {
  display: grid;
  gap: 10px;
}

.tieChoices button {
  min-height: 64px;

  border: 1px solid #323b47;
