  background: #222a35;
  color: white;

  font-size: 19px;
  font-weight: 800;
}

@media (max-width: 760px) {
  .roundEntryLayout {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .roundPlayers {
    grid-template-columns: 1fr;
  }
}

/* ==============================
   TITLE RACE
================================ */

.raceAction {
  background: #2d3541 !important;
  color: #f5f7fa !important;
}

.racePage {
  max-width: 1200px;
}

.raceHeader {
  display: grid;
  grid-template-columns:
    auto 1fr auto;
  align-items: center;
  gap: 18px;
  margin-bottom: 22px;
}

.raceHeader > div > span {
  color: #7e8998;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.raceHeader h1 {
  margin: 3px 0 0;
  font-size: 34px;
}

.racePlay {
  min-width: 110px;
  min-height: 52px;

  border: 0;
  border-radius: 14px;

  background: #f2f4f6;
