.historySessionSummary {
  width: 100%;
  min-height: 88px;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  padding: 16px 20px;

  border: 0;

  background: transparent;
  color: #f5f7fa;

  text-align: left;
}

.historySessionSummary > div:first-child {
  display: grid;
  gap: 4px;
}

.historySessionSummary > div:first-child strong {
  font-size: 20px;
}

.historySessionSummary > div:first-child span,
.historySessionSummaryRight > span {
  color: #8793a1;
  font-size: 13px;
}

.historySessionSummaryRight {
  display: flex;
  align-items: center;
  gap: 12px;
}

.historySessionSummaryRight b {
  padding: 5px 8px;

  border-radius: 7px;

  background: #29323d;
  color: #9eabb9;

  font-size: 10px;
  letter-spacing: 0.08em;
}

.historySessionSummaryRight b.active {
  background: #20372a;
  color: #81d499;
}

.historySessionDetails {
  padding: 18px 20px 20px;

  border-top: 1px solid #29313b;
}

.historySessionMeta {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 9px;

  margin-bottom: 16px;
}

.historySessionMeta > div {
  min-width: 0;

  padding: 14px;

  border-radius: 13px;

  background: #11151b;
}

.historySessionMeta span {
  display: block;

  margin-bottom: 5px;

  color: #778392;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.historySessionMeta strong {
  display: block;

  overflow: hidden;

  font-size: 18px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.historyStandings {
  display: grid;
  gap: 7px;
}

.historyStanding {
  display: grid;
  grid-template-columns:
    38px minmax(0, 1fr) auto;
  align-items: center;

  min-height: 62px;

  padding: 8px 14px;

  border-radius: 12px;

  background: #202731;
}

.historyStanding > span {
  color: #788391;
  font-weight: 850;
}

.historyStanding > div {
  display: grid;
  gap: 3px;

  min-width: 0;
}

.historyStanding > div > strong {
  overflow: hidden;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.historyStanding small {
  color: #8994a2;
}

.historyStanding > b {
  font-size: 22px;
}

.historyRaceButton {
  width: 100%;
  min-height: 58px;

  margin-top: 14px;

  border: 0;
  border-radius: 14px;

  background: #303946;
  color: #f5f7fa;

  font-weight: 850;
}

.historyEmpty {
  padding: 50px 20px;

  border: 1px dashed #303844;
  border-radius: 17px;

  color: #7f8997;

  text-align: center;
}

/* PLAYER STATS */

.playerStatsList {
  display: grid;
  gap: 14px;
}

.playerStatsCard {
  padding: 20px;

  border: 1px solid #29313b;
  border-radius: 18px;

  background: #171c24;
}

.playerStatsCard > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  margin-bottom: 18px;
}

.playerStatsCard > header > div {
  display: grid;
  gap: 3px;
}

.playerStatsCard h2 {
  margin: 0;

  font-size: 27px;
}

.playerStatsCard > header span {
  color: #8994a2;
  font-size: 13px;
}

.playerStatsCard > header > strong {
  font-size: 21px;
}

.playerStatSectionLabel {
  margin: 17px 2px 8px;

  color: #7c8795;

  font-size: 14px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.playerStatGrid {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.playerStatGrid > div {
  min-width: 0;

  padding: 14px;

  border-radius: 13px;

  background: #11151b;
}

.playerStatGrid span {
  display: block;

  min-height: 24px;
  margin-bottom: 5px;

  color: #778392;

  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.07em;
}

.playerStatGrid strong {
  font-size: 23px;
}

.hideStageBreakdown {
  display: grid;
  grid-template-columns:
    auto repeat(4, 1fr);
  align-items: center;
  gap: 8px;

  margin-top: 10px;
  padding: 11px 13px;

  border: 1px solid #3c3250;
  border-radius: 13px;

  background: #1d1827;
}

.hideStageBreakdown > span {
  color: #a891c5;

  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.hideStageBreakdown > div {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 5px;
}

.hideStageBreakdown small {
  color: #8f7ba8;
  font-size: 11px;
}

.hideStageBreakdown strong {
  color: #d0b7ef;
}

/* AWARDS */

.historyAwards {
  display: grid;
  gap: 18px;
}

.awardsIntro {
  padding: 5px 2px 2px;
}

.awardsIntro > span {
  color: #d9ae4b;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.awardsIntro h2 {
  margin: 5px 0 6px;

  font-size: 31px;
}

.awardsIntro p {
  max-width: 620px;
  margin: 0;

  color: #8994a2;
  line-height: 1.5;
}

.awardGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.awardCard {
  min-width: 0;

  padding: 20px;

  border: 1px solid #303844;
  border-radius: 18px;

  background: #171c24;
}

.awardCard > span {
  color: #d9ae4b;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.awardCard h3 {
  margin: 8px 0 4px;

  overflow-wrap: anywhere;

  font-size: 27px;
}

.awardCard > strong {
  color: #b5c0cd;

  font-size: 15px;
}

.awardCard p {
  margin: 11px 0 0;

  color: #7f8b99;

  font-size: 13px;
  line-height: 1.4;
}

@media (max-width: 700px) {
  .historySessionMeta {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .playerStatSectionLabel {
    font-size: 13px;
  }

  .playerStatGrid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .playerStatGrid span,
  .hideStageBreakdown > span {
    font-size: 11px;
  }

  .awardGrid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .historySessionSummary {
    align-items: flex-start;
  }

  .historySessionSummaryRight {
    flex-direction: column;
    align-items: flex-end;
    gap: 5px;
  }

  .hideStageBreakdown {
    grid-template-columns:
      1fr 1fr;
  }

  .hideStageBreakdown > span {
    grid-column: 1 / -1;
  }
}


/* ==============================
   SESSION AWARDS
================================ */

.sessionAwardsSection {
  margin-top: 20px;
  padding-top: 18px;

  border-top: 1px solid #29313b;
}

.sessionAwardsHeader {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;

  margin-bottom: 12px;
}

.sessionAwardsHeader span {
  color: #d9ae4b;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.sessionAwardsHeader strong {
  color: #8994a2;

  font-size: 13px;
}

.sessionAwardGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 9px;
}

.sessionAwardCard {
  padding: 15px;

  background: #141920;
}

.sessionAwardCard > span {
  font-size: 9px;
}

.sessionAwardCard h3 {
  margin: 6px 0 3px;

  font-size: 21px;
}

.sessionAwardCard > strong {
  font-size: 13px;
}

.sessionAwardCard p {
  margin-top: 8px;

  font-size: 12px;
}

@media (max-width: 600px) {
  .sessionAwardGrid {
    grid-template-columns: 1fr;
  }

  .sessionAwardsHeader {
    align-items: flex-start;
    flex-direction: column;
    gap: 3px;
  }
}

/* ==============================
   AWARD COLORS + BIGGER TITLES
   History / Session Awards CSS.
================================ */

.awardCard {
  --award-color: #d9ae4b;

  border-left:
    4px solid var(--award-color);
}

.awardCard > span {
  color: var(--award-color);

  font-size: 15px;
  font-weight: 950;
  letter-spacing: 0.08em;
}

.awardCard > strong {
  color: var(--award-color);
}

/* Session cards are smaller overall,
   but the award name should still
   be obvious at a glance. */

.sessionAwardCard > span {
  font-size: 13px;
}

.sessionAwardCard h3 {
  font-size: 23px;
}

/* Each family title gets its own
   stable visual identity. */

.awardTone-cuci {
  --award-color: #6fc8d4;
}

.awardTone-slayer {
  --award-color: #ef7f89;
}

.awardTone-tuah {
  --award-color: #e0b65c;
}

.awardTone-malang {
  --award-color: #b491df;
}

.awardTone-standard {
  --award-color: #79a7f2;
}

.awardTone-jim {
  --award-color: #e79a61;
}

.awardTone-hide {
  --award-color: #bd8fe9;
}

.awardTone-denda {
  --award-color: #e88b9c;
}

.awardTone-survivor {
  --award-color: #7fcf95;
}

.awardTone-comeback {
  --award-color: #67c5b3;
}

.awardTone-jatuh {
  --award-color: #d7838f;
}

.awardTone-default {
  --award-color: #aab5c2;
}

@media (max-width: 600px) {
  .awardCard > span {
    font-size: 14px;
  }

  .sessionAwardCard > span {
    font-size: 12px;
  }
}

/* ==============================
   HISTORY V3
   History / Awards CSS.
================================ */

/* SESSION DETAILS */

.historySessionMetaExpanded {
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
}

/* PLAYER SORTING */

.playerSortPanel {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;

  margin-bottom: 14px;
  padding: 16px 18px;

  border: 1px solid #29313b;
  border-radius: 16px;

  background: #151a21;
}

.playerSortPanel > div:first-child {
  display: grid;
  gap: 3px;

  flex: 0 0 auto;
}

.playerSortPanel > div:first-child span {
  color: #788493;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.playerSortPanel > div:first-child strong {
  font-size: 17px;
}

.playerSortButtons {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 7px;
}

.playerSortButtons button {
  min-height: 38px;
  padding: 0 12px;

  border: 1px solid #303945;
  border-radius: 10px;

  background: #202630;
  color: #8f9aa7;

  font-size: 11px;
  font-weight: 850;
}

.playerSortButtons button.active {
  border-color: #59697d;

  background: #344152;
  color: #f5f7fa;
}

.playerStatsIdentity {
  display: flex !important;
  align-items: center;
  gap: 13px;
}

.playerStatsRank {
  display: grid !important;
  place-items: center;

  width: 42px;
  height: 42px;

  flex: 0 0 42px;

  border-radius: 12px;

  background: #242c36;
  color: #9ba7b5 !important;

  font-size: 13px !important;
  font-weight: 900;
}

.playerStatsHeadline {
  display: grid;
  justify-items: end;
  gap: 1px;
}

.playerStatsHeadline strong {
  font-size: 25px;
}

.playerStatsHeadline span {
  color: #778391;

  font-size: 8px !important;
  font-weight: 900;
  letter-spacing: 0.09em;
}

/* AWARD SECTIONS */

.awardSection {
  display: grid;
  gap: 13px;

  margin-top: 10px;
}

.awardSection + .awardSection {
  margin-top: 28px;
  padding-top: 27px;

  border-top: 1px solid #29313b;
}

.awardSectionHeader {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 30px;

  padding: 0 2px;
}

.awardSectionHeader > div {
  display: grid;
  gap: 3px;
}

.awardSectionHeader > div > span {
  color: #8a95a3;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.awardSectionHeader h3 {
  margin: 0;

  font-size: 25px;
}

.awardSectionHeader p {
  max-width: 420px;
  margin: 0;

  color: #74808e;

  font-size: 12px;
  line-height: 1.45;
  text-align: right;
}

.awardRecordNote {
  display: block;

  margin-top: 5px;

  color: #8995a3;

  font-size: 11px;
  font-weight: 800;
}

.rateAwardCard {
  min-height: 180px;
}

/* Updated award tones */

.awardTone-denda {
  --award-color: #df8a72;
}

.awardTone-duration {
  --award-color: #70b8d9;
}

.awardTone-rounds {
  --award-color: #8ca8e8;
}

/* Bigger award identity */

.awardCard > span {
  font-size: 25px;
}

.awardCard h3 {
  margin-top: 10px;

  font-size: 28px;
}

.awardCard > strong {
  font-size: 17px;
}

/* Mobile */

@media (max-width: 800px) {
  .playerSortPanel {
    align-items: flex-start;
    flex-direction: column;
  }

  .playerSortButtons {
    justify-content: flex-start;

    width: 100%;
  }

  .historySessionMetaExpanded {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .awardSectionHeader {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }

  .awardSectionHeader p {
    max-width: none;

    text-align: left;
  }
}

@media (max-width: 520px) {
  .playerSortButtons {
    display: grid;
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .playerSortButtons button {
    width: 100%;
  }

  .playerStatsCard > header {
    align-items: flex-start;
  }

  .playerStatsHeadline {
    min-width: 70px;
  }

  .historySessionMetaExpanded {
    grid-template-columns: 1fr 1fr;
  }

  .awardCard > span {
    font-size: 25px;
  }

  .awardCard h3 {
    font-size: 23px;
  }
}

/* ==============================
   COMBINED ALL-TIME AWARDS
================================ */

.combinedAwardCard {
  grid-column: span 1;

  padding: 22px;
}

.combinedAwardDescription {
  margin: 8px 0 17px !important;

  color: #7f8b99 !important;

  font-size: 12px !important;
  line-height: 1.45 !important;
}

.combinedAwardMetrics {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  overflow: hidden;

  border: 1px solid #2b343f;
  border-radius: 14px;

  background: #11151b;
}

.combinedAwardMetric {
  min-width: 0;

  padding: 15px 16px;
}

.combinedAwardMetric +
.combinedAwardMetric {
  border-left:
    1px solid #2b343f;
}

.combinedAwardMetric small {
  display: block;

  margin-bottom: 6px;

  color: var(--award-color);

  font-size: 9px;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.09em;
}

.combinedAwardMetric h3 {
  margin: 0 0 3px;

  overflow-wrap: anywhere;

  font-size: 23px;
}

.combinedAwardMetric strong {
  display: block;

  color: var(--award-color);

  font-size: 15px;
}

.combinedAwardMetric em {
  display: block;

  margin-top: 5px;

  color: #778493;

  font-size: 10px;
  font-style: normal;
  font-weight: 750;
}

/* Raja Session */
.awardTone-session {
  --award-color: #75c6a7;
}

@media (max-width: 620px) {
  .combinedAwardMetrics {
    grid-template-columns: 1fr;
  }

  .combinedAwardMetric +
  .combinedAwardMetric {
    border-top:
      1px solid #2b343f;

    border-left: 0;
  }

  .combinedAwardMetric h3 {
    font-size: 21px;
  }
}

/* ==============================
   CLEAN SINGLE-SESSION WINNERS
================================ */

.sessionRecordWinners {
  display: grid;
  gap: 7px;

  margin: 10px 0 8px;
}

.sessionRecordWinner {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;

  min-width: 0;

  padding: 9px 11px;

  border-radius: 10px;

  background: #11151b;
}

.sessionRecordWinner h3 {
  min-width: 0;
  margin: 0;

  overflow: hidden;

  font-size: 22px;
  line-height: 1.15;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.sessionRecordWinner > span {
  flex: 0 0 auto;

  color: #82909f;

  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}

/* Keep the record value visually
   separate from the winner rows. */
.rateAwardCard > .sessionRecordWinners + strong {
  display: block;

  margin-top: 7px;
}

/* On small screens, let the date sit
   underneath instead of crushing names. */
@media (max-width: 520px) {
  .sessionRecordWinner {
    align-items: flex-start;
    flex-direction: column;
    gap: 2px;
  }

  .sessionRecordWinner h3 {
    width: 100%;

    overflow: visible;
    white-space: normal;
  }
}

/* ==============================
   CLEAN ALL-TIME TIED WINNERS
   combined award CSS.
================================ */

.combinedWinnerList {
  display: grid;
  gap: 5px;

  margin: 2px 0 7px;
}

.combinedWinnerRow {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;

  min-width: 0;
}

.combinedWinnerRow h3 {
  min-width: 0;
  margin: 0;

  overflow: hidden;

  font-size: 22px;
  line-height: 1.18;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.combinedWinnerRow > span {
  flex: 0 0 auto;

  color: #7f8b99;

  font-size: 10px;
  font-weight: 800;
  white-space: nowrap;
}

/* Keep the shared record value
   visually separate from tied names. */

.combinedAwardMetric >
.combinedWinnerList + strong {
  margin-top: 5px;
}

/* If many people share a record,
   the card grows vertically instead
   of forcing names onto one line. */

@media (max-width: 520px) {
  .combinedWinnerRow {
    align-items: flex-start;
    flex-direction: column;
    gap: 1px;
  }

  .combinedWinnerRow h3 {
    width: 100%;

    overflow: visible;
    white-space: normal;
  }
}

/* ==============================
   PER-SESSION AWARDS
================================ */

.historySessionActions {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 10px;

  margin-top: 14px;
}

.historySessionActions
.historyRaceButton,
.historySessionActions
.historyAwardsButton {
  width: 100%;
  min-height: 58px;
  margin-top: 0;

  border: 0;
  border-radius: 14px;

  font-weight: 850;
}

.historyAwardsButton {
  background: #26382f;
  color: #91d5aa;
}

.historyAwardsButton:hover {
  background: #2d4437;
}

.sessionAwardsPage {
  max-width: 1100px;
}

.sessionAwardsSummary {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 10px;

  margin-bottom: 18px;
}

.sessionAwardsSummary > div {
  padding: 15px 17px;

  border: 1px solid #29313b;
  border-radius: 14px;

  background: #151a21;
}

.sessionAwardsSummary span {
  display: block;

  margin-bottom: 4px;

  color: #788493;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.sessionAwardsSummary strong {
  font-size: 20px;
}

.sessionOwnAwardGrid {
  margin-top: 2px;
}

.sessionOwnAwardGrid
.awardCard {
  min-height: 190px;
}

@media (max-width: 600px) {
  .historySessionActions {
    grid-template-columns: 1fr;
  }

  .sessionAwardsSummary {
    grid-template-columns: 1fr 1fr;
  }
}

/* ==============================
   PLAYER SORT STAT HIGHLIGHT
================================ */

