    linear-gradient(
      135deg,
      rgba(222, 181, 88, 0.12),
      rgba(17, 21, 27, 0.78)
    );
}

.playerStatsHeadline.sortStatHighlight
strong {
  color: #f0c75e;
}

.playerStatsHeadline.sortStatHighlight
span {
  color: #c7a755;
}

/* ==============================
