  padding: 4px 2px 2px;
}

.mvpIntro > div:first-child > span {
  color: #e0b65c;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.mvpIntro h2 {
  margin: 5px 0 6px;

  font-size: 31px;
}

.mvpIntro p {
  max-width: 650px;
  margin: 0;

  color: #8994a2;
  line-height: 1.5;
}

