  }

  .gameRoundHero > strong {
    font-size: 40px;
  }
}

@media (max-width: 620px) {
  .gameHeaderPolished
  .gameHeaderActions {
    gap: 5px;
  }

  .gameHeaderPolished
  .gameHeaderActions button {
    min-height: 40px;
    padding: 0 10px;

    font-size: 11px;
  }

