/* ==============================
   TABLET QUICK-RANK DRAG FIX
   Prevent browser pull-to-refresh
   from stealing reorder gestures.
================================ */

/*
  JIMRAMI is an app-like interface.
  Native pull-to-refresh is more
  harmful than useful here.
*/
/*
  The entire Quick Rank interaction
  belongs to the reorder gesture,
  not page scrolling.
*/
.quickRankPanel,
.quickRankList,
.quickRankItem,
.quickRankCard {
  touch-action: none !important;
  overscroll-behavior: none;
}

/*
  Avoid long-press text/image selection
  while dragging on Android.
*/
.quickRankList,
.quickRankItem,
.quickRankCard {
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
}

/* ==============================
   SCOREBOARD — LAST WINNER,
   TALLIES, JIM STARS & STATUS
================================ */

/* ---------- PREVIOUS WINNER ---------- */

.previousWinnerBar {
  display: grid;
  grid-template-columns:
    minmax(150px, auto)
    minmax(0, 1fr)
    38px;
  align-items: center;
  gap: 18px;

  margin-bottom: 12px;
  padding: 11px 15px;

  border:
    1px solid #343c47;
  border-radius: 13px;

  background:
    linear-gradient(
      90deg,
      #151b22,
      #12171d
    );
}

.previousWinnerLabel {
  display: grid;
  gap: 2px;
}

.previousWinnerLabel > span {
  color: #7d8997;

  font-size: 9px;
  font-weight: 950;
  letter-spacing: 0.11em;
}

.previousWinnerLabel > small {
  color: #65717f;

  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.04em;
}

.previousWinnerBar > strong {
  overflow: hidden;

  color: #f2f5f8;

  font-size: 18px;
  font-weight: 950;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.previousWinnerIcon {
  display: grid;
  place-items: center;

  width: 32px;
  height: 32px;

  border-radius: 10px;

  font-size: 15px;
  font-weight: 950;
}

.previousWinnerIcon.standard {
  background: #1c2b3a;
  color: #83b9e8;
}

.previousWinnerIcon.jim {
  background: #332a16;
  color: #e2b64e;
}

/* ---------- PLAYING / WAITING ---------- */

.playerStatusTag {
  flex: 0 0 auto;

  padding: 5px 8px;

  border-radius: 7px;

  font-size: 8px;
  font-weight: 950;
  letter-spacing: 0.1em;
}

.playerStatusTag.playing {
  border:
    1px solid #28533a;

  background: #183324;
  color: #72cf93;
}

.playerStatusTag.waiting {
  border:
    1px solid #5a4920;

  background: #342a16;
  color: #e2bd61;
}

/* ---------- ACHIEVEMENTS ---------- */

.standingAchievements {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 11px;

  min-height: 22px;
  margin-top: 6px;
}

.standardWinTally {
  display: flex;
  align-items: center;
  gap: 7px;

  min-width: 0;
}

.winMetaLabel {
  color: #718092;

  font-size: 8px;
  font-weight: 950;
  letter-spacing: 0.08em;
}

.tallyGroups {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
}

.tallyGroup {
  position: relative;

  display: flex;
  align-items: center;
  gap: 3px;

  height: 18px;
  min-width: 4px;
}

.tallyMark {
  display: block;

  width: 2px;
  height: 15px;

  border-radius: 2px;

  background: #8fb7df;

  transform:
    rotate(-2deg);
}

.tallyStrike {
  position: absolute;
  top: 8px;
  left: -2px;

  display: block;

  width: 22px;
  height: 2px;

  border-radius: 2px;

  background: #8fb7df;

  transform:
    rotate(-31deg);
  transform-origin: center;
}

.jimWinStars {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2px;

  max-width: 170px;

  line-height: 1;
}

.jimWinStars > span {
  color: #e3b64b;

  font-size: 15px;

  filter:
    drop-shadow(
      0 0 4px
      rgba(227, 182, 75, 0.15)
