/* ---------- SMALLER SCREENS ---------- */

@media (max-width: 620px) {
  .previousWinnerBar {
    grid-template-columns:
      1fr auto;
    gap: 8px 12px;
  }

  .previousWinnerLabel {
    grid-column: 1;
  }

  .previousWinnerBar > strong {
    grid-column: 1;
    grid-row: 2;

    font-size: 17px;
  }

  .previousWinnerIcon {
    grid-column: 2;
    grid-row: 1 / 3;
  }

  .standingAchievements {
    gap: 8px;
  }

  .winMetaLabel {
    font-size: 7px;
  }

  .tallyMark {
    height: 13px;
  }

  .tallyGroup {
    height: 16px;
  }

  .tallyStrike {
