/* ==============================
   SCORE TRANSITION — CURRENT
================================ */

/* Kill visual leftovers from the
   previous transition experiment. */
.cleanTransitionPage {
  gap: 20px;
}

.cleanTransitionHeader {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;

  margin-bottom: 18px;
}

.cleanTransitionHeader > div {
  display: grid;
  gap: 4px;
}

.cleanTransitionHeader span {
  color: #758398;

  font-size: 10px;
  font-weight: 950;
  letter-spacing: 0.12em;
}

.cleanTransitionHeader h1 {
  margin: 0;

  color: #f4f7fb;

  font-size: 42px;
  font-weight: 1000;
  line-height: 1;
}

.cleanTransitionHeader button {
  min-height: 40px;
  padding: 0 14px;

  border: 1px solid #364252;
  border-radius: 11px;

  background: #202936;
  color: #eef3f8;

  font-size: 11px;
  font-weight: 900;
}

/* ---------- BOARD ---------- */

.cleanTransitionBoard {
  position: relative;

  width: 100%;
}

.cleanTransitionRow {
  position: absolute;
  left: 0;
  right: 0;

  box-sizing: border-box;

  display: grid;
  grid-template-columns:
    50px
    minmax(0, 1fr)
    92px;

  align-items: center;
  gap: 16px;

  height: 94px;
  padding: 15px 20px;

  overflow: visible;

  border: 1px solid #2a3441;
  border-radius: 17px;

  background: #171e27;

  transition:
    top 900ms
      cubic-bezier(
        0.22,
        1,
        0.36,
        1
      ),
    border-color
      300ms ease,
    transform
      300ms ease;
}

.cleanTransitionRow.settled {
  border-color: #344151;
}

.cleanTransitionRank {
  color: #8291a5;

  font-size: 23px;
  font-weight: 950;

  text-align: center;
}

.cleanTransitionMain {
  min-width: 0;
}

.cleanTransitionNameLine {
  display: flex;
  align-items: center;
  gap: 9px;

  min-width: 0;
}

.cleanTransitionNameLine h2 {
  margin: 0;

  overflow: hidden;

  color: #f6f8fb;

  font-size: 22px;
  font-weight: 950;

  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---------- STATUS ---------- */

.cleanTransitionPage
.playerStatusTag {
  flex: 0 0 auto;

  padding: 4px 7px;

  border-radius: 7px;

  font-size: 7px;
  font-weight: 950;
  letter-spacing: 0.09em;
}

.cleanTransitionPage
.playerStatusTag.playing {
  border: 1px solid #28533a;

  background: #183324;
  color: #72cf93;
}

.cleanTransitionPage
.playerStatusTag.waiting {
  border: 1px solid #5a4920;

  background: #342a16;
  color: #e2bd61;
}

/* ---------- ACHIEVEMENTS ---------- */

.cleanTransitionMeta {
  display: flex;
  align-items: center;
  gap: 9px;

  min-height: 17px;
  margin-top: 6px;
}

.scoreTally {
  display: flex;
  align-items: center;
  gap: 5px;
}

.scoreTallyGroup {
  position: relative;

  display: flex;
  align-items: center;
  gap: 3px;

  height: 16px;
}

.scoreTallyMark {
  display: block;

  width: 2px;
  height: 13px;

  border-radius: 2px;

  background: #8eb7e0;
}

.scoreTallyStrike {
  position: absolute;
  top: 7px;
  left: -2px;

  width: 20px;
  height: 2px;

  border-radius: 2px;

  background: #8eb7e0;

  transform:
    rotate(-31deg);
}

.scoreJimStars {
  display: flex;
  align-items: center;
  gap: 2px;
}

.scoreJimStars > span {
  color: #e3b64b;

  font-size: 13px;
  line-height: 1;
}

.scoreTally.pop,
.scoreJimStars.pop {
  animation:
    achievementPop
    650ms
    cubic-bezier(
      0.22,
      1.4,
      0.36,
      1
    );
}

@keyframes achievementPop {
  0% {
    transform:
      scale(0.72);
    opacity: 0.35;
  }

  60% {
    transform:
      scale(1.18);
    opacity: 1;
  }

  100% {
    transform:
      scale(1);
    opacity: 1;
  }
}

/* ---------- POINTS ---------- */

.cleanTransitionPoints {
  display: grid;
  justify-items: end;
  align-content: center;
  gap: 2px;
}

.cleanTransitionPoints strong {
  color: #f4f7fa;

  font-size: 44px;
  font-weight: 1000;
  line-height: 0.9;
}

.cleanTransitionPoints span {
  color: #8290a2;

  font-size: 8px;
  font-weight: 950;
  letter-spacing: 0.1em;
}

/* ---------- REWARD POP ---------- */

.cleanRewardBubble {
  position: absolute;
  top: 10px;
  right: 104px;
  z-index: 5;

  display: flex;
  align-items: center;
  gap: 7px;

  padding: 5px 9px;

  border-radius: 10px;

  pointer-events: none;

  animation:
    rewardIn
      300ms ease-out,
    rewardOut
      600ms ease-in
      7.0s forwards;
}

.cleanRewardBubble.gain {
  border: 1px solid #2c6546;

  background: #183a29;
  color: #83d7a1;
}

.cleanRewardBubble.loss {
  border: 1px solid #71404a;

  background: #41242a;
  color: #ef99a4;
}

.cleanRewardBubble strong {
  font-size: 17px;
  font-weight: 1000;
  line-height: 1;
}

.rewardTally {
  color: #9cc3ea;

  font-size: 17px;
  font-weight: 1000;
  line-height: 1;
}

.rewardStar {
  color: #e3b64b;

  font-size: 15px;
  line-height: 1;
}

@keyframes rewardIn {
  from {
    opacity: 0;
    transform:
      translateY(5px)
      scale(0.88);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }
}

@keyframes rewardOut {
  to {
    opacity: 0;
    transform:
      translateY(-8px)
      scale(0.96);
  }
}

/* ---------- TABLET ---------- */

@media (
  max-width: 700px
) {
  .cleanTransitionHeader h1 {
    font-size: 35px;
  }

  .cleanTransitionRow {
    grid-template-columns:
      38px
      minmax(0, 1fr)
      70px;

    gap: 9px;

    padding:
      13px 12px;
  }

  .cleanTransitionRank {
    font-size: 18px;
  }

  .cleanTransitionNameLine h2 {
    font-size: 18px;
  }

  .cleanTransitionPoints strong {
    font-size: 35px;
  }

  .cleanRewardBubble {
    right: 76px;
  }
}

/* Very small phones: stack History tabs only when truly necessary. */
@media (max-width: 420px) {
  .historyTabs {
    grid-template-columns:
      1fr;
  }
}

* {
  box-sizing: border-box;
}

:root {
  font-family:
    Inter,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;

  color: #f5f7fa;
  background: #0d1015;
  font-synthesis: none;
}

html,
body,
#root {
  width: 100%;
  min-width: 320px;
  min-height: 100%;
  margin: 0;
  overscroll-behavior-y: none;
}

body {
  background: #0d1015;
}

button,
input {
  font: inherit;
}

button {
  cursor: pointer;
}

.app {
  width: 100%;
  max-width: 1000px;
  margin: 0 auto;
  padding: 28px;
}

/* HEADER */

.setupHeader {
  display: grid;
  grid-template-columns:
    1fr auto 1fr;
  align-items: center;
  gap: 20px;
  margin-bottom: 28px;
}

.setupHeader > h1 {
  grid-column: 2;
  justify-self: center;

  margin: 0;
  font-size: 44px;
  letter-spacing: -0.045em;
  text-align: center;
}

.setupHeaderActions {
  grid-column: 3;
  justify-self: end;
}

@media (max-width: 700px) {
  .setupHeader {
    grid-template-columns:
      1fr auto;
    gap: 14px;
  }

  .setupHeader > h1 {
    grid-column: 1 / -1;
    grid-row: 1;
  }

  .setupHeaderActions {
    grid-column: 2;
    grid-row: 2;
  }
}

/* ADD PLAYER */

.addPlayer {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  margin-bottom: 24px;
}

.addPlayer input {
  min-width: 0;
  min-height: 60px;
  padding: 0 18px;
  border: 1px solid #303844;
  border-radius: 15px;
  outline: none;
  background: #171c24;
  color: white;
  font-size: 18px;
}

.addPlayer input:focus {
  border-color: #8faeff;
}

.addPlayer button {
  min-width: 140px;
  border: 0;
  border-radius: 15px;
  background: #f2f4f6;
  color: #101419;
  font-weight: 800;
}

/* PLAYER LIST */

.playerLibrary {
  display: grid;
  gap: 11px;
}

.emptyPlayers {
  padding: 30px;
  border: 1px dashed #303844;
  border-radius: 16px;
  color: #7f8997;
  text-align: center;
}

.playerSelect {
  display: grid;
  grid-template-columns: 1fr 94px;
  min-height: 78px;
  overflow: hidden;
  border: 2px solid #272e38;
  border-radius: 17px;
  background: #171c24;
}

.playerSelect.selected {
  border-color: #8faeff;
  background: #1b2230;
}

.playerSelectMain {
  display: grid;
  grid-template-columns: 48px 1fr auto;
  align-items: center;
  gap: 14px;
  min-width: 0;
  padding: 14px 18px;
  border: 0;
  background: transparent;
  color: white;
  text-align: left;
}

.playerSelectMain strong {
  overflow: hidden;
  font-size: 21px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.playerSelectMain > span {
  color: #778493;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.playerSelect.selected .playerSelectMain > span {
  color: #aebcce;
}

.selectionNumber {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border: 1px solid #38414e;
  border-radius: 11px;
  color: #8b96a5;
  font-weight: 900;
}

.playerSelect.selected .selectionNumber {
  background: #f3f5f7;
  color: #101419;
}

.deletePlayer {
  border: 0;
  border-left: 1px solid #29313c;
  background: transparent;
  color: #687382;
  font-size: 25px;
}

.deletePlayer:hover {
  color: white;
}

/* SESSION SUMMARY */

.sessionSummary {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-top: 22px;
}

.sessionSummary > div {
  padding: 17px;
  border: 1px solid #272e38;
  border-radius: 15px;
  background: #13171d;
}

.sessionSummary span {
  display: block;
  margin-bottom: 5px;
  color: #778392;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.sessionSummary strong {
  font-size: 27px;
}

/* START */

.startSession {
  width: 100%;
  min-height: 72px;
  margin-top: 16px;
  border: 0;
  border-radius: 17px;
  background: #f2f4f6;
  color: #101419;
  font-size: 18px;
  font-weight: 850;
}

.startSession:disabled {
  background: #242a33;
  color: #606b78;
  cursor: not-allowed;
}

@media (max-width: 600px) {
  .app {
    padding: 18px;
  }

  .addPlayer {
    grid-template-columns: 1fr;
  }

  .addPlayer button {
    min-height: 56px;
  }

  .playerSelectMain {
    grid-template-columns: 42px 1fr;
  }

  .playerSelectMain > span {
    grid-column: 2;
  }
}
/* ---------- ACTIVE GAME ---------- */

.gameHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 28px;
}

.gameHeader h1 {
  margin: 0 0 8px;
  font-size: 48px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.gameRound {
  color: #808b99;
  font-size: 17px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.endSession {
  min-height: 48px;
  padding: 0 18px;
  border: 1px solid #39414c;
  border-radius: 13px;
  background: transparent;
  color: #aab3be;
  font-weight: 750;
}

.gameScoreboard {
  display: grid;
  gap: 10px;
}

.standingRow {
  position: relative;

  display: grid;
  grid-template-columns:
    54px minmax(0, 1fr) 105px;
  align-items: center;

  min-height: 104px;
  padding: 16px 22px;

  border: 1px solid #282f39;
  border-radius: 18px;
  background: #171c24;

  transition:
    border-color 160ms ease,
    background 160ms ease;
}

.standingRank {
  display: grid;
  place-items: center;

  width: 38px;
  height: 38px;

  border-radius: 11px;

  background: #202731;
  color: #8390a0;

  font-size: 18px;
  font-weight: 950;
}

.standingPlayer {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.standingPlayer > div {
  min-width: 0;
}

.standingPlayer h2 {
  margin: 0;
  font-size: 27px;
}

.standingPlayer p {
  margin: 6px 0 0;

  color: #758293;

  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.035em;
}

.standingPoints {
  display: grid;
  justify-items: end;
  align-content: center;
  gap: 2px;
}

.standingPoints strong {
  font-size: 49px;
  line-height: 0.9;
}

.standingPoints span {
  color: #7a8796;

  font-size: 9px;
  font-weight: 950;
  letter-spacing: 0.12em;
}

.gameWaiting {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;

  min-height: 56px;
  margin-top: 12px;
  padding: 13px 18px;

  border: 1px solid #2b3440;
  border-radius: 13px;
  background: #151b22;
}

.gameWaiting span {
  color: #778596;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.gameWaiting strong {
  color: #edf2f7;
  font-size: 14px;
  text-align: right;
}

.gameActions {
  display: grid !important;
  grid-template-columns:
    repeat(3, minmax(0, 1fr)) !important;

  gap: 10px !important;
  margin-top: 20px;
}

.gameActions button {
  min-height: 76px;
  border: 0;
  border-radius: 18px;
  background: #f2f4f6;
  color: #101419;
  font-size: 18px;
  font-weight: 850;
}

.gameActions .jimAction {
  background: #d9ae4b;
}

.gameActions button:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.nextFeature {
  margin: 12px 0 0;
  color: #626d79;
  font-size: 12px;
  text-align: center;
}

@media (max-width: 600px) {
  .standingRow {
    grid-template-columns:
      42px minmax(0, 1fr) auto;
    padding: 16px;
  }

  .standingPlayer h2 {
    font-size: 22px;
  }

  .standingPoints strong {
    font-size: 40px;
  }

  .gameActions {
    grid-template-columns: 1fr;
  }
}

/* ==============================
   STANDARD ROUND ENTRY
================================ */

.roundEntryHeader {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-bottom: 28px;
}

.roundEntryHeader h1 {
  margin: 3px 0 0;
  font-size: 34px;
}

.roundEntryHeader span {
  color: #7f8997;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.1em;
}


/* SHARED ROUND / ACTION HEADER */

.roundHeader {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-bottom: 28px;
}

.roundHeader > div {
  min-width: 0;
}

.roundHeader > div > span {
  color: #7f8997;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.roundHeader h1 {
  margin: 3px 0 0;
  font-size: 34px;
}

.roundBack {
  width: 54px;
  height: 54px;
  flex: 0 0 auto;
  border: 1px solid #2d3540;
  border-radius: 15px;
  background: #171c24;
  color: white;
  font-size: 25px;
}

.roundEntryLayout {
  display: grid;
  grid-template-columns:
    minmax(0, 1fr)
    330px;

  gap: 22px;
  align-items: start;
}

.roundPlayers {
  display: grid;
  grid-template-columns:
    1fr 1fr;
  gap: 12px;
}

.roundPlayerCard {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;

  width: 100%;
  min-height: 125px;

  padding: 20px;

  border: 2px solid #282f39;
  border-radius: 18px;

  background: #171c24;
  color: white;

  text-align: left;
}

.roundPlayerCard.active {
  border-color: #8faeff;
  background: #1c2330;
}

.roundPlayerCard strong {
  font-size: 23px;
}

.roundPlayerScore {
  min-width: 60px;
  text-align: right;
  font-size: 42px;
  font-weight: 850;
  line-height: 1;
}

.autoScore {
  display: block;
  width: fit-content;

  margin-top: 8px;
  padding: 4px 7px;

  border-radius: 6px;

  background: #29313d;
  color: #a8b4c2;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.cardTotal {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-top: 14px;
  padding: 22px 24px;

  border: 1px solid #282f39;
  border-radius: 18px;

  background: #171c24;
}

.cardTotal.valid {
  border-color: #4b9865;
}

.cardTotal > span {
  color: #8993a1;
  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.cardTotal strong {
  font-size: 38px;
}

.cardTotal small {
  color: #798493;
  font-size: 20px;
}

.roundMessage {
  min-height: 22px;
  margin: 12px 4px 0;
  color: #aab3bf;
  font-size: 14px;
}

/* KEYPAD */

.numberPadPanel {
  padding: 18px;

  border: 1px solid #282f39;
  border-radius: 18px;

  background: #171c24;
}

.numberPadPlayer {
  display: flex;
  align-items: baseline;
  justify-content: space-between;

  gap: 12px;
  margin-bottom: 14px;
}

.numberPadPlayer span {
  color: #7e8998;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.numberPadPlayer strong {
  font-size: 20px;
}

.numberPad {
  display: grid;
  grid-template-columns:
    repeat(3, 1fr);

  gap: 9px;
}

.numberPad button {
  min-height: 66px;

  border: 1px solid #303946;
  border-radius: 14px;

  background: #202731;
  color: white;

  font-size: 24px;
  font-weight: 800;
}

.numberPad button:active {
  background: #303a48;
}

.numberPad .numberPadSecondary {
  color: #aab4c1;
  font-size: 19px;
}

.nextScorePlayer {
  width: 100%;
  min-height: 58px;

  margin-top: 11px;

  border: 0;
  border-radius: 14px;

  background: #323b48;
  color: white;

  font-weight: 850;
}

.saveStandardRound {
  width: 100%;
  min-height: 76px;

  margin-top: 18px;

  border: 0;
  border-radius: 18px;

  background: #f2f4f6;
  color: #101419;

  font-size: 18px;
  font-weight: 850;
}

.saveStandardRound:disabled {
  background: #252b34;
  color: #5f6976;
  cursor: not-allowed;
}

/* TIE DIALOG */

.tieOverlay {
  position: fixed;
  inset: 0;
  z-index: 50;

  display: grid;
  place-items: center;

  padding: 24px;

  background:
    rgba(5, 7, 10, 0.84);
}

.tieDialog {
  width: min(
    100%,
    470px
  );

  padding: 28px;

  border: 1px solid #323b47;
  border-radius: 22px;

  background: #171c24;
}

.tieLabel {
  color: #d9ae4b;

  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.tieDialog h2 {
  margin: 8px 0 4px;
  font-size: 32px;
}

.tieDialog p {
  margin: 0 0 20px;
  color: #9aa5b3;
}

.tieChoices {
  display: grid;
  gap: 10px;
}

.tieChoices button {
  min-height: 64px;

  border: 1px solid #323b47;
  border-radius: 14px;

  background: #222a35;
  color: white;

  font-size: 19px;
  font-weight: 800;
}

@media (max-width: 760px) {
  .roundEntryLayout {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .roundPlayers {
    grid-template-columns: 1fr;
  }
}

/* ==============================
   TITLE RACE
================================ */

.raceAction {
  background: #2d3541 !important;
  color: #f5f7fa !important;
}

.racePage {
  max-width: 1200px;
}

.raceHeader {
  display: grid;
  grid-template-columns:
    auto 1fr auto;
  align-items: center;
  gap: 18px;
  margin-bottom: 22px;
}

.raceHeader > div > span {
  color: #7e8998;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.raceHeader h1 {
  margin: 3px 0 0;
  font-size: 34px;
}

.racePlay {
  min-width: 110px;
  min-height: 52px;

  border: 0;
  border-radius: 14px;

  background: #f2f4f6;
  color: #101419;

  font-weight: 850;
}

.racePlay:disabled {
  opacity: 0.35;
}

.raceChart {
  padding: 18px 8px 4px;

  border: 1px solid #282f39;
  border-radius: 20px;

  background: #141920;
}

.raceControls {
  display: grid;
  grid-template-columns:
    1fr auto;
  align-items: center;
  gap: 20px;

  margin-top: 18px;
}

.raceControls input {
  width: 100%;
  accent-color: #f2f4f6;
}

.raceRoundCount {
  min-width: 105px;
  color: #8994a2;
  font-size: 13px;
  font-weight: 800;
  text-align: right;
}

.raceStandings {
  display: grid;
  gap: 8px;

  margin-top: 20px;
}

.raceStanding {
  display: grid;
  grid-template-columns:
    40px 1fr auto;
  align-items: center;

  min-height: 52px;
  padding: 0 16px;

  border-radius: 12px;
  background: #171c24;

  will-change: transform;
}

.raceStanding > span {
  color: #788391;
  font-weight: 900;
}

.raceStanding strong {
  font-size: 16px;
}

.raceStanding b {
  font-size: 20px;
}

.raceEmpty {
  padding: 60px 20px;

  border: 1px dashed #303844;
  border-radius: 18px;

  color: #7f8997;
  text-align: center;
}

@media (max-width: 600px) {
  .gameActions {
    grid-template-columns: 1fr;
  }

  .raceChart {
    padding-left: 0;
    padding-right: 0;
  }

  .raceControls {
    grid-template-columns: 1fr;
  }

  .raceRoundCount {
    text-align: center;
  }
}

.raceHeaderActions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.raceSpeed {
  min-width: 66px;
  min-height: 52px;

  border: 1px solid #303844;
  border-radius: 14px;

  background: #171c24;
  color: #f5f7fa;

  font-weight: 850;
}

.raceSpeed:active {
  background: #252d39;
}

/* ==============================
   DATA / BACKUP
================================ */

.gameHeaderActions,
.setupHeaderActions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.dataButton {
  min-height: 48px;
  padding: 0 18px;

  border: 1px solid #39414c;
  border-radius: 13px;

  background: #171c24;
  color: #f2f4f6;

  font-weight: 800;
}

.dataOverlay {
  position: fixed;
  inset: 0;
  z-index: 100;

  display: grid;
  place-items: center;

  padding: 22px;

  background:
    rgba(4, 6, 9, 0.84);
}

.dataPanel {
  width: min(
    100%,
    620px
  );

  padding: 26px;

  border: 1px solid #303844;
  border-radius: 22px;

  background: #171c24;
}

.dataHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-bottom: 22px;
}

.dataHeader span {
  color: #7f8997;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.dataHeader h2 {
  margin: 3px 0 0;
  font-size: 30px;
}

.dataHeader > button {
  width: 46px;
  height: 46px;

  border: 1px solid #303844;
  border-radius: 13px;

  background: #202731;
  color: white;

  font-size: 24px;
}

.dataOption {
  display: grid;
  grid-template-columns:
    minmax(0, 1fr)
    auto;

  align-items: center;
  gap: 20px;

  padding: 20px 0;

  border-top:
    1px solid #29313b;
}

.dataOption strong {
  font-size: 18px;
}

.dataOption p {
  margin: 6px 0 0;

  color: #8994a2;

  font-size: 14px;
  line-height: 1.45;
}

.dataOption > button,
.dataOption > label {
  min-width: 100px;
  min-height: 48px;

  display: grid;
  place-items: center;

  padding: 0 16px;

  border: 0;
  border-radius: 13px;

  background: #f2f4f6;
  color: #101419;

  cursor: pointer;

  font-weight: 850;
}

.dataOption input {
  display: none;
}

.importDisabled {
  opacity: 0.4;
  pointer-events: none;
}

.dataWarning {
  margin: 16px 0 0;

  color: #737f8e;

  font-size: 12px;
}

@media (max-width: 520px) {
  .dataOption {
    grid-template-columns: 1fr;
  }

  .dataOption > button,
  .dataOption > label {
    width: 100%;
  }
}

/* ==============================
   PENALTY
================================ */

.penaltyPanel {
  max-width: 760px;
  margin: 0 auto;
}

.penaltyPrompt {
  margin: 10px 0 16px;

  color: #8994a2;

  font-size: 17px;
  font-weight: 700;
}

.penaltyPlayers {
  display: grid;
  gap: 10px;
}

.penaltyPlayer {
  display: flex;
  align-items: center;
  justify-content: space-between;

  min-height: 84px;
  padding: 15px 20px;

  border: 1px solid #303844;
  border-radius: 16px;

  background: #171c24;
  color: white;

  text-align: left;
}

.penaltyPlayer > div {
  display: grid;
  gap: 5px;
}

.penaltyPlayer strong {
  font-size: 22px;
  font-weight: 700;
}

.penaltyPlayer span {
  color: #858f9c;

  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.penaltyPlayer b {
  font-size: 30px;
}

.penaltyPlayer:active {
  transform: scale(0.985);
}

.penaltyAction {
  background: #47272b !important;
  color: #f1a0a7 !important;
}


/* ==============================
   JIM ROUND
================================ */

.jimRoundPage {
  width: 100%;
  max-width: 1000px;
  margin: 0 auto;
}

.jimPanel {
  width: 100%;
  max-width: 760px;
  margin: 0 auto;

  display: grid;
  gap: 24px;
}

/* ---------- HEADINGS ---------- */

.jimSectionTitle,
.jimCurrentPlayer,
.jimWinTitle {
  display: grid;
  gap: 5px;
}

.jimSectionTitle span,
.jimCurrentPlayer span,
.jimWinTitle > span {
  color: #8290a2;

  font-size: 11px;
  font-weight: 700;

  letter-spacing: 0.08em;
}

.jimSectionTitle h2,
.jimCurrentPlayer h2,
.jimWinTitle h2 {
  margin: 0;

  color: #f5f7fa;

  font-size: 30px;
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

/* ---------- PLAYER CHOICES ---------- */

.jimPlayerChoices {
  width: 100%;

  display: grid !important;

  grid-template-columns:
    repeat(2, minmax(0, 1fr)) !important;

  gap: 12px !important;
}

.jimPlayerChoice {
  width: 100% !important;
  min-width: 0 !important;

  min-height: 82px;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 14px 18px;

  border: 1px solid #303946 !important;
  border-radius: 16px !important;

  background: #171d25 !important;
  color: #f5f7fa !important;

  font: inherit;
  font-size: 22px !important;
  font-weight: 700 !important;

  text-align: center;

  cursor: pointer;
}

.jimPlayerChoice:hover {
  background: #1d242e !important;
}

.jimPlayerChoice:active {
  transform: scale(0.985);
}

.jimPlayerChoice.selected {
  border-color: #d5ad53 !important;

  background: #332c1f !important;
  color: #f3ce77 !important;
}

/* ---------- PROGRESS ---------- */

.jimProgress {
  width: 100%;

  padding: 24px 20px 22px;

  border: 1px solid #2b333e;
  border-radius: 22px;

  background: #151a21;
}

.jimProgressTop {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  gap: 8px;
  margin-bottom: 22px;

  text-align: center;
}

.jimProgressTop span {
  color: #8290a2;

  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.jimProgressTop strong {
  color: #f5f7fa;

  font-size: 38px;
  line-height: 1;
}

/* ---------- SIX JIM STAGES ---------- */

.jimStages {
  width: 100%;

  display: grid !important;

  grid-template-columns:
    repeat(6, minmax(0, 1fr)) !important;

  gap: 12px !important;

  justify-items: center;
  align-items: start;
  padding-bottom: 20px;
}

.jimStage {
  position: relative;

  width: 72px;
  height: 72px;
  min-width: 72px;
  min-height: 72px;

  display: grid;
  place-items: center;

  border: 2px solid #303946;
  border-radius: 999px;

  background: #10151b;
  color: #697585;

  font-size: 22px;
  font-weight: 700;

  box-shadow:
    inset 0 0 0 1px rgba(255,255,255,0.02);
}

.jimStage.survived {
  border-color: #315940;

  background: #1e3828;
  color: #8fd6a3;
}

.jimStage.current {
  border-color: #d6ae55;

  background: #2b2417;
  color: #f1cc74;
}

.jimStage.hidden {
  border-color: #9171c1;

  background: #302640;
  color: #caadf0;
}

.jimStage small {
  position: absolute;

  left: 50%;
  bottom: -18px;

  transform: translateX(-50%);

  padding: 2px 6px;

  border-radius: 999px;

  background: #5a4680;
  color: #f1e9ff;

  text-align: center;

  font-size: 8px;
  font-weight: 900;
  line-height: 1;

  letter-spacing: 0.08em;
  white-space: nowrap;
}
/* ---------- HIDE ---------- */

.jimHideArea {
  width: 100%;
}

.jimHideButton {
  width: 100% !important;

  min-height: 68px;

  border: 1px solid #8867b7 !important;
  border-radius: 15px !important;

  background: #2c233c !important;
  color: #cbb0ef !important;

  font: inherit;
  font-size: 17px !important;
  font-weight: 700 !important;

  letter-spacing: 0.04em;
}

.jimHideButton:disabled {
  border-color: #2b333e !important;

  background: #171c23 !important;
  color: #606c7b !important;
}

.jimHideUsed {
  width: 100%;
  min-height: 68px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 20px;

  border: 1px solid #8867b7;
  border-radius: 15px;

  background: #2c233c;
  color: #cbb0ef;
}

.jimHideUsed span {
  font-size: 11px;
  font-weight: 900;

  letter-spacing: 0.1em;
}

.jimHideUsed strong {
  font-size: 21px;
}

/* ---------- MAIN JIM BUTTONS ---------- */

.jimMainActions {
  width: 100%;

  display: grid !important;

  grid-template-columns:
    2fr 1fr !important;

  gap: 12px !important;
}

.jimSurvivedButton,
.jimCaughtButton,
.jimConfirmButton {
  width: 100% !important;

  min-height: 70px;

  border: 0 !important;
  border-radius: 15px !important;

  font: inherit;
  font-size: 17px !important;
  font-weight: 700 !important;

  cursor: pointer;
}

.jimSurvivedButton {
  background: #f0f2f5 !important;
  color: #101318 !important;
}

.jimCaughtButton {
  background: #47272c !important;
  color: #f1a0a8 !important;
}

/* ---------- RESULT SUMMARY ---------- */

.jimOutcomeSummary {
  width: 100%;

  display: grid !important;

  grid-template-columns:
    repeat(4, minmax(0, 1fr)) !important;

  gap: 10px !important;
}

.jimOutcomeSummary > div {
  min-width: 0;

  padding: 16px;

  border: 1px solid #29313b;
  border-radius: 14px;

  background: #151a21;
}

.jimOutcomeSummary span {
  display: block;

  margin-bottom: 6px;

  color: #7f8b9a;

  font-size: 9px;
  font-weight: 900;

  letter-spacing: 0.09em;
}

.jimOutcomeSummary strong {
  display: block;

  color: #f5f7fa;

  font-size: 22px;
}

/* ---------- CONFIRM ---------- */

.jimConfirmButton {
  background: #eef1f5 !important;
  color: #101318 !important;
}

.jimConfirmButton:disabled {
  opacity: 0.4;
}

.jimWinConfirm {
  background: #d2ab50 !important;
  color: #17130b !important;
}

/* ---------- WIN ---------- */

.jimWinTitle > strong {
  margin-top: 4px;

  color: #d8b45d;

  font-size: 48px;
  line-height: 1;
}

/* ---------- ROTATION NOTE ---------- */

.jimRotationNote {
  margin: 0;

  color: #909ba8;

  font-size: 15px;
}

/* ---------- SMALLER SCREENS ---------- */

@media (max-width: 600px) {
  .jimPanel {
    gap: 18px;
  }

  .jimPlayerChoices {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }

  .jimPlayerChoice {
    min-height: 72px;

    font-size: 19px !important;
  }

  .jimStages {
    gap: 5px !important;
  }

.jimStage {
  width: 56px;
  height: 56px;
  min-width: 56px;
  min-height: 56px;

  font-size: 18px;
}
  .jimOutcomeSummary {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }

  .jimMainActions {
    grid-template-columns: 1fr !important;
  }
}

/* ==============================
   HISTORY & STATS
================================ */

.historyPage {
  max-width: 1100px;
}

.historyHeader {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-bottom: 26px;
}

.historyHeader > div > span {
  color: #7f8997;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.historyHeader h1 {
  margin: 3px 0 0;
  font-size: 34px;
}

.historyTabs {
  display: grid;
  grid-template-columns:
    repeat(4, 1fr);
  gap: 7px;

  margin-bottom: 22px;
  padding: 6px;

  border-radius: 16px;
  background: #13171d;
}

.historyTabs button {
  min-height: 52px;

  border: 0;
  border-radius: 12px;

  background: transparent;
  color: #7f8997;

  font-weight: 800;
}

.historyTabs button.active {
  background: #29323e;
  color: #f5f7fa;
}

/* SESSION HISTORY */

.historySessionList {
  display: grid;
  gap: 12px;
}

.historySession {
  overflow: hidden;

  border: 1px solid #29313b;
  border-radius: 18px;

  background: #171c24;
}

.historySessionSummary {
  width: 100%;
  min-height: 88px;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  padding: 16px 20px;

  border: 0;

  background: transparent;
  color: #f5f7fa;

  text-align: left;
}

.historySessionSummary > div:first-child {
  display: grid;
  gap: 4px;
}

.historySessionSummary > div:first-child strong {
  font-size: 20px;
}

.historySessionSummary > div:first-child span,
.historySessionSummaryRight > span {
  color: #8793a1;
  font-size: 13px;
}

.historySessionSummaryRight {
  display: flex;
  align-items: center;
  gap: 12px;
}

.historySessionSummaryRight b {
  padding: 5px 8px;

  border-radius: 7px;

  background: #29323d;
  color: #9eabb9;

  font-size: 10px;
  letter-spacing: 0.08em;
}

.historySessionSummaryRight b.active {
  background: #20372a;
  color: #81d499;
}

.historySessionDetails {
  padding: 18px 20px 20px;

  border-top: 1px solid #29313b;
}

.historySessionMeta {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 9px;

  margin-bottom: 16px;
}

.historySessionMeta > div {
  min-width: 0;

  padding: 14px;

  border-radius: 13px;

  background: #11151b;
}

.historySessionMeta span {
  display: block;

  margin-bottom: 5px;

  color: #778392;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.historySessionMeta strong {
  display: block;

  overflow: hidden;

  font-size: 18px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.historyStandings {
  display: grid;
  gap: 7px;
}

.historyStanding {
  display: grid;
  grid-template-columns:
    38px minmax(0, 1fr) auto;
  align-items: center;

  min-height: 62px;

  padding: 8px 14px;

  border-radius: 12px;

  background: #202731;
}

.historyStanding > span {
  color: #788391;
  font-weight: 850;
}

.historyStanding > div {
  display: grid;
  gap: 3px;

  min-width: 0;
}

.historyStanding > div > strong {
  overflow: hidden;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.historyStanding small {
  color: #8994a2;
}

.historyStanding > b {
  font-size: 22px;
}

.historyRaceButton {
  width: 100%;
  min-height: 58px;

  margin-top: 14px;

  border: 0;
  border-radius: 14px;

  background: #303946;
  color: #f5f7fa;

  font-weight: 850;
}

.historyEmpty {
  padding: 50px 20px;

  border: 1px dashed #303844;
  border-radius: 17px;

  color: #7f8997;

  text-align: center;
}

/* PLAYER STATS */

.playerStatsList {
  display: grid;
  gap: 14px;
}

.playerStatsCard {
  padding: 20px;

  border: 1px solid #29313b;
  border-radius: 18px;

  background: #171c24;
}

.playerStatsCard > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  margin-bottom: 18px;
}

.playerStatsCard > header > div {
  display: grid;
  gap: 3px;
}

.playerStatsCard h2 {
  margin: 0;

  font-size: 27px;
}

.playerStatsCard > header span {
  color: #8994a2;
  font-size: 13px;
}

.playerStatsCard > header > strong {
  font-size: 21px;
}

.playerStatSectionLabel {
  margin: 17px 2px 8px;

  color: #7c8795;

  font-size: 14px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.playerStatGrid {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.playerStatGrid > div {
  min-width: 0;

  padding: 14px;

  border-radius: 13px;

  background: #11151b;
}

.playerStatGrid span {
  display: block;

  min-height: 24px;
  margin-bottom: 5px;

  color: #778392;

  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.07em;
}

.playerStatGrid strong {
  font-size: 23px;
}

.hideStageBreakdown {
  display: grid;
  grid-template-columns:
    auto repeat(4, 1fr);
  align-items: center;
  gap: 8px;

  margin-top: 10px;
  padding: 11px 13px;

  border: 1px solid #3c3250;
  border-radius: 13px;

  background: #1d1827;
}

.hideStageBreakdown > span {
  color: #a891c5;

  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.hideStageBreakdown > div {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 5px;
}

.hideStageBreakdown small {
  color: #8f7ba8;
  font-size: 11px;
}

.hideStageBreakdown strong {
  color: #d0b7ef;
}

/* AWARDS */

.historyAwards {
  display: grid;
  gap: 18px;
}

.awardsIntro {
  padding: 5px 2px 2px;
}

.awardsIntro > span {
  color: #d9ae4b;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.awardsIntro h2 {
  margin: 5px 0 6px;

  font-size: 31px;
}

.awardsIntro p {
  max-width: 620px;
  margin: 0;

  color: #8994a2;
  line-height: 1.5;
}

.awardGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.awardCard {
  min-width: 0;

  padding: 20px;

  border: 1px solid #303844;
  border-radius: 18px;

  background: #171c24;
}

.awardCard > span {
  color: #d9ae4b;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.awardCard h3 {
  margin: 8px 0 4px;

  overflow-wrap: anywhere;

  font-size: 27px;
}

.awardCard > strong {
  color: #b5c0cd;

  font-size: 15px;
}

.awardCard p {
  margin: 11px 0 0;

  color: #7f8b99;

  font-size: 13px;
  line-height: 1.4;
}

@media (max-width: 700px) {
  .historySessionMeta {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .playerStatSectionLabel {
    font-size: 13px;
  }

  .playerStatGrid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .playerStatGrid span,
  .hideStageBreakdown > span {
    font-size: 11px;
  }

  .awardGrid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .historySessionSummary {
    align-items: flex-start;
  }

  .historySessionSummaryRight {
    flex-direction: column;
    align-items: flex-end;
    gap: 5px;
  }

  .hideStageBreakdown {
    grid-template-columns:
      1fr 1fr;
  }

  .hideStageBreakdown > span {
    grid-column: 1 / -1;
  }
}


/* ==============================
   SESSION AWARDS
================================ */

.sessionAwardsSection {
  margin-top: 20px;
  padding-top: 18px;

  border-top: 1px solid #29313b;
}

.sessionAwardsHeader {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;

  margin-bottom: 12px;
}

.sessionAwardsHeader span {
  color: #d9ae4b;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.sessionAwardsHeader strong {
  color: #8994a2;

  font-size: 13px;
}

.sessionAwardGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 9px;
}

.sessionAwardCard {
  padding: 15px;

  background: #141920;
}

.sessionAwardCard > span {
  font-size: 9px;
}

.sessionAwardCard h3 {
  margin: 6px 0 3px;

  font-size: 21px;
}

.sessionAwardCard > strong {
  font-size: 13px;
}

.sessionAwardCard p {
  margin-top: 8px;

  font-size: 12px;
}

@media (max-width: 600px) {
  .sessionAwardGrid {
    grid-template-columns: 1fr;
  }

  .sessionAwardsHeader {
    align-items: flex-start;
    flex-direction: column;
    gap: 3px;
  }
}

/* ==============================
   AWARD COLORS + BIGGER TITLES
   History / Session Awards CSS.
================================ */

.awardCard {
  --award-color: #d9ae4b;

  border-left:
    4px solid var(--award-color);
}

.awardCard > span {
  color: var(--award-color);

  font-size: 15px;
  font-weight: 950;
  letter-spacing: 0.08em;
}

.awardCard > strong {
  color: var(--award-color);
}

/* Session cards are smaller overall,
   but the award name should still
   be obvious at a glance. */

.sessionAwardCard > span {
  font-size: 13px;
}

.sessionAwardCard h3 {
  font-size: 23px;
}

/* Each family title gets its own
   stable visual identity. */

.awardTone-cuci {
  --award-color: #6fc8d4;
}

.awardTone-slayer {
  --award-color: #ef7f89;
}

.awardTone-tuah {
  --award-color: #e0b65c;
}

.awardTone-malang {
  --award-color: #b491df;
}

.awardTone-standard {
  --award-color: #79a7f2;
}

.awardTone-jim {
  --award-color: #e79a61;
}

.awardTone-hide {
  --award-color: #bd8fe9;
}

.awardTone-denda {
  --award-color: #e88b9c;
}

.awardTone-survivor {
  --award-color: #7fcf95;
}

.awardTone-comeback {
  --award-color: #67c5b3;
}

.awardTone-jatuh {
  --award-color: #d7838f;
}

.awardTone-default {
  --award-color: #aab5c2;
}

@media (max-width: 600px) {
  .awardCard > span {
    font-size: 14px;
  }

  .sessionAwardCard > span {
    font-size: 12px;
  }
}

/* ==============================
   HISTORY V3
   History / Awards CSS.
================================ */

/* SESSION DETAILS */

.historySessionMetaExpanded {
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
}

/* PLAYER SORTING */

.playerSortPanel {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;

  margin-bottom: 14px;
  padding: 16px 18px;

  border: 1px solid #29313b;
