  border: 1px solid #303945;
  border-radius: 10px;

  background: #202630;
  color: #8f9aa7;

  font-size: 11px;
  font-weight: 850;
}

.playerSortButtons button.active {
  border-color: #59697d;

  background: #344152;
  color: #f5f7fa;
}

.playerStatsIdentity {
  display: flex !important;
