   MVP QUALIFICATION TICKS
================================ */

.mvpSample span.complete {
  background: #1d3025;
  color: #7fd19a;
}

/* ==============================
   MVP PODIUM
================================ */

.mvpPodiumSection {
  padding: 22px 22px 0;

  border: 1px solid #303844;
  border-radius: 18px;

  background:
    radial-gradient(
      circle at 50% 0%,
      rgba(217, 174, 75, 0.11),
      transparent 46%
    ),
    #151a21;
}

.mvpPodiumHeader {
  text-align: center;
}

.mvpPodiumHeader > span,
.mvpLeaderboardHeader > span {
  color: #d9ae4b;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.mvpPodiumHeader h3,
.mvpLeaderboardHeader h3 {
  margin: 4px 0 0;

  font-size: 25px;
}

.mvpPodium {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
  align-items: end;
  gap: 14px;

  max-width: 900px;
  margin: 30px auto 0;
}

.mvpPodiumSlot {
  display: grid;
  grid-template-rows:
    auto auto auto;
  align-items: end;

  min-width: 0;
}

.mvpPodiumPlayer {
  position: relative;

  display: grid;
  justify-items: center;
  gap: 4px;

  padding: 17px 12px 14px;

  border: 1px solid #313a46;
  border-radius: 15px 15px 0 0;

  background: #1b212a;

  text-align: center;
}

.mvpPodiumPlayer > strong {
  max-width: 100%;

  overflow: hidden;

  font-size: 22px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mvpPodiumPlayer > small {
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.09em;
}

.mvpMedal {
  display: grid;
  place-items: center;

  width: 38px;
  height: 38px;

  margin-top: -37px;

  border: 3px solid #151a21;
  border-radius: 50%;

  background: #596473;
  color: #f5f7fa;

  font-size: 16px;
  font-weight: 950;
}

.mvpPodiumScore {
  display: grid;
  justify-items: center;

  padding: 13px 10px;

  border-right: 1px solid #313a46;
  border-left: 1px solid #313a46;

  background: #11151b;
}

.mvpPodiumScore strong {
  font-size: 31px;
  line-height: 1;
}

.mvpPodiumScore span {
  margin-top: 4px;

  color: #7e8997;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.mvpPodiumBlock {
  display: grid;
  place-items: center;

  min-height: 128px;

  border-radius: 0 0 10px 10px;

  background:
    linear-gradient(
      180deg,
      rgba(255,255,255,0.045),
      rgba(255,255,255,0.01)
    ),
    #29323d;
}

.mvpPodiumBlock span {
  color: #cbd3dc;

  font-size: 33px;
  font-weight: 950;
}

/* #1 in the middle, tallest and gold */

.mvpPodiumSlot.rank1
.mvpPodiumPlayer {
  border-color: #6b582a;

  background:
    linear-gradient(
      180deg,
      #262317,
      #1d1d1b
    );
}

.mvpPodiumSlot.rank1
.mvpMedal {
  background: #d9ae4b;
  color: #1a160b;
}

.mvpPodiumSlot.rank1
.mvpPodiumScore strong {
  color: #e8bd57;
}

.mvpPodiumSlot.rank1
.mvpPodiumBlock {
  min-height: 190px;

  background:
    linear-gradient(
      180deg,
      #6c5624,
      #3c311b
    );
}

.mvpPodiumSlot.rank1
.mvpPodiumBlock span {
  color: #f1c969;
}

/* #2 silver */

.mvpPodiumSlot.rank2
.mvpMedal {
  background: #9ca8b5;
  color: #171b20;
}

.mvpPodiumSlot.rank2
.mvpPodiumScore strong {
  color: #c8d0d9;
}

.mvpPodiumSlot.rank2
.mvpPodiumBlock {
  min-height: 145px;

  background:
    linear-gradient(
      180deg,
      #48535f,
      #303a45
    );
}

/* #3 bronze */

.mvpPodiumSlot.rank3
.mvpMedal {
  background: #ba8058;
  color: #1b120c;
}

.mvpPodiumSlot.rank3
.mvpPodiumScore strong {
  color: #d69a70;
}

.mvpPodiumSlot.rank3
.mvpPodiumBlock {
  min-height: 112px;

  background:
    linear-gradient(
      180deg,
      #5d4031,
      #352a25
    );
}

.mvpLeaderboardSection {
  display: grid;
  gap: 13px;

  margin-top: 2px;
}

.mvpLeaderboardHeader {
  padding: 0 2px;
}

/* Make the #1 detailed card a little
   quieter now that the podium is the hero. */

.mvpCard.mvpLeader {
  border-color: #3c4652;

  box-shadow: none;
}

/* Tablet / phone */

@media (max-width: 760px) {
  .mvpPodiumSection {
    padding: 18px 12px 0;
  }

  .mvpPodium {
    gap: 7px;

    margin-top: 28px;
  }

  .mvpPodiumPlayer {
    padding:
      14px 7px 11px;
  }

  .mvpPodiumPlayer > strong {
    font-size: 17px;
  }

  .mvpMedal {
    width: 32px;
    height: 32px;

    margin-top: -31px;

    font-size: 13px;
  }

  .mvpPodiumScore strong {
    font-size: 24px;
  }

  .mvpPodiumBlock span {
    font-size: 27px;
  }

  .mvpPodiumSlot.rank1
  .mvpPodiumBlock {
    min-height: 155px;
  }

  .mvpPodiumSlot.rank2
  .mvpPodiumBlock {
    min-height: 118px;
  }

  .mvpPodiumSlot.rank3
  .mvpPodiumBlock {
    min-height: 90px;
  }
}

@media (max-width: 520px) {
  .mvpPodium {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }

  .mvpPodiumPlayer > strong {
    font-size: 14px;
  }

  .mvpPodiumPlayer > small {
    font-size: 6px;
  }

  .mvpPodiumScore {
    padding:
      10px 4px;
  }

  .mvpPodiumScore strong {
    font-size: 20px;
  }
}


/* ==============================
   STANDARD ROUND — QUICK RANK
   Round CSS.
================================ */

.standardModeBar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;

  max-width: 760px;
  margin: 0 auto 18px;
  padding: 14px 16px;

  border: 1px solid #2c3540;
  border-radius: 15px;

  background: #151a21;
}

.standardModeBar > div {
  display: grid;
  gap: 3px;
}

.standardModeBar > div > span {
  color: #7f8b99;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.standardModeBar > div > strong {
  font-size: 16px;
}

.standardModeButton {
  flex: 0 0 auto;

  min-height: 40px;
  padding: 0 14px;

  border: 1px solid #3a4552;
  border-radius: 10px;

  background: #252d38;
  color: #dfe5eb;

  font-size: 11px;
  font-weight: 850;
}

.quickRankPanel {
  position: relative;

  max-width: 760px;
  margin: 0 auto 18px;
}

.quickRankList {
  display: grid;

  margin: 0;
  padding: 0;

  list-style: none;
}

.quickRankItem {
  position: relative;

  margin: 0;
  padding: 0;

  list-style: none;

  touch-action: none;
}

.quickRankCard {
  display: grid;
  grid-template-columns:
    54px minmax(0, 1fr) auto 30px;
  align-items: center;
  gap: 13px;

  min-height: 84px;
  padding: 12px 16px;

  border: 1px solid #303a46;
  border-radius: 16px;

  background: #1a2028;

  cursor: grab;
  user-select: none;
}

.quickRankCard:active {
  cursor: grabbing;
}

.quickRankNumber {
  display: grid;
  place-items: center;

  width: 42px;
  height: 42px;

  border-radius: 12px;

  background: #252e39;
  color: #9ba8b6;

