}

/*
  The small divider between cards is
  the "connect these two" control.
*/
.rankTieConnector {
  position: relative;
  z-index: 3;

  display: grid;
  place-items: center;

  width: calc(100% - 36px);
  height: 24px;
  margin: -1px 18px;

  border: 0;

  background: transparent;
}

.rankTieConnector::before {
  content: '';

  position: absolute;

  left: 0;
  right: 0;
  top: 50%;

  height: 1px;

  background: #27303a;
}

.rankTieConnector > span {
  position: relative;
  z-index: 1;

  display: grid;
  place-items: center;

  min-width: 30px;
  height: 20px;
  padding: 0 7px;

  border: 1px solid #34404d;
  border-radius: 999px;

  background: #11161c;
  color: #7e8997;

  font-size: 10px;
  font-weight: 950;
  letter-spacing: 0.05em;
}

.rankTieConnector.active {
  height: 30px;

  margin-top: -4px;
  margin-bottom: -4px;

  border-right: 2px solid #856fd0;
  border-left: 2px solid #856fd0;

  background:
    rgba(133, 111, 208, 0.08);
}

.rankTieConnector.active::before {
  background: #856fd0;
}

.rankTieConnector.active > span {
  border-color: #856fd0;

  background: #302747;
  color: #c9b8f3;
}

.quickRankCard.tiedWithNext,
.quickRankCard.tiedWithPrevious {
  border-color: #6757a1;

  background:
    linear-gradient(
      90deg,
      rgba(116, 91, 180, 0.08),
      #1a2028 45%
    );
}

.quickRankCard.tiedWithNext {
  border-bottom-right-radius: 8px;
  border-bottom-left-radius: 8px;
}

.quickRankCard.tiedWithPrevious {
  border-top-right-radius: 8px;
  border-top-left-radius: 8px;
}

.quickRankCard.tiedWithNext
.quickRankPlayer span,
.quickRankCard.tiedWithPrevious
.quickRankPlayer span {
  color: #aa98db;
}

.quickRankHint {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 16px;

  margin-top: 13px;

  color: #74808e;

  font-size: 10px;
  font-weight: 750;
}

.quickRankToast {
