  color: #f2f5f8;

  font-size: 18px;
  font-weight: 950;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.previousWinnerIcon {
  display: grid;
  place-items: center;

  width: 32px;
  height: 32px;

  border-radius: 10px;

  font-size: 15px;
  font-weight: 950;
}

