  flex: 0 0 auto;

  padding: 5px 8px;

  border-radius: 7px;

  font-size: 8px;
  font-weight: 950;
  letter-spacing: 0.1em;
}

.playerStatusTag.playing {
  border:
    1px solid #28533a;

  background: #183324;
  color: #72cf93;
}

.playerStatusTag.waiting {
  border:
    1px solid #5a4920;

  background: #342a16;
  color: #e2bd61;
}

/* ---------- ACHIEVEMENTS ---------- */

.standingAchievements {
