.roundEditDragItem:active
.roundEditDragRow {
  border-color: #5b6b7d;

  background: #1d252f;

  box-shadow:
    0 10px 28px
    rgba(0, 0, 0, 0.3);
}

.roundEditDragPosition {
  display: grid;
  place-items: center;

  width: 26px;
  height: 26px;

  border-radius: 8px;

  background: #222b35;
  color: #9ca9b7;

  font-size: 11px;
  font-weight: 900;
}

.roundEditDragRow > strong {
  overflow: hidden;

  color: #edf1f4;

  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.roundEditDragHandle {
  display: grid;
  place-items: center;

  width: 34px;
  height: 34px;

  border: 1px solid #3e4a57;
  border-radius: 9px;

  background: #222a34;
  color: #aab6c2;

  font-size: 16px;
  font-weight: 900;
}

.roundEditDragHint {
  margin-top: -3px;

  color: #6f7c89;

  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.025em;
}

/* ---------- JIM: CUSTOM CHOICE CONTROLS ---------- */

.roundEditChoiceField {
  display: grid;
  gap: 7px;
}

.roundEditChoiceField > span {
  color: #7f8b99;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.roundEditChoiceGrid {
  display: grid;
  grid-template-columns:
    repeat(
      auto-fit,
      minmax(120px, 1fr)
    );
  gap: 7px;
}

.roundEditChoiceGrid button,
.roundEditNumberChoices button,
.roundEditHideChoices button {
  min-height: 42px;
  padding: 0 12px;

  border: 1px solid #38434f;
  border-radius: 10px;

  background: #1c232c;
  color: #9da9b6;

  font: inherit;
  font-size: 11px;
  font-weight: 850;

  transition:
    border-color 120ms ease,
    background 120ms ease,
    color 120ms ease,
    transform 120ms ease;
}

.roundEditChoiceGrid button:hover,
.roundEditNumberChoices button:hover,
.roundEditHideChoices button:hover {
  border-color: #536273;

  background: #232c36;
  color: #dce2e8;
}

.roundEditChoiceGrid button:active,
.roundEditNumberChoices button:active,
.roundEditHideChoices button:active {
  transform: translateY(1px);
}

/* Generic selected state */
.roundEditChoiceGrid button.active,
.roundEditNumberChoices button.active,
.roundEditHideChoices button.active {
  border-color: #637487;

  background: #2a3542;
  color: #eef2f5;

  box-shadow:
    inset 0 0 0 1px
    rgba(255, 255, 255, 0.025);
}

/* Catcher selection */
.roundEditChoiceGrid button.active.caught {
  border-color: #754852;

  background: #3a242a;
  color: #ef98a2;
}

/* Hide selection */
.roundEditHideChoices button.active.hide {
  border-color: #765a98;

  background: #30253f;
  color: #d8baf5;
}

/* 0–5 stages */
.roundEditNumberChoices {
  display: grid;
  grid-template-columns:
    repeat(6, minmax(0, 1fr));
  gap: 6px;
}

.roundEditNumberChoices button {
  padding: 0;

  font-size: 13px;
}

/* No Hide + stages 2–5 */
.roundEditHideChoices {
  display: grid;
  grid-template-columns:
    repeat(5, minmax(0, 1fr));
  gap: 6px;
}

/* ---------- SMALL SCREENS ---------- */

@media (max-width: 620px) {
  .roundEditDragRow {
    grid-template-columns:
      30px minmax(0, 1fr) 36px;

    min-height: 48px;
  }

  .roundEditChoiceGrid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .roundEditNumberChoices {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }

  .roundEditHideChoices {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .roundEditHideChoices
  button:first-child {
    grid-column: 1 / -1;
  }
}

/* =========================================
   ROUND EDITOR — QUICK-RANK STYLE TIES
   Append to the VERY BOTTOM of index.css
========================================= */

/* Let the connector occupy the gap between
   the ranking cards. */
.roundEditDragList {
  gap: 0 !important;
}

.roundEditDragItem {
  display: grid;
  padding-bottom: 7px;
}

.roundEditDragItem.hasTieConnector {
  padding-bottom: 0;
}

/* The small divider between positions is
   now the tie control, matching Quick Rank. */
.roundEditTieConnector {
  position: relative;
  z-index: 3;

  display: grid;
  place-items: center;

  width: calc(100% - 36px);
  height: 24px;
  margin: -1px 18px;
  padding: 0;

  border: 0;

  background: transparent;

  cursor: pointer;
  touch-action: manipulation;
}

.roundEditTieConnector::before {
  content: '';

  position: absolute;
  left: 0;
  right: 0;
  top: 50%;

  height: 1px;

  background: #27303a;
}

.roundEditTieConnector > span {
  position: relative;
  z-index: 1;

  display: grid;
  place-items: center;

  min-width: 30px;
  height: 20px;
  padding: 0 7px;

  border: 1px solid #34404d;
  border-radius: 999px;

  background: #11161c;
  color: #7e8997;

  font-size: 10px;
  font-weight: 950;
  letter-spacing: 0.05em;
}

.roundEditTieConnector:hover > span {
  border-color: #526071;
  color: #a8b3c0;
}

/* Active tie: same purple connector language
   as the normal Standard Quick Rank screen. */
.roundEditTieConnector.active {
  height: 30px;
  margin-top: -4px;
  margin-bottom: -4px;

  border-right: 2px solid #856fd0;
  border-left: 2px solid #856fd0;

  background: rgba(133, 111, 208, 0.08);
}

.roundEditTieConnector.active::before {
  background: #856fd0;
}

.roundEditTieConnector.active > span {
  border-color: #856fd0;

  background: #302747;
  color: #c9b8f3;
}

/* Highlight the two cards belonging to the
   active tie. */
.roundEditDragRow.tiedWithNext,
.roundEditDragRow.tiedWithPrevious {
  border-color: #6757a1;

  background:
    linear-gradient(
      90deg,
      rgba(116, 91, 180, 0.08),
      #161c23 45%
    );
}

.roundEditDragRow.tiedWithNext {
  border-bottom-right-radius: 8px;
  border-bottom-left-radius: 8px;
}

.roundEditDragRow.tiedWithPrevious {
  border-top-right-radius: 8px;
  border-top-left-radius: 8px;
}

.roundEditDragRow.tiedWithNext
.roundEditDragPosition,
.roundEditDragRow.tiedWithPrevious
.roundEditDragPosition {
  background: #302747;
  color: #c9b8f3;
}

/* Replace the old one-line hint with the
   compact Quick Rank-style legend. */
.roundEditDragHint {
  display: flex !important;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 16px;

  margin-top: 7px !important;

  color: #74808e;

  font-size: 10px !important;
  font-weight: 750 !important;
}

@media (max-width: 620px) {
  .roundEditTieConnector {
    width: calc(100% - 24px);
    margin-right: 12px;
    margin-left: 12px;
  }

  .roundEditDragHint {
    gap: 5px 12px;
  }
}

/* =========================================
   SCOREBOARD — JIM WIN STAR / HIDE MARKER
   Append to the VERY BOTTOM of index.css

   Gold star = Jim win
   Purple ring = Hide was used for that win
   No ring = hideless Jim win
========================================= */

.jimWinStars {
  gap: 3px !important;
}

.jimWinStars > .jimWinStar {
  display: inline-grid;
  place-items: center;

  width: 21px;
  height: 21px;

  box-sizing: border-box;

  border: 1px solid transparent;
  border-radius: 50%;

  color: #e3b64b;

  font-size: 14px;
  line-height: 1;

  filter:
    drop-shadow(
      0 0 4px
      rgba(227, 182, 75, 0.15)
    );
}

/* Jim win where Hide was used. */
.jimWinStars >
.jimWinStar.usedHide {
  border-color: #8d6ac0;

  background:
    rgba(141, 106, 192, 0.07);

  box-shadow:
    inset 0 0 0 1px
      rgba(141, 106, 192, 0.08),
    0 0 5px
      rgba(141, 106, 192, 0.15);
}

/* Keep identical dimensions so stars
   remain perfectly aligned. */
.jimWinStars >
.jimWinStar.hideless {
  border-color: transparent;
}

@media (max-width: 620px) {
  .jimWinStars >
  .jimWinStar {
    width: 19px;
    height: 19px;

    font-size: 13px;
  }
}

/* =========================================
   JIM HIDE MARKERS — TRANSITION + PREVIOUS WINNER
   Append to the VERY BOTTOM of index.css

   Gold star only = hideless Jim
   Gold star + purple ring = Hide used
========================================= */

/* ---------- SCORE TRANSITION ---------- */

.scoreJimStars {
  gap: 3px !important;
}

.scoreJimStars >
.scoreJimStar {
  display: inline-grid;
  place-items: center;

  width: 19px;
  height: 19px;

  box-sizing: border-box;

  border: 1px solid transparent;
  border-radius: 50%;

  color: #e3b64b;

  font-size: 13px;
  line-height: 1;
}

.scoreJimStars >
.scoreJimStar.usedHide {
  border-color: #8d6ac0;

  background:
    rgba(141, 106, 192, 0.07);

  box-shadow:
    inset 0 0 0 1px
      rgba(141, 106, 192, 0.08),
    0 0 5px
      rgba(141, 106, 192, 0.14);
}

/* Reward bubble shown when a fresh Jim win
   is awarded during the transition. */
.rewardStar {
  display: inline-grid;
  place-items: center;

  width: 21px;
  height: 21px;

  box-sizing: border-box;

  border: 1px solid transparent;
  border-radius: 50%;
}

.rewardStar.usedHide {
  border-color: #8d6ac0;

  background:
    rgba(141, 106, 192, 0.08);

  box-shadow:
    0 0 5px
      rgba(141, 106, 192, 0.15);
}

/* ---------- PREVIOUS ROUND WINNER ---------- */

/* Keep the existing gold Jim appearance.
   Only add purple language when that Jim
   round used Hide. */
.previousWinnerIcon.jim.usedHide {
  border: 1px solid #8d6ac0;

  box-shadow:
    inset 0 0 0 1px
      rgba(141, 106, 192, 0.08),
    0 0 6px
      rgba(141, 106, 192, 0.16);
}

@media (max-width: 620px) {
  .scoreJimStars >
  .scoreJimStar {
    width: 18px;
    height: 18px;

    font-size: 12px;
  }

  .rewardStar {
    width: 20px;
    height: 20px;
  }
}

/* ==============================
   JIMRAMI IN-APP DIALOGS
================================ */

.jimDialogOverlay {
  position: fixed;
  inset: 0;
  z-index: 220;

  display: grid;
  place-items: center;

  padding: 22px;

  background:
    rgba(4, 6, 9, 0.7);
}

.jimDialog {
  width: min(
    100%,
    420px
  );

  padding: 24px;

  border: 1px solid #39414c;
  border-radius: 20px;

  background: #202731;
  color: #f2f4f6;

  box-shadow:
    0 24px 70px
    rgba(0, 0, 0, 0.45);
}

.jimDialog h3 {
  margin: 0;

  font-size: 22px;
}

.jimDialog p {
  margin: 12px 0 0;

  color: #a4adba;

  font-size: 15px;
  line-height: 1.5;
  white-space: pre-line;
}

.jimDialogActions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;

  margin-top: 24px;
}

.jimDialogActions button {
  min-width: 96px;
  min-height: 46px;

  padding: 0 16px;

  border-radius: 13px;

  cursor: pointer;
  font-weight: 850;
}

.jimDialogPrimary {
  border: 0;

  background: #f2f4f6;
  color: #101419;
}

.jimDialogSecondary {
  border: 1px solid #3a4350;

  background: #171c24;
  color: #f2f4f6;
}

@media (max-width: 520px) {
  .jimDialogActions {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .jimDialogActions button {
    width: 100%;
  }
}


/* =========================================
   JIM DATA — DISABLED CLOUD ACTIONS
========================================= */

.dataOption > button:disabled {
  background: #3a414b !important;
  color: #7f8995 !important;
  opacity: 0.65;
  cursor: not-allowed !important;
  box-shadow: none !important;
  transform: none !important;
}

.dataOption > button:disabled:hover,
.dataOption > button:disabled:active {
  background: #3a414b !important;
  color: #7f8995 !important;
  transform: none !important;
}

/* =========================================
   JIM DATA — CLOUD STATUS / ADVANCED DETAILS
========================================= */

.cloudStatusMessage {
  max-width: 680px;
  margin-top: 7px !important;
}

.cloudStatusMessage.warning {
  color: #d8a0a6 !important;
}

.cloudAdvancedWrap {
  border-top: 1px solid #222a34;
}

.cloudAdvancedToggle {
  display: flex;
  width: 100%;
  min-height: 52px;
  align-items: center;
  justify-content: space-between;

  padding: 0 4px;

  border: 0;

  background: transparent;
  color: #8f9baa;

  font-size: 12px;
  font-weight: 850;
  letter-spacing: 0.04em;
  text-align: left;
}

.cloudAdvancedToggle:hover {
  color: #c5ced8;
}

.cloudAdvancedToggle > span:last-child {
  font-size: 20px;
  font-weight: 500;
}

.cloudAdvancedPanel {
  margin-bottom: 14px;
  padding: 16px;

  border: 1px solid #2c3540;
  border-radius: 14px;

  background: #11171e;
}

.cloudAdvancedHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;

  margin-bottom: 13px;
}

.cloudAdvancedHeader > strong {
  color: #dce3ea;
  font-size: 13px;
}

.cloudAdvancedHeader > button {
  min-height: 34px;
  padding: 0 11px;

  border: 1px solid #384451;
  border-radius: 9px;

  background: #1c242d;
  color: #aeb9c5;

  font-size: 10px;
  font-weight: 850;
}

.cloudAdvancedHeader > button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.cloudAdvancedGrid {
  display: grid;

  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 8px;
  margin: 0;
}

.cloudAdvancedGrid > div {
  min-width: 0;
  padding: 10px 11px;

  border: 1px solid #27313b;
  border-radius: 10px;

  background: #161d25;
}

.cloudAdvancedGrid dt {
  margin: 0 0 4px;

  color: #687687;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.cloudAdvancedGrid dd {
  min-width: 0;
  margin: 0;

  overflow-wrap: anywhere;

  color: #c8d1db;

  font-size: 11px;
  font-weight: 750;
}

.cloudAdvancedNote,
.cloudAdvancedError {
  margin: 12px 2px 0 !important;

  font-size: 10px !important;
  line-height: 1.5 !important;
}

.cloudAdvancedNote {
  color: #687687 !important;
}

.cloudAdvancedError {
  color: #c9868d !important;
}

@media (max-width: 620px) {
  .cloudAdvancedGrid {
    grid-template-columns: 1fr;
  }
}

/* =========================================
   JIM DATA — SCROLLABLE BACKUP PANEL
========================================= */

.dataOverlay {
  overflow-y: auto !important;
  overscroll-behavior: contain;
}

.dataPanel {
  max-height: calc(100dvh - 40px) !important;
  overflow-y: auto !important;

  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
}

/* Keep some breathing room at the bottom */
.dataPanel {
  margin-top: 20px;
  margin-bottom: 20px;
}

/* =========================================
   JIM DATA — CLOUD TEXT SIZE + HIDE SCROLLBAR
========================================= */

.cloudStatusOption p,
.cloudStatusMessage {
  font-size: 13px !important;
  line-height: 1.45 !important;
}

.cloudStatusOption p strong,
.cloudStatusMessage strong {
  font-size: inherit !important;
}

/* Hide scrollbar but keep scrolling */
.dataOverlay,
.dataPanel {
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.dataOverlay::-webkit-scrollbar,
.dataPanel::-webkit-scrollbar {
  display: none;
}

/* =========================================
   ANDROID APP POLISH
========================================= */

/* Let the Android status-bar safe area
   blend into the JIMRAMI background */
html,
body,
#root {
  background-color: #0d1015 !important;
}

/* Remove Android/WebView blue tap flash */
button,
a,
input,
select,
textarea,
[role="button"] {
  -webkit-tap-highlight-color: transparent;
}

/* Don't leave a focus rectangle after touch */
button:focus:not(:focus-visible),
a:focus:not(:focus-visible),
[role="button"]:focus:not(:focus-visible) {
  outline: none;
}

/* =========================================
   ANDROID — DOUBLE BACK TO EXIT
========================================= */

.androidExitHint {
  position: fixed;
  left: 50%;
  bottom: calc(24px + env(safe-area-inset-bottom));
  z-index: 9999;

  transform: translateX(-50%);

  padding: 10px 16px;
  border: 1px solid #2f3945;
  border-radius: 999px;

  background: rgba(18, 24, 31, 0.96);
  color: #dbe3ec;

  font-size: 12px;
  font-weight: 800;
  line-height: 1;
  white-space: nowrap;

  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.28);

  pointer-events: none;
}

/* =========================================
   JIMRAMI — PAGE TRANSITIONS
========================================= */

@keyframes jimPageEnter {
  from {
    opacity: 0;
    transform: translateY(6px) scale(0.995);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.app {
  animation:
    jimPageEnter
    180ms
    cubic-bezier(0.22, 1, 0.36, 1);
}

/* Respect Android accessibility settings */
@media (prefers-reduced-motion: reduce) {
  .app {
    animation: none;
  }
}

/* =========================================
   JIMRAMI — PAGE TRANSITIONS V2
========================================= */

/* History tabs:
   keep the header/tab bar still, animate only
   the content underneath it. */
@keyframes jimHistoryTabEnter {
  from {
    opacity: 0;
    transform: translateY(8px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.historyTabPage {
  animation:
    jimHistoryTabEnter
    200ms
    cubic-bezier(0.22, 1, 0.36, 1)
    both;
}


/* Score Transition gets a slightly clearer
   full-page entrance than ordinary pages. */
@keyframes jimScoreTransitionEnter {
  from {
    opacity: 0;
    transform:
      translateY(10px)
      scale(0.992);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }
}

@keyframes jimScoreTransitionExit {
  from {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }

  to {
    opacity: 0;
    transform:
      translateY(-6px)
      scale(0.996);
  }
}

.scoreTransitionShell
  > .cleanTransitionPage {
  animation:
    jimScoreTransitionEnter
    220ms
    cubic-bezier(0.22, 1, 0.36, 1)
    both !important;
}

.scoreTransitionShell.leaving
  > .cleanTransitionPage {
  animation:
    jimScoreTransitionExit
    160ms
    ease-in
    forwards !important;

  pointer-events: none;
}


/* Accessibility */
@media (prefers-reduced-motion: reduce) {
  .historyTabPage,
  .scoreTransitionShell
    > .cleanTransitionPage,
  .scoreTransitionShell.leaving
    > .cleanTransitionPage {
    animation: none !important;
  }
}

/* =========================================
   JIM ROUND — INTERNAL PHASE TRANSITIONS
========================================= */

@keyframes jimPhaseEnter {
  from {
    opacity: 0;
    transform:
      translateY(8px)
      scale(0.995);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }
}

.jimPhasePage {
  animation:
    jimPhaseEnter
    200ms
    cubic-bezier(0.22, 1, 0.36, 1)
    both;
}

@media (prefers-reduced-motion: reduce) {
  .jimPhasePage {
    animation: none;
  }
}

/* =========================================
   JIMRAMI — APP LAUNCH INTRO
========================================= */

@keyframes jimLaunchBrandIn {
  0% {
    opacity: 0;
    transform:
      translateY(10px)
      scale(0.94);
  }

  55% {
    opacity: 1;
  }

  100% {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }
}

@keyframes jimLaunchScreenOut {
  0% {
    opacity: 1;
  }

  100% {
    opacity: 0;
  }
}

.launchIntro {
  position: fixed;
  inset: 0;
  z-index: 100000;

  display: grid;
  place-items: center;

  background: #0d1015;

  pointer-events: none;

  animation:
    jimLaunchScreenOut
    240ms
    ease
    720ms
    forwards;
}

.launchIntroBrand {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;

  animation:
    jimLaunchBrandIn
    480ms
    cubic-bezier(0.22, 1, 0.36, 1)
    both;
}

.launchIntroBrand img {
  display: block;
  width: min(230px, 42vw);
  max-height: 120px;
  object-fit: contain;
}

.launchIntroBrand strong {
  color: #f4f6f8;

  font-size: clamp(
    28px,
    5vw,
    52px
  );

  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.04em;
}

@media (prefers-reduced-motion: reduce) {
  .launchIntro,
  .launchIntroBrand {
    animation: none;
  }

  .launchIntro {
    opacity: 0;
  }
}

/* =========================================
   JIMRAMI — APP LAUNCH INTRO V2
   Put Jim_Card.svg in: public/Jim_Card.svg
========================================= */

@keyframes jimLaunchCardIn {
  0% {
    opacity: 0;
    transform:
      translateY(12px)
      rotate(-4deg)
      scale(0.9);
  }

  100% {
    opacity: 1;
    transform:
      translateY(0)
      rotate(0deg)
      scale(1);
  }
}

@keyframes jimLaunchJawiIn {
  0% {
    opacity: 0;
    transform:
      translateY(8px)
      scale(0.96);
  }

  100% {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }
}

@keyframes jimLaunchTitleIn {
  0% {
    opacity: 0;
    letter-spacing: 0.08em;
  }

  100% {
