  box-shadow: 0 22px 80px rgba(0, 0, 0, .55), 0 0 55px rgba(185, 124, 41, .09);
  text-align: center;
  animation: jimIntroAppear .28s ease-out both;
}
.jimIntroKicker { color: #d1b578; font-size: 12px; font-weight: 900; letter-spacing: .20em; }
.jimIntroSymbol {
  width: 94px;
  height: 94px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid rgba(214, 176, 92, .35);
  background: rgba(233, 175, 74, .09);
  color: #ecc16a;
  font-size: 60px;
  line-height: 1;
}
.jimIntroModal h2 {
  margin: 0;
  color: #f7f8fa;
  font-size: clamp(28px, 6vw, 38px);
  font-weight: 850;
  overflow-wrap: anywhere;
  line-height: 1.15;
}
.jimIntroWave { display: flex; align-items: center; justify-content: center; gap: 4px; height: 48px; }
.jimIntroWave span {
  display: block;
  width: 4px;
  height: 25%;
  border-radius: 5px;
  background: #e6b762;
  transform-origin: center;
  animation: jimIntroPulse .75s ease-in-out infinite alternate;
}
.jimIntroModal p { margin: 0; color: #abb5c1; font-size: 14px; }
.jimIntroSkip {
  margin-top: 4px;
  padding: 10px 18px;
  border: 1px solid #46505d;
  border-radius: 12px;
  background: #252d37;
