}
.jimIntroSkip:focus-visible { outline: 2px solid #f0c56d; outline-offset: 3px; }
@keyframes jimIntroAppear { from { opacity: 0; transform: scale(.94) translateY(9px); } to { opacity: 1; transform: scale(1) translateY(0); } }
@keyframes jimIntroPulse { from { height: 18%; opacity: .60; } to { height: 92%; opacity: 1; } }
@media (prefers-reduced-motion: reduce) {
  .jimIntroModal, .jimIntroWave span { animation: none; }
  .jimIntroWave span { height: 36%; }
}

/* Personal JIM voice recorder */
.jimVoiceEditor { display: grid; gap: 10px; padding: 16px; margin: 16px 0; border: 1px solid #334155; border-radius: 14px; }
.jimVoiceEditor p { margin: 0; font-size: 0.9rem; color: #9ca3af; }
.jimVoiceEditor audio { width: 100%; max-width: 100%; }
.jimVoiceEditor > span { font-size: .8rem; color: #94a3b8; }
.jimVoiceButtons { display: flex; flex-wrap: wrap; gap: 8px; }
.jimVoiceButtons button { padding: 10px 14px; border-radius: 9px; border: 1px solid #475569; background: #263343; color: #fff; cursor: pointer; }
.jimVoiceButtons button:disabled { opacity: .5; cursor: not-allowed; }

/* =======================================================
   JIM VOICE — custom playback + delete confirmation
   Append to the bottom of src/index.css. App.css untouched.
   ======================================================= */

.jimVoiceEditor .jimVoicePlayback {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.jimVoiceEditor .jimVoiceClipLabel {
  color: #9aa7b8;
  font-size: 12px;
  line-height: 1.2;
  font-weight: 500;
}

.jimVoiceEditor .jimVoicePlayer {
  display: flex;
  align-items: center;
  gap: 13px;
  width: 100%;
  min-width: 0;
  padding: 10px 13px;
  background: #111720;
  border: 1px solid #354253;
  border-radius: 13px;
  box-sizing: border-box;
}

.jimVoiceEditor .jimVoicePlayer audio {
  display: none;
}

.jimVoiceEditor .jimVoicePlayButton {
  flex: 0 0 40px;
  height: 40px;
  width: 40px;
  display: grid;
  place-items: center;
  border-radius: 11px;
  border: 1px solid #526279;
  background: #263447;
  color: #e9f0f9;
  cursor: pointer;
  padding: 0;
}
.jimVoiceEditor .jimVoicePlayButton:active { transform: scale(.96); }
.jimVoiceEditor .jimVoicePlayButton:focus-visible,
.jimVoiceEditor .jimVoiceSeek:focus-visible {
  outline: 2px solid #e7bb62;
  outline-offset: 3px;
}

/* The editor stays scrollable even while the background page is locked. */
.playerEditorOverlay { overscroll-behavior: contain; align-items: safe center; }
.playerEditorDialog {
  max-height: calc(100dvh - 36px);
  overflow-y: auto;
  overscroll-behavior: contain;
}

.jimVoiceEditor .jimVoiceWaveArea {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  height: 38px;
  display: grid;
  align-items: center;
}

.jimVoiceEditor .jimVoiceWaveArea:focus-within {
  outline: 2px solid #e7bb62;
  outline-offset: 2px;
  border-radius: 3px;
}

.jimVoiceEditor .jimVoiceWave {
  height: 30px;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2px;
  overflow: hidden;
  pointer-events: none;
}
.jimVoiceEditor .jimVoiceWave > span {
  flex: 1 1 0;
  min-width: 1px;
  max-width: 4px;
  border-radius: 4px;
  background: #4b5a6d;
  transition: background 120ms;
}
.jimVoiceEditor .jimVoiceWave > span.played {
  background: #ddb76f;
}

.jimVoiceEditor .jimVoiceSeek {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  padding: 0;
  margin: 0;
  opacity: 0;
  cursor: pointer;
  touch-action: pan-y;
}
.jimVoiceEditor .jimVoiceSeek:disabled { cursor: default; }

.jimVoiceEditor .jimVoiceClock {
  font-size: 11px;
  color: #a8b4c1;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}
.jimVoiceEditor .jimVoicePlaybackError {
  color: #f2a6ad;
  font-size: 12px;
}

/* Overlay sits above Edit Player, including on Android WebView. */
.jimVoiceConfirmBackdrop {
  position: fixed;
  inset: 0;
  z-index: 2400;
  display: grid;
  place-items: center;
  padding: 20px;
  box-sizing: border-box;
  background: rgba(5, 8, 12, .78);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
.jimVoiceConfirmDialog {
