  padding: 27px;
  background: #191f28;
  border: 1px solid #394555;
  border-radius: 20px;
  box-shadow: 0 28px 75px rgba(0,0,0,.5);
  color: #f4f6f9;
}
.jimVoiceConfirmEyebrow {
  display: block;
  color: #e8a5aa;
  font-size: 10px;
  font-weight: 850;
  letter-spacing: .12em;
  margin-bottom: 8px;
}
.jimVoiceConfirmDialog h3 {
  margin: 0 0 10px;
  font-size: 24px;
  font-weight: 800;
  letter-spacing: -.025em;
}
.jimVoiceConfirmDialog p {
  margin: 0 0 23px;
  color: #aab5c2;
  font-size: 14px;
  line-height: 1.55;
}
.jimVoiceConfirmDialog p strong { color: #f3f5f7; }
.jimVoiceConfirmActions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}
.jimVoiceConfirmActions button {
  min-height: 46px;
  padding: 10px 14px;
  border-radius: 11px;
  font: inherit;
  font-weight: 750;
