/* JIM FAIL SKULLS | 1 skull = 1 JIM player caught (not the catcher).
   Paired with the existing tally / star / scissors icons. */
.jimFailSkulls {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 2px;
  margin: 0;
  line-height: 1;
}
.jimFailSkull,
.rewardJimSkull {
  display: inline-grid;
  place-items: center;
  width: 21px;
  height: 21px;
  color: #ac8894;
  flex: 0 0 auto;
}
.jimFailSkull svg,
.rewardJimSkull svg {
  width: 18px;
  height: 18px;
  display: block;
}
.jimFailSkulls.transition .jimFailSkull {
  width: 19px;
  height: 19px;
}
.jimFailSkulls.transition .jimFailSkull svg {
  width: 17px;
  height: 17px;
}
.jimFailSkulls.pop {
  animation: achievementPop 650ms cubic-bezier(0.22, 1.4, 0.36, 1);
}
.historyStandingAchievements .jimFailSkulls,
.sessionPlayerDetailAchievements .jimFailSkulls,
.goalpostPodiumAccolades .jimFailSkulls {
  margin: 0 !important;
}
.goalpostPodiumAccolades .jimFailSkulls {
  justify-content: flex-start;
}
/* Four distinct categories in the session player detail modal. */
.sessionPlayerDetailAchievements {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
@media (max-width: 700px) {
  .sessionPlayerDetailAchievements {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 620px) {
  .jimFailSkull,
  .rewardJimSkull {
    width: 19px;
    height: 19px;
