  .jimFailSkull svg,
  .rewardJimSkull svg {
    width: 16px;
    height: 16px;
  }
}

/* JIM voice recording indicator */

.jimVoiceRecordingStatus {
  display: flex;
  align-items: center;
  gap: 8px;
}

.jimVoiceRecordingDot {
  width: 10px;
  height: 10px;
  flex-shrink: 0;
  border-radius: 50%;
  background: #ff3b46;
  box-shadow: 0 0 7px rgba(255, 59, 70, 0.5);
  animation: jimRecordBlink 1s ease-in-out infinite;
}

@keyframes jimRecordBlink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.15; }
}

@media (prefers-reduced-motion: reduce) {
  .jimVoiceRecordingDot {
    animation: none;
  }
