================================ */

.historyPage {
  max-width: 1100px;
}

.historyHeader {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-bottom: 26px;
}

.historyHeader > div > span {
  color: #7f8997;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.historyHeader h1 {
  margin: 3px 0 0;
  font-size: 34px;
}

.historyTabs {
  display: grid;
  grid-template-columns:
    repeat(4, 1fr);
  gap: 7px;

  margin-bottom: 22px;
  padding: 6px;

  border-radius: 16px;
  background: #13171d;
}

.historyTabs button {
  min-height: 52px;

  border: 0;
  border-radius: 12px;

  background: transparent;
  color: #7f8997;

  font-weight: 800;
}

.historyTabs button.active {
  background: #29323e;
  color: #f5f7fa;
}

/* SESSION HISTORY */

.historySessionList {
  display: grid;
  gap: 12px;
}

.historySession {
  overflow: hidden;

  border: 1px solid #29313b;
  border-radius: 18px;

  background: #171c24;
}

.historySessionSummary {
  width: 100%;
  min-height: 88px;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  padding: 16px 20px;

  border: 0;

  background: transparent;
  color: #f5f7fa;

  text-align: left;
}

.historySessionSummary > div:first-child {
  display: grid;
  gap: 4px;
}

.historySessionSummary > div:first-child strong {
  font-size: 20px;
}

.historySessionSummary > div:first-child span,
.historySessionSummaryRight > span {
  color: #8793a1;
  font-size: 13px;
}

.historySessionSummaryRight {
  display: flex;
  align-items: center;
  gap: 12px;
}

.historySessionSummaryRight b {
  padding: 5px 8px;

  border-radius: 7px;

  background: #29323d;
  color: #9eabb9;

  font-size: 10px;
  letter-spacing: 0.08em;
}

.historySessionSummaryRight b.active {
  background: #20372a;
  color: #81d499;
}

.historySessionDetails {
  padding: 18px 20px 20px;

  border-top: 1px solid #29313b;
}

.historySessionMeta {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 9px;

  margin-bottom: 16px;
}

.historySessionMeta > div {
  min-width: 0;

  padding: 14px;

  border-radius: 13px;

  background: #11151b;
}

.historySessionMeta span {
  display: block;

  margin-bottom: 5px;

  color: #778392;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.historySessionMeta strong {
  display: block;

  overflow: hidden;

  font-size: 18px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.historyStandings {
  display: grid;
  gap: 7px;
}

.historyStanding {
  display: grid;
  grid-template-columns:
    38px minmax(0, 1fr) auto;
  align-items: center;

  min-height: 62px;

  padding: 8px 14px;

  border-radius: 12px;

  background: #202731;
}

.historyStanding > span {
  color: #788391;
  font-weight: 850;
}

.historyStanding > div {
  display: grid;
  gap: 3px;

  min-width: 0;
}

.historyStanding > div > strong {
  overflow: hidden;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.historyStanding small {
  color: #8994a2;
}

.historyStanding > b {
  font-size: 22px;
}

.historyRaceButton {
  width: 100%;
  min-height: 58px;

  margin-top: 14px;

  border: 0;
  border-radius: 14px;

  background: #303946;
  color: #f5f7fa;

  font-weight: 850;
}

.historyEmpty {
  padding: 50px 20px;

  border: 1px dashed #303844;
  border-radius: 17px;

  color: #7f8997;

  text-align: center;
}

/* PLAYER STATS */

.playerStatsList {
  display: grid;
  gap: 14px;
}

.playerStatsCard {
  padding: 20px;

  border: 1px solid #29313b;
  border-radius: 18px;

  background: #171c24;
}

.playerStatsCard > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  margin-bottom: 18px;
}

.playerStatsCard > header > div {
  display: grid;
  gap: 3px;
}

.playerStatsCard h2 {
  margin: 0;

  font-size: 27px;
}

.playerStatsCard > header span {
  color: #8994a2;
  font-size: 13px;
}

.playerStatsCard > header > strong {
  font-size: 21px;
}

.playerStatSectionLabel {
  margin: 17px 2px 8px;

  color: #7c8795;

  font-size: 14px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.playerStatGrid {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.playerStatGrid > div {
  min-width: 0;

  padding: 14px;

  border-radius: 13px;

  background: #11151b;
}

.playerStatGrid span {
  display: block;

  min-height: 24px;
  margin-bottom: 5px;

  color: #778392;

  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.07em;
}

.playerStatGrid strong {
  font-size: 23px;
}

.hideStageBreakdown {
  display: grid;
  grid-template-columns:
    auto repeat(4, 1fr);
  align-items: center;
  gap: 8px;

  margin-top: 10px;
  padding: 11px 13px;

  border: 1px solid #3c3250;
  border-radius: 13px;

  background: #1d1827;
}

.hideStageBreakdown > span {
  color: #a891c5;

  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.hideStageBreakdown > div {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 5px;
}

.hideStageBreakdown small {
  color: #8f7ba8;
  font-size: 11px;
}

.hideStageBreakdown strong {
  color: #d0b7ef;
}

/* AWARDS */

.historyAwards {
  display: grid;
  gap: 18px;
}

.awardsIntro {
  padding: 5px 2px 2px;
}

.awardsIntro > span {
  color: #d9ae4b;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.awardsIntro h2 {
  margin: 5px 0 6px;

  font-size: 31px;
}

.awardsIntro p {
  max-width: 620px;
  margin: 0;

  color: #8994a2;
  line-height: 1.5;
}

.awardGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.awardCard {
  min-width: 0;

  padding: 20px;

  border: 1px solid #303844;
  border-radius: 18px;

  background: #171c24;
}

.awardCard > span {
  color: #d9ae4b;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.awardCard h3 {
  margin: 8px 0 4px;

  overflow-wrap: anywhere;

  font-size: 27px;
}

.awardCard > strong {
  color: #b5c0cd;

  font-size: 15px;
}

.awardCard p {
  margin: 11px 0 0;

  color: #7f8b99;

  font-size: 13px;
  line-height: 1.4;
}

@media (max-width: 700px) {
  .historySessionMeta {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .playerStatSectionLabel {
    font-size: 13px;
  }

  .playerStatGrid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .playerStatGrid span,
  .hideStageBreakdown > span {
    font-size: 11px;
  }

  .awardGrid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .historySessionSummary {
    align-items: flex-start;
  }

  .historySessionSummaryRight {
    flex-direction: column;
    align-items: flex-end;
    gap: 5px;
  }

  .hideStageBreakdown {
    grid-template-columns:
      1fr 1fr;
  }

  .hideStageBreakdown > span {
    grid-column: 1 / -1;
  }
}


