  .historySessionActions {
    grid-template-columns: 1fr;
  }

  .sessionAwardsSummary {
    grid-template-columns: 1fr 1fr;
  }
}

/* ==============================
   PLAYER SORT STAT HIGHLIGHT
================================ */

/* Grid statistic selected by the
   active player-sort button. */
.playerStatGrid > div.sortStatHighlight {
  position: relative;

  border:
    1px solid rgba(222, 181, 88, 0.62);

  background:
    linear-gradient(
      135deg,
      rgba(222, 181, 88, 0.11),
      #11151b 62%
    );

  box-shadow:
    inset 0 0 0 1px
      rgba(222, 181, 88, 0.05);
}

.playerStatGrid >
div.sortStatHighlight > span {
  color: #c7a755;
}

.playerStatGrid >
div.sortStatHighlight > strong {
  color: #f0c75e;
}

/* TOTAL PTS lives in the card header
   rather than the stat grid. */
.playerStatsHeadline.sortStatHighlight {
  min-width: 92px;
  padding: 9px 11px;

  border:
    1px solid rgba(222, 181, 88, 0.62);
  border-radius: 12px;

  background:
    linear-gradient(
      135deg,
      rgba(222, 181, 88, 0.12),
      rgba(17, 21, 27, 0.78)
    );
}

.playerStatsHeadline.sortStatHighlight
strong {
  color: #f0c75e;
}

.playerStatsHeadline.sortStatHighlight
span {
  color: #c7a755;
}

/* ==============================
   MVP TAB
================================ */

.mvpPage {
  display: grid;
  gap: 18px;
}

.mvpIntro {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 30px;

  padding: 4px 2px 2px;
}

.mvpIntro > div:first-child > span {
  color: #e0b65c;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.mvpIntro h2 {
  margin: 5px 0 6px;

  font-size: 31px;
}

.mvpIntro p {
  max-width: 650px;
  margin: 0;

  color: #8994a2;
  line-height: 1.5;
}

.mvpFormula {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, auto));
  gap: 6px 14px;

  padding: 14px 16px;

  border: 1px solid #303844;
  border-radius: 14px;

  background: #151a21;
}

.mvpFormula > span {
  grid-column: 1 / -1;

  color: #7c8795;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.mvpFormula strong {
  color: #c9d2dc;

  font-size: 12px;
}

.mvpEligibility {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 22px;

  padding: 14px 16px;

  border: 1px solid #3a3322;
  border-radius: 14px;

  background: #1b1913;
}

.mvpEligibility span {
  flex: 0 0 auto;

  color: #d9ae4b;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.mvpEligibility p {
  margin: 0;

  color: #9a8d6c;

  font-size: 12px;
  line-height: 1.45;
  text-align: right;
}

.mvpLeaderboard {
  display: grid;
  gap: 13px;
}

.mvpCard {
  padding: 20px;

  border: 1px solid #2d3641;
  border-radius: 18px;

  background: #171c24;
}

.mvpCard.mvpLeader {
  border-color: #5d4d27;

  box-shadow:
    inset 4px 0 0 #d9ae4b;
}

.mvpCard > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  margin-bottom: 16px;
}

.mvpIdentity {
  display: flex;
  align-items: center;
  gap: 13px;
}

.mvpIdentity > span {
  display: grid;
  place-items: center;

  width: 42px;
  height: 42px;

  border-radius: 12px;

  background: #252d37;
  color: #9aa6b5;

  font-size: 13px;
  font-weight: 900;
}

.mvpIdentity h3 {
  margin: 0 0 3px;

  font-size: 26px;
}

.mvpIdentity small {
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.09em;
}

.mvpProvisional {
  color: #c99963;
}

.mvpQualified {
  color: #75c895;
}

.mvpScore {
  display: grid;
  justify-items: end;
}

.mvpScore strong {
  color: #e0b65c;

  font-size: 36px;
  line-height: 1;
}

.mvpScore span {
  margin-top: 3px;

  color: #9d8245;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.mvpComponents {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.mvpComponents > div {
  min-width: 0;

  padding: 14px;

  border-radius: 13px;

  background: #11151b;
}

.mvpComponents span {
  display: block;

  margin-bottom: 5px;

  color: #788493;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.09em;
}

.mvpComponents strong {
  display: block;

  margin-bottom: 4px;

  font-size: 23px;
}

.mvpComponents small {
  color: #7f8b99;

  font-size: 10px;
  line-height: 1.35;
}

.mvpSample {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;

  margin-top: 11px;
}

.mvpSample span {
  padding: 5px 8px;

  border-radius: 8px;

  background: #222a34;
  color: #8d99a7;

  font-size: 10px;
  font-weight: 800;
}

.mvpMethodNote {
  padding: 15px 17px;

  border: 1px solid #2c3540;
  border-radius: 14px;

  background: #131820;
}

.mvpMethodNote strong {
  color: #9aa6b5;

  font-size: 10px;
  letter-spacing: 0.09em;
}

.mvpMethodNote p {
  margin: 6px 0 0;

  color: #778493;

  font-size: 12px;
  line-height: 1.5;
}

@media (max-width: 850px) {
  .mvpIntro {
    align-items: flex-start;
    flex-direction: column;
  }

  .mvpComponents {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .mvpEligibility {
    align-items: flex-start;
    flex-direction: column;
  }

  .mvpEligibility p {
    text-align: left;
  }
}

@media (max-width: 600px) {
  .historyTabs {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .mvpComponents {
    grid-template-columns: 1fr;
  }

  .mvpCard > header {
    align-items: flex-start;
  }

  .mvpScore strong {
    font-size: 30px;
  }
}

/* ==============================
   MVP QUALIFICATION TICKS
================================ */

.mvpSample span.complete {
  background: #1d3025;
  color: #7fd19a;
}

/* ==============================
   MVP PODIUM
================================ */

.mvpPodiumSection {
  padding: 22px 22px 0;

  border: 1px solid #303844;
  border-radius: 18px;

  background:
    radial-gradient(
      circle at 50% 0%,
      rgba(217, 174, 75, 0.11),
      transparent 46%
    ),
    #151a21;
}

.mvpPodiumHeader {
  text-align: center;
}

.mvpPodiumHeader > span,
.mvpLeaderboardHeader > span {
  color: #d9ae4b;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.mvpPodiumHeader h3,
.mvpLeaderboardHeader h3 {
  margin: 4px 0 0;

  font-size: 25px;
}

.mvpPodium {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
  align-items: end;
  gap: 14px;

  max-width: 900px;
  margin: 30px auto 0;
}

.mvpPodiumSlot {
  display: grid;
  grid-template-rows:
    auto auto auto;
  align-items: end;

  min-width: 0;
}

.mvpPodiumPlayer {
  position: relative;

  display: grid;
  justify-items: center;
  gap: 4px;

  padding: 17px 12px 14px;

  border: 1px solid #313a46;
  border-radius: 15px 15px 0 0;

  background: #1b212a;

  text-align: center;
}

.mvpPodiumPlayer > strong {
  max-width: 100%;

  overflow: hidden;

  font-size: 22px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mvpPodiumPlayer > small {
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.09em;
}

.mvpMedal {
  display: grid;
  place-items: center;

  width: 38px;
  height: 38px;

  margin-top: -37px;

  border: 3px solid #151a21;
  border-radius: 50%;

  background: #596473;
  color: #f5f7fa;

  font-size: 16px;
  font-weight: 950;
}

.mvpPodiumScore {
  display: grid;
  justify-items: center;

  padding: 13px 10px;

  border-right: 1px solid #313a46;
  border-left: 1px solid #313a46;

  background: #11151b;
}

.mvpPodiumScore strong {
  font-size: 31px;
  line-height: 1;
}

.mvpPodiumScore span {
  margin-top: 4px;

  color: #7e8997;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.mvpPodiumBlock {
  display: grid;
  place-items: center;

  min-height: 128px;

  border-radius: 0 0 10px 10px;

  background:
    linear-gradient(
      180deg,
      rgba(255,255,255,0.045),
      rgba(255,255,255,0.01)
    ),
    #29323d;
}

.mvpPodiumBlock span {
  color: #cbd3dc;

  font-size: 33px;
  font-weight: 950;
}

/* #1 in the middle, tallest and gold */

.mvpPodiumSlot.rank1
.mvpPodiumPlayer {
  border-color: #6b582a;

  background:
    linear-gradient(
      180deg,
      #262317,
      #1d1d1b
    );
}

.mvpPodiumSlot.rank1
.mvpMedal {
  background: #d9ae4b;
  color: #1a160b;
}

.mvpPodiumSlot.rank1
.mvpPodiumScore strong {
  color: #e8bd57;
}

.mvpPodiumSlot.rank1
.mvpPodiumBlock {
  min-height: 190px;

  background:
    linear-gradient(
      180deg,
      #6c5624,
      #3c311b
    );
}

.mvpPodiumSlot.rank1
.mvpPodiumBlock span {
  color: #f1c969;
}

/* #2 silver */

.mvpPodiumSlot.rank2
.mvpMedal {
  background: #9ca8b5;
  color: #171b20;
}

.mvpPodiumSlot.rank2
.mvpPodiumScore strong {
  color: #c8d0d9;
}

.mvpPodiumSlot.rank2
.mvpPodiumBlock {
  min-height: 145px;

  background:
    linear-gradient(
      180deg,
      #48535f,
      #303a45
    );
}

/* #3 bronze */

.mvpPodiumSlot.rank3
.mvpMedal {
  background: #ba8058;
  color: #1b120c;
}

.mvpPodiumSlot.rank3
.mvpPodiumScore strong {
  color: #d69a70;
}

.mvpPodiumSlot.rank3
.mvpPodiumBlock {
  min-height: 112px;

  background:
    linear-gradient(
      180deg,
      #5d4031,
      #352a25
    );
}

.mvpLeaderboardSection {
  display: grid;
  gap: 13px;

  margin-top: 2px;
}

.mvpLeaderboardHeader {
  padding: 0 2px;
}

/* Make the #1 detailed card a little
   quieter now that the podium is the hero. */

.mvpCard.mvpLeader {
  border-color: #3c4652;

  box-shadow: none;
}

/* Tablet / phone */

@media (max-width: 760px) {
  .mvpPodiumSection {
    padding: 18px 12px 0;
  }

  .mvpPodium {
    gap: 7px;

    margin-top: 28px;
  }

  .mvpPodiumPlayer {
    padding:
      14px 7px 11px;
  }

  .mvpPodiumPlayer > strong {
    font-size: 17px;
  }

  .mvpMedal {
    width: 32px;
    height: 32px;

    margin-top: -31px;

    font-size: 13px;
  }

  .mvpPodiumScore strong {
    font-size: 24px;
  }

  .mvpPodiumBlock span {
    font-size: 27px;
  }

  .mvpPodiumSlot.rank1
  .mvpPodiumBlock {
    min-height: 155px;
  }

  .mvpPodiumSlot.rank2
  .mvpPodiumBlock {
    min-height: 118px;
  }

  .mvpPodiumSlot.rank3
  .mvpPodiumBlock {
    min-height: 90px;
  }
}

@media (max-width: 520px) {
  .mvpPodium {
    grid-template-columns:
      repeat(3, minmax(0, 1fr));
  }

  .mvpPodiumPlayer > strong {
    font-size: 14px;
  }

  .mvpPodiumPlayer > small {
    font-size: 6px;
  }

  .mvpPodiumScore {
    padding:
      10px 4px;
  }

  .mvpPodiumScore strong {
    font-size: 20px;
  }
}


/* ==============================
   STANDARD ROUND — QUICK RANK
   Round CSS.
================================ */

.standardModeBar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;

  max-width: 760px;
  margin: 0 auto 18px;
  padding: 14px 16px;

  border: 1px solid #2c3540;
  border-radius: 15px;

  background: #151a21;
}

.standardModeBar > div {
  display: grid;
  gap: 3px;
}

.standardModeBar > div > span {
  color: #7f8b99;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.standardModeBar > div > strong {
  font-size: 16px;
}

.standardModeButton {
  flex: 0 0 auto;

  min-height: 40px;
  padding: 0 14px;

  border: 1px solid #3a4552;
  border-radius: 10px;

  background: #252d38;
  color: #dfe5eb;

  font-size: 11px;
  font-weight: 850;
}

.quickRankPanel {
  position: relative;

  max-width: 760px;
  margin: 0 auto 18px;
}

.quickRankList {
  display: grid;

  margin: 0;
  padding: 0;

  list-style: none;
}

.quickRankItem {
  position: relative;

  margin: 0;
  padding: 0;

  list-style: none;

  touch-action: none;
}

.quickRankCard {
  display: grid;
  grid-template-columns:
    54px minmax(0, 1fr) auto 30px;
  align-items: center;
  gap: 13px;

  min-height: 84px;
  padding: 12px 16px;

  border: 1px solid #303a46;
  border-radius: 16px;

  background: #1a2028;

  cursor: grab;
  user-select: none;
}

.quickRankCard:active {
  cursor: grabbing;
}

.quickRankNumber {
  display: grid;
  place-items: center;

  width: 42px;
  height: 42px;

  border-radius: 12px;

  background: #252e39;
  color: #9ba8b6;

  font-size: 17px;
  font-weight: 950;
}

.quickRankPlayer {
  display: grid;
  gap: 3px;

  min-width: 0;
}

.quickRankPlayer strong {
  overflow: hidden;

  font-size: 22px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.quickRankPlayer span {
  color: #778493;

  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.quickRankPoints {
  display: grid;
  justify-items: end;
}

.quickRankPoints strong {
  font-size: 25px;
}

.quickRankPoints span {
  color: #788493;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.quickRankDrag {
  color: #647181;

  font-size: 20px;
  font-weight: 900;
}

/*
  The small divider between cards is
  the "connect these two" control.
*/
.rankTieConnector {
  position: relative;
  z-index: 3;

  display: grid;
  place-items: center;

  width: calc(100% - 36px);
  height: 24px;
  margin: -1px 18px;

  border: 0;

  background: transparent;
}

.rankTieConnector::before {
  content: '';

  position: absolute;

  left: 0;
  right: 0;
  top: 50%;

  height: 1px;

  background: #27303a;
}

.rankTieConnector > span {
  position: relative;
  z-index: 1;

  display: grid;
  place-items: center;

  min-width: 30px;
  height: 20px;
  padding: 0 7px;

  border: 1px solid #34404d;
  border-radius: 999px;

  background: #11161c;
  color: #7e8997;

  font-size: 10px;
  font-weight: 950;
  letter-spacing: 0.05em;
}

.rankTieConnector.active {
  height: 30px;

  margin-top: -4px;
  margin-bottom: -4px;

  border-right: 2px solid #856fd0;
  border-left: 2px solid #856fd0;

  background:
    rgba(133, 111, 208, 0.08);
}

.rankTieConnector.active::before {
  background: #856fd0;
}

.rankTieConnector.active > span {
  border-color: #856fd0;

  background: #302747;
  color: #c9b8f3;
}

.quickRankCard.tiedWithNext,
.quickRankCard.tiedWithPrevious {
  border-color: #6757a1;

  background:
    linear-gradient(
      90deg,
      rgba(116, 91, 180, 0.08),
      #1a2028 45%
    );
}

.quickRankCard.tiedWithNext {
  border-bottom-right-radius: 8px;
  border-bottom-left-radius: 8px;
}

.quickRankCard.tiedWithPrevious {
  border-top-right-radius: 8px;
  border-top-left-radius: 8px;
}

.quickRankCard.tiedWithNext
.quickRankPlayer span,
.quickRankCard.tiedWithPrevious
.quickRankPlayer span {
  color: #aa98db;
}

.quickRankHint {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 16px;

  margin-top: 13px;

  color: #74808e;

  font-size: 10px;
  font-weight: 750;
}

.quickRankToast {
  position: sticky;
  bottom: 18px;
  z-index: 10;

  width: fit-content;
  max-width: calc(100% - 24px);

  margin: 14px auto 0;
  padding: 9px 13px;

  border: 1px solid #5d4b8d;
  border-radius: 999px;

  background: #251f34;
  color: #cdbcf3;

  font-size: 11px;
  font-weight: 850;
  text-align: center;
}

/* The old exact-score mode remains
   secondary, not the default. */

.nextScorePlayer:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

@media (max-width: 620px) {
  .standardModeBar {
    align-items: flex-start;
    flex-direction: column;
  }

  .standardModeButton {
    width: 100%;
  }

  .quickRankCard {
    grid-template-columns:
      44px minmax(0, 1fr) auto 24px;

    min-height: 76px;
    padding: 10px 12px;
  }

  .quickRankNumber {
    width: 36px;
    height: 36px;

    font-size: 15px;
  }

  .quickRankPlayer strong {
    font-size: 18px;
  }

  .quickRankPoints strong {
    font-size: 21px;
  }
}

/* ==============================
   PENALTY CONFIRMATION MODAL
================================ */

.penaltyConfirmOverlay {
  position: fixed;
  inset: 0;
  z-index: 1000;

  display: grid;
  place-items: center;

  padding: 22px;

  background: rgba(5, 8, 12, 0.76);
  backdrop-filter: blur(8px);
}

.penaltyConfirmDialog {
  width: min(100%, 520px);
  padding: 28px;

  border: 1px solid #4a3035;
  border-radius: 22px;

  background: #171c24;

  box-shadow:
    0 24px 70px rgba(0, 0, 0, 0.45);
}

.penaltyConfirmLabel {
  color: #dc7d87;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.penaltyConfirmDialog h2 {
  margin: 8px 0 22px;

  font-size: 30px;
  line-height: 1.15;
}

.penaltyConfirmPoints {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 12px;

  margin-bottom: 22px;
}

.penaltyConfirmPoints > div:not(
  .penaltyConfirmArrow
) {
  padding: 16px;

  border-radius: 14px;

  background: #11151b;
}

.penaltyConfirmPoints span {
  display: block;

  margin-bottom: 5px;

  color: #7e8997;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.penaltyConfirmPoints strong {
  font-size: 30px;
}

.penaltyConfirmArrow {
  color: #697583;

  font-size: 22px;
  font-weight: 900;
}

.penaltyConfirmActions {
  display: grid;
  grid-template-columns: 1fr 1.4fr;
  gap: 10px;
}

.penaltyConfirmActions button {
  min-height: 58px;

  border-radius: 14px;

  font-size: 15px;
  font-weight: 850;
}

.penaltyCancelButton {
  border: 1px solid #39434f;

  background: #232a33;
  color: #b5bfca;
}

.penaltyConfirmButton {
  border: 0;

  background: #6a3037;
  color: #f4dfe2;
}

.penaltyConfirmButton:hover {
  background: #793740;
}

.penaltyConfirmActions button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

@media (max-width: 520px) {
  .penaltyConfirmDialog {
    padding: 22px;
  }

  .penaltyConfirmDialog h2 {
    font-size: 25px;
  }

  .penaltyConfirmActions {
    grid-template-columns: 1fr;
  }
}

/* ==============================
   MAIN SCOREBOARD POLISH
================================ */

/* ---------- HEADER ---------- */

.gameHeader.gameHeaderPolished {
  display: grid;
  grid-template-columns:
    minmax(190px, 1fr)
    auto
    minmax(190px, 1fr);

  align-items: center;
  gap: 24px;

  margin-bottom: 30px;
}

.gameRoundHero {
  display: flex;
  align-items: baseline;
  gap: 11px;

  justify-self: start;
}

.gameRoundHero > span {
  color: #758292;

  font-size: 11px;
  font-weight: 950;
  letter-spacing: 0.14em;
}

.gameRoundHero > strong {
  color: #f5f7fa;

  font-size: 48px;
  font-weight: 950;
  line-height: 0.95;
