}

.standingRank {
  display: grid;
  place-items: center;

  width: 38px;
  height: 38px;

  border-radius: 11px;

  background: #202731;
  color: #8390a0;

  font-size: 18px;
  font-weight: 950;
}

.standingPlayer {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.standingPlayer > div {
  min-width: 0;
}

.standingPlayer h2 {
  margin: 0;
  font-size: 27px;
}

.standingPlayer p {
  margin: 6px 0 0;

  color: #758293;

  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.035em;
}

.standingPoints {
  display: grid;
  justify-items: end;
  align-content: center;
  gap: 2px;
}

.standingPoints strong {
  font-size: 49px;
  line-height: 0.9;
}

.standingPoints span {
  color: #7a8796;

