  gap: 24px;

  min-height: 56px;
  margin-top: 12px;
  padding: 13px 18px;

  border: 1px solid #2b3440;
  border-radius: 13px;
  background: #151b22;
}

.gameWaiting span {
  color: #778596;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.gameWaiting strong {
  color: #edf2f7;
  font-size: 14px;
  text-align: right;
}

.gameActions {
  display: grid !important;
  grid-template-columns:
    repeat(3, minmax(0, 1fr)) !important;

  gap: 10px !important;
  margin-top: 20px;
}

.gameActions button {
  min-height: 76px;
  border: 0;
  border-radius: 18px;
  background: #f2f4f6;
  color: #101419;
  font-size: 18px;
  font-weight: 850;
}

.gameActions .jimAction {
  background: #d9ae4b;
}

.gameActions button:disabled {
