  cursor: not-allowed;
}

.nextFeature {
  margin: 12px 0 0;
  color: #626d79;
  font-size: 12px;
  text-align: center;
}

@media (max-width: 600px) {
  .standingRow {
    grid-template-columns:
      42px minmax(0, 1fr) auto;
    padding: 16px;
  }

  .standingPlayer h2 {
    font-size: 22px;
  }

  .standingPoints strong {
    font-size: 40px;
  }

  .gameActions {
    grid-template-columns: 1fr;
  }
}

/* ==============================
   STANDARD ROUND ENTRY
================================ */

.roundEntryHeader {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-bottom: 28px;
}

.roundEntryHeader h1 {
  margin: 3px 0 0;
  font-size: 34px;
}

.roundEntryHeader span {
  color: #7f8997;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.1em;
}


