/* ==================================================
   JIM ROUND — CIRCULAR MODE WHEEL
   Append this at the VERY BOTTOM of index.css
================================================== */

/* Main progress card */
.jimProgress.jimProgressWheelCard {
  position: relative;

  display: grid;
  place-items: center;

  width: 100%;
  min-height: 430px;
  padding: 24px 20px 20px;

  overflow: hidden;

  border: 1px solid #2b333e;
  border-radius: 22px;

  background:
    radial-gradient(
      circle at 50% 43%,
      rgba(217, 174, 75, 0.055),
      transparent 35%
    ),
    #151a21;
}

/* Whole wheel + readout */
.jimWheelWrap {
  display: grid;
  justify-items: center;
  gap: 8px;

  width: 100%;
}

/* Square wheel canvas */
.jimWheel {
  position: relative;

  width: min(100%, 360px);
  aspect-ratio: 1;

  flex: 0 0 auto;
}

/* SVG outer ring */
.jimWheelRing {
  position: absolute;
  inset: 0;

  display: block;

  width: 100%;
  height: 100%;

  overflow: visible;
}

/* Each stage is a thick arc */
.jimWheelSegment {
  fill: none;

  stroke: #303946;
  stroke-width: 28;
  stroke-linecap: round;

  opacity: 0.82;

  transition:
    stroke 220ms ease,
    opacity 220ms ease,
    filter 220ms ease;
}

/* Already survived */
.jimWheelSegment.survived {
  stroke: #b98f35;

  opacity: 1;

  filter:
    drop-shadow(
      0 0 5px
      rgba(217, 174, 75, 0.16)
    );
}

/* Stage being played right now */
.jimWheelSegment.current {
  stroke: #e0b447;

  opacity: 1;

  filter:
    drop-shadow(
      0 0 7px
      rgba(224, 180, 71, 0.34)
    );
}

/* Hide was used on this stage */
.jimWheelSegment.hidden {
  stroke: #9a75ca;

  filter:
    drop-shadow(
      0 0 6px
      rgba(154, 117, 202, 0.28)
    );
}

/* Stage numbers */
.jimWheelNumber {
  dominant-baseline: middle;
  text-anchor: middle;

  fill: #718093;

  font-family: inherit;
  font-size: 19px;
  font-weight: 800;

  pointer-events: none;

  transition:
    fill 220ms ease,
    opacity 220ms ease;
}

.jimWheelNumber.survived {
  fill: #e4bd62;
}

.jimWheelNumber.current {
  fill: #ffd36c;
}

.jimWheelNumber.hidden {
  fill: #d3b8f2;
}

/* Center Jim emblem */
.jimModeEmblem {
  position: absolute;
  top: 50%;
  left: 50%;

  width: 48%;
  aspect-ratio: 1;

  transform:
    translate(-50%, -50%);

  display: grid;
  place-items: center;

  overflow: hidden;

  border: 1px solid #3b424d;
  border-radius: 50%;

  background:
    radial-gradient(
      circle at 50% 45%,
      #1a2028,
      #10151b 72%
    );

  box-shadow:
    inset 0 0 0 7px
      rgba(255,255,255,0.012),
    0 0 0 1px
      rgba(217,174,75,0.05);
}

/*
  The same SVG is layered several times.
  The dim copy shows the unfinished logo.
  Completed stages reveal one horizontal
  sixth from the bottom upward.
*/
.jimModeLogo {
  position: absolute;
  inset: 13%;

  width: 74%;
  height: 74%;

  object-fit: contain;

  filter:
    brightness(0)
    invert(1);

  pointer-events: none;
  user-select: none;
}

.jimModeLogoGhost {
  opacity: 0.11;
}

.jimModeLogoBand {
  opacity: 1;

  filter:
    brightness(0)
    invert(1)
    drop-shadow(
      0 0 4px
      rgba(255,255,255,0.08)
    );

  animation:
    jimModeBandReveal
    300ms
    cubic-bezier(
      0.2,
      0.8,
      0.2,
      1
    )
