/* =========================================
   GOALPOST POPUP ANIMATIONS
   Append to the VERY BOTTOM of index.css
========================================= */

/* Shared overlay fade */
.goalpostOverlay {
  animation:
    goalpostOverlayFadeIn
    220ms ease-out both;
}


/* -----------------------------------------
   DEUCE
----------------------------------------- */

.goalpostDialog.deuce {
  transform-origin: center;

  animation:
    goalpostDeucePopIn
    520ms
    cubic-bezier(
      0.2,
      0.9,
      0.25,
      1.12
    )
    both;
}

.goalpostDialog.deuce
.goalpostHeroMark {
  animation:
    goalpostDeuceMarkIn
    700ms
    cubic-bezier(
      0.2,
      0.9,
      0.25,
      1.2
    )
    140ms
    both;
}

.goalpostDialog.deuce
.goalpostDeucePlayers
> div {
  opacity: 0;

  animation:
    goalpostDeuceRowIn
    420ms ease-out
    both;
}

.goalpostDialog.deuce
.goalpostDeucePlayers
> div:nth-child(1) {
  animation-delay: 180ms;
}

.goalpostDialog.deuce
.goalpostDeucePlayers
> div:nth-child(2) {
  animation-delay: 250ms;
}

.goalpostDialog.deuce
.goalpostDeucePlayers
> div:nth-child(3) {
  animation-delay: 320ms;
}

.goalpostDialog.deuce
.goalpostDeucePlayers
> div:nth-child(4) {
  animation-delay: 390ms;
}


/* -----------------------------------------
   GOALPOST REACHED / CONGRATS
----------------------------------------- */

.goalpostDialog.reached {
  transform-origin:
    center 42%;

  animation:
    goalpostCongratsPopIn
    620ms
    cubic-bezier(
      0.16,
      1,
      0.3,
      1
    )
    both;
}

.goalpostDialog.reached
.goalpostHeroMark.crown {
  transform-origin: center;

  animation:
    goalpostCrownDrop
    760ms
    cubic-bezier(
      0.18,
      1.35,
      0.35,
      1
    )
    120ms
    both;
}

.goalpostDialog.reached
h2,
.goalpostDialog.reached
.goalpostWinnerPoints,
.goalpostDialog.reached
.goalpostTargetChip {
  opacity: 0;

  animation:
    goalpostCongratsTextIn
    420ms ease-out
    260ms
    both;
}


/* Kahoot podium rises from the floor */
.goalpostDialog.reached
.goalpostPodiumColumn {
  opacity: 0;

  animation:
    goalpostPodiumRise
    560ms
    cubic-bezier(
      0.18,
      0.9,
      0.28,
      1.08
    )
    both;
}

.goalpostDialog.reached
.goalpostPodiumColumn.rank-1 {
  animation-delay: 300ms;
}

.goalpostDialog.reached
.goalpostPodiumColumn.rank-2 {
  animation-delay: 390ms;
}

.goalpostDialog.reached
.goalpostPodiumColumn.rank-3 {
  animation-delay: 470ms;
}

.goalpostDialog.reached
.goalpostPodiumColumn.rank-4 {
  animation-delay: 540ms;
}

.goalpostDialog.reached
.goalpostPodiumColumn.rank-5 {
  animation-delay: 600ms;
}

.goalpostDialog.reached
.goalpostPodiumColumn.rank-6 {
  animation-delay: 660ms;
}

.goalpostDialog.reached
.goalpostDecision,
.goalpostDialog.reached
.goalpostFinishButton {
  opacity: 0;

  animation:
    goalpostActionsIn
    420ms ease-out
    680ms
    both;
}


/* -----------------------------------------
   KEYFRAMES
----------------------------------------- */

@keyframes goalpostOverlayFadeIn {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes goalpostDeucePopIn {
  0% {
    opacity: 0;
    transform:
      translateY(18px)
      scale(0.94);
  }

  70% {
    opacity: 1;
    transform:
      translateY(-3px)
      scale(1.012);
  }

  100% {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }
}

@keyframes goalpostDeuceMarkIn {
  0% {
    opacity: 0;
    transform:
      scale(0.35)
      rotate(-18deg);
  }

  60% {
    opacity: 1;
    transform:
      scale(1.2)
      rotate(5deg);
  }

  100% {
    opacity: 1;
    transform:
      scale(1)
      rotate(0);
  }
}

@keyframes goalpostDeuceRowIn {
  from {
    opacity: 0;
    transform:
      translateX(-12px);
  }

  to {
    opacity: 1;
    transform:
      translateX(0);
  }
}

@keyframes goalpostCongratsPopIn {
  0% {
    opacity: 0;
    transform:
      translateY(24px)
      scale(0.92);
  }

  65% {
    opacity: 1;
    transform:
      translateY(-4px)
      scale(1.015);
  }

  100% {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }
}

@keyframes goalpostCrownDrop {
  0% {
    opacity: 0;
    transform:
      translateY(-26px)
      scale(0.45)
      rotate(-12deg);
  }

  58% {
    opacity: 1;
    transform:
      translateY(4px)
      scale(1.22)
      rotate(5deg);
  }

  78% {
    transform:
      translateY(-2px)
      scale(0.97)
      rotate(-2deg);
  }

  100% {
    opacity: 1;
    transform:
      translateY(0)
      scale(1)
      rotate(0);
  }
}

@keyframes goalpostCongratsTextIn {
  from {
    opacity: 0;
    transform:
      translateY(8px);
  }

  to {
    opacity: 1;
    transform:
      translateY(0);
  }
}

@keyframes goalpostPodiumRise {
  from {
    opacity: 0;
    transform:
      translateY(34px)
      scaleY(0.82);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scaleY(1);
  }
}

@keyframes goalpostActionsIn {
  from {
    opacity: 0;
    transform:
      translateY(10px);
  }

  to {
    opacity: 1;
    transform:
      translateY(0);
  }
}


/* Accessibility */
@media (
  prefers-reduced-motion:
  reduce
) {
  .goalpostOverlay,
