  line-height: 1;
}


/* Jim win */
.winStreakJim {
  display: inline-grid;
  place-items: center;

  width: 20px;
  height: 20px;

  color: #e3b64b;

  border:
    1px solid transparent;
  border-radius: 50%;

  font-size: 14px;
  line-height: 1;
}

.winStreakJim.usedHide {
  border-color: #9a75ca;
}


/* Let longer records wrap cleanly rather than
   shrinking the symbols. */
@media (max-width: 620px) {
  .sessionRecordWinner
  .winStreakPath {
    gap: 4px;
  }

  .winStreakPathArrow {
    font-size: 10px;
  }
}

/* =========================================
   WIN STREAK PATH — COMPACT STANDARD TALLIES
   Append to the VERY BOTTOM of index.css
========================================= */

/* Consecutive Standard wins now render as one
   compact string: ||, |||, ||||, etc. */
.winStreakStandardRun {
  display: inline-block;

  color: #88add7;

  font-family: ui-monospace,
    SFMono-Regular,
    Menlo,
    Consolas,
    monospace;

  font-size: 18px;
  font-weight: 950;
  line-height: 1;

  letter-spacing: -2px;

  white-space: nowrap;
}

/* =========================================
   WIN STREAK PATH — TRUE 5-BAR TALLY
   Append to the VERY BOTTOM of index.css
========================================= */

.winStreakStandardTallies {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.winStreakTallyGroup {
  position: relative;

  display: inline-flex;
  align-items: center;
  gap: 3px;

  height: 20px;
}

.winStreakTallyMark {
  display: block;

  width: 2px;
  height: 18px;

  border-radius: 2px;

  background: #88add7;
}

/* Fifth win crosses the first four,
   matching the familiar tally-mark style. */
.winStreakTallyStrike {
  position: absolute;

  left: 0;
  top: 9px;

  width: 100%;
  height: 2px;

  border-radius: 2px;

  background: #88add7;

  transform:
    rotate(-24deg);

  transform-origin: center;
}

/* =========================================
   WIN STREAK RECORD — NAME LAYOUT FIX
   Append to the VERY BOTTOM of index.css
========================================= */

/*
  The streak path became a third flex child of
  .sessionRecordWinner, so it was stealing width
  from the player name and forcing "H...".

  Rows containing a streak path use a 2-column
  grid instead:
    name | date
    streak path across the full row
*/
.sessionRecordWinner:has(
  .winStreakPath
) {
  display: grid !important;

  grid-template-columns:
    minmax(0, 1fr) auto;

  align-items: center !important;
  column-gap: 14px !important;
  row-gap: 7px !important;
}


/* Player name keeps the full first column. */
.sessionRecordWinner:has(
  .winStreakPath
) h3 {
  width: auto !important;
  min-width: 0;

  overflow: hidden;

  text-overflow: ellipsis;
  white-space: nowrap;
}


/* Date stays compact on the right. */
.sessionRecordWinner:has(
  .winStreakPath
) > span {
  grid-column: 2;

  justify-self: end;
}


/* Streak sequence gets its own full-width row. */
.sessionRecordWinner:has(
  .winStreakPath
) .winStreakPath {
  grid-column: 1 / -1;

  width: 100%;

  margin-top: 0;
}

/* =========================================
   JIM DATA — CLOUD SYNC STATUS
   Append to the bottom of index.css
========================================= */

.cloudStatusOption {
  align-items: start;
}

.cloudStatusLine {
  display: flex;
  align-items: center;
  gap: 8px;

  margin-top: 8px;

  color: #aeb8c5;

  font-size: 14px;
  font-weight: 850;
}

.cloudStatusDot {
  font-size: 13px;
  line-height: 1;
}

.cloudStatusLine.connected {
  color: #78c89a;
}

.cloudStatusLine.pending {
  color: #d8b66a;
}

.cloudStatusLine.offline {
  color: #d58b82;
}

.cloudStatusLine.local,
.cloudStatusLine.signedOut {
  color: #8994a2;
}

.cloudStatusOption p + p {
  margin-top: 4px;
}

/* =========================================
   JIMRAMI CLOUD — OPTIONAL DATA-PANEL LOGIN
   Append to the bottom of src/index.css
========================================= */

.cloudLoginPanel {
  display: grid;
  grid-template-columns:
    minmax(0, 1fr)
    minmax(0, 1fr)
    auto;
  align-items: end;
  gap: 12px;

  padding: 16px 0;

  border-bottom:
    1px solid #2b3440;
}

.cloudLoginPanel label {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.cloudLoginPanel label > span {
  color: #8795a6;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.cloudLoginPanel input {
  width: 100%;
  min-width: 0;
  min-height: 44px;

  padding: 0 12px;

  border:
    1px solid #35404d;
  border-radius: 11px;

  outline: none;

  background: #10151c;
  color: #edf2f7;

  font: inherit;
}

.cloudLoginPanel input:focus {
  border-color: #667d9a;
}

.cloudLoginPanel input::placeholder {
  color: #5f6c7c;
}

.cloudLoginPanel > button {
  min-height: 44px;
  padding: 0 16px;

  white-space: nowrap;
}

.cloudLoginError {
  grid-column: 1 / -1;

  margin: 0;
  padding: 9px 11px;

  border:
    1px solid #684049;
  border-radius: 9px;

  background: #291a1f;
  color: #e89aa4;

  font-size: 11px;
  line-height: 1.4;
}

.cloudSignOutButton {
  background: transparent !important;
  color: #a6b1be !important;

  border:
    1px solid #3a4552 !important;
}

@media (max-width: 680px) {
  .cloudLoginPanel {
    grid-template-columns: 1fr;
    align-items: stretch;
  }

  .cloudLoginPanel > button {
    width: 100%;
  }
}

/* =========================================
   JIMRAMI — SUPABASE OWNER CONNECTION
   Append BELOW the previous cloud-login CSS
========================================= */

/*
  Override the normal white Data-panel
  action buttons for Supabase controls.
*/
.cloudStatusOption > .cloudConnectButton,
.cloudStatusOption > .cloudSignOutButton {
  min-height: 44px !important;
  padding: 0 16px !important;

  border:
    1px solid #3b4755 !important;
  border-radius: 11px !important;

  background:
    #202731 !important;
  color:
    #b8c3d0 !important;

  box-shadow: none !important;

  font-size: 12px !important;
  font-weight: 850 !important;
}

.cloudStatusOption > .cloudConnectButton:hover,
.cloudStatusOption > .cloudSignOutButton:hover {
  background:
    #252e3a !important;

  border-color:
    #4b5969 !important;
}

.cloudLoginPanel > .cloudLoginSubmit {
  min-height: 44px !important;
  padding: 0 16px !important;

  border:
    1px solid #42536a !important;
  border-radius: 11px !important;

  background:
    #263345 !important;
  color:
    #d3deeb !important;

  box-shadow: none !important;

  font-size: 12px !important;
  font-weight: 850 !important;
}

.cloudLoginPanel > .cloudLoginSubmit:hover {
  background:
    #2d3b50 !important;

  border-color:
    #536985 !important;
}

.cloudLoginHint {
  grid-column: 1 / -1;

  margin: -2px 0 0;

  color: #667588;

  font-size: 10px;
  line-height: 1.45;
}

@media (max-width: 680px) {
  .cloudStatusOption >
  .cloudConnectButton,
  .cloudStatusOption >
  .cloudSignOutButton {
    min-width: 96px;
  }
}

* {
  box-sizing: border-box;
}

:root {
  font-family:
    Inter,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;

  color: #f5f7fa;
  background: #0d1015;
  font-synthesis: none;
}

html,
body,
#root {
  width: 100%;
  min-width: 320px;
  min-height: 100%;
  margin: 0;
  overscroll-behavior-y: none;
}

body {
  background: #0d1015;
}

button,
input {
  font: inherit;
}

button {
  cursor: pointer;
}

.app {
  width: 100%;
  max-width: 1000px;
  margin: 0 auto;
  padding: 28px;
}

/* HEADER */

.setupHeader {
  display: grid;
  grid-template-columns:
    1fr auto 1fr;
  align-items: center;
  gap: 20px;
  margin-bottom: 28px;
}

.setupHeader > h1 {
  grid-column: 2;
  justify-self: center;

  margin: 0;
  font-size: 44px;
  letter-spacing: -0.045em;
  text-align: center;
}

.setupHeaderActions {
  grid-column: 3;
  justify-self: end;
}


@media (max-width: 700px) {
  .setupHeader {
    grid-template-columns:
      1fr auto;
    gap: 14px;
  }

  .setupHeader > h1 {
    grid-column: 1 / -1;
    grid-row: 1;
  }

  .setupHeaderActions {
    grid-column: 2;
    grid-row: 2;
  }
}

/* ADD PLAYER */

.addPlayer {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  margin-bottom: 24px;
}

.addPlayer input {
  min-width: 0;
  min-height: 60px;
  padding: 0 18px;
  border: 1px solid #303844;
  border-radius: 15px;
  outline: none;
  background: #171c24;
  color: white;
  font-size: 18px;
}

.addPlayer input:focus {
  border-color: #8faeff;
}

.addPlayer button {
  min-width: 140px;
  border: 0;
  border-radius: 15px;
  background: #f2f4f6;
  color: #101419;
  font-weight: 800;
}

/* PLAYER LIST */

.playerLibrary {
  display: grid;
  gap: 11px;
}

.emptyPlayers {
  padding: 30px;
  border: 1px dashed #303844;
  border-radius: 16px;
  color: #7f8997;
  text-align: center;
}

.playerSelect {
  display: grid;
  grid-template-columns: 1fr 94px;
  min-height: 78px;
  overflow: hidden;
  border: 2px solid #272e38;
  border-radius: 17px;
  background: #171c24;
}

.playerSelect.selected {
  border-color: #8faeff;
  background: #1b2230;
}

.playerSelectMain {
  display: grid;
  grid-template-columns: 48px 1fr auto;
  align-items: center;
  gap: 14px;
  min-width: 0;
  padding: 14px 18px;
  border: 0;
  background: transparent;
  color: white;
  text-align: left;
}

.playerSelectMain strong {
  overflow: hidden;
  font-size: 21px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.playerSelectMain > span {
  color: #778493;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.playerSelect.selected .playerSelectMain > span {
  color: #aebcce;
}

.selectionNumber {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border: 1px solid #38414e;
  border-radius: 11px;
  color: #8b96a5;
  font-weight: 900;
}

.playerSelect.selected .selectionNumber {
  background: #f3f5f7;
  color: #101419;
}

.deletePlayer {
  border: 0;
  border-left: 1px solid #29313c;
  background: transparent;
  color: #687382;
  font-size: 25px;
}

.deletePlayer:hover {
  color: white;
}

/* SESSION SUMMARY */

.sessionSummary {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-top: 22px;
}

.sessionSummary > div {
  padding: 17px;
  border: 1px solid #272e38;
  border-radius: 15px;
  background: #13171d;
}

.sessionSummary span {
  display: block;
  margin-bottom: 5px;
  color: #778392;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.sessionSummary strong {
  font-size: 27px;
}

/* START */

.startSession {
  width: 100%;
  min-height: 72px;
  margin-top: 16px;
  border: 0;
  border-radius: 17px;
  background: #f2f4f6;
  color: #101419;
  font-size: 18px;
  font-weight: 850;
}

.startSession:disabled {
  background: #242a33;
  color: #606b78;
  cursor: not-allowed;
}

@media (max-width: 600px) {
  .app {
    padding: 18px;
  }

  .addPlayer {
    grid-template-columns: 1fr;
  }

  .addPlayer button {
    min-height: 56px;
  }

  .playerSelectMain {
    grid-template-columns: 42px 1fr;
  }

  .playerSelectMain > span {
    grid-column: 2;
  }
}
/* ---------- ACTIVE GAME ---------- */

.gameHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 28px;
}

.gameHeader h1 {
  margin: 0 0 8px;
  font-size: 48px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.gameRound {
  color: #808b99;
  font-size: 17px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.endSession {
  min-height: 48px;
  padding: 0 18px;
  border: 1px solid #39414c;
  border-radius: 13px;
  background: transparent;
  color: #aab3be;
  font-weight: 750;
}

.gameScoreboard {
  display: grid;
  gap: 10px;
}

.standingRow {
  position: relative;

  display: grid;
  grid-template-columns:
    54px minmax(0, 1fr) 105px;
  align-items: center;

  min-height: 104px;
  padding: 16px 22px;

  border: 1px solid #282f39;
  border-radius: 18px;
  background: #171c24;

  transition:
    border-color 160ms ease,
    background 160ms ease;
}

.standingRank {
  display: grid;
  place-items: center;

  width: 38px;
  height: 38px;

  border-radius: 11px;

  background: #202731;
  color: #8390a0;

  font-size: 18px;
  font-weight: 950;
}

.standingPlayer {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.standingPlayer > div {
  min-width: 0;
}

.standingPlayer h2 {
  margin: 0;
  font-size: 27px;
}

.standingPlayer p {
  margin: 6px 0 0;

  color: #758293;

  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.035em;
}

.standingPoints {
  display: grid;
  justify-items: end;
  align-content: center;
  gap: 2px;
}

.standingPoints strong {
  font-size: 49px;
  line-height: 0.9;
}

.standingPoints span {
  color: #7a8796;

  font-size: 9px;
  font-weight: 950;
  letter-spacing: 0.12em;
}

.gameWaiting {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;

  min-height: 56px;
  margin-top: 12px;
  padding: 13px 18px;

  border: 1px solid #2b3440;
  border-radius: 13px;
  background: #151b22;
}

.gameWaiting span {
  color: #778596;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.gameWaiting strong {
  color: #edf2f7;
  font-size: 14px;
  text-align: right;
}

.gameActions {
  display: grid !important;
  grid-template-columns:
    repeat(3, minmax(0, 1fr)) !important;

  gap: 10px !important;
  margin-top: 20px;
}

.gameActions button {
  min-height: 76px;
  border: 0;
  border-radius: 18px;
  background: #f2f4f6;
  color: #101419;
  font-size: 18px;
  font-weight: 850;
}

.gameActions .jimAction {
  background: #d9ae4b;
}

.gameActions button:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.nextFeature {
  margin: 12px 0 0;
  color: #626d79;
  font-size: 12px;
  text-align: center;
}

@media (max-width: 600px) {
  .standingRow {
    grid-template-columns:
      42px minmax(0, 1fr) auto;
    padding: 16px;
  }

  .standingPlayer h2 {
    font-size: 22px;
  }

  .standingPoints strong {
    font-size: 40px;
  }

  .gameActions {
    grid-template-columns: 1fr;
  }
}

/* ==============================
   STANDARD ROUND ENTRY
================================ */

.roundEntryHeader {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-bottom: 28px;
}

.roundEntryHeader h1 {
  margin: 3px 0 0;
  font-size: 34px;
}

.roundEntryHeader span {
  color: #7f8997;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.1em;
}


/* SHARED ROUND / ACTION HEADER */

.roundHeader {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-bottom: 28px;
}

.roundHeader > div {
  min-width: 0;
}

.roundHeader > div > span {
  color: #7f8997;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.roundHeader h1 {
  margin: 3px 0 0;
  font-size: 34px;
}

.roundBack {
  width: 54px;
  height: 54px;
  flex: 0 0 auto;
  border: 1px solid #2d3540;
  border-radius: 15px;
  background: #171c24;
  color: white;
  font-size: 25px;
}

.roundEntryLayout {
  display: grid;
  grid-template-columns:
    minmax(0, 1fr)
    330px;

  gap: 22px;
  align-items: start;
}

.roundPlayers {
  display: grid;
  grid-template-columns:
    1fr 1fr;
  gap: 12px;
}

.roundPlayerCard {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;

  width: 100%;
  min-height: 125px;

  padding: 20px;

  border: 2px solid #282f39;
  border-radius: 18px;

  background: #171c24;
  color: white;

  text-align: left;
}

.roundPlayerCard.active {
  border-color: #8faeff;
  background: #1c2330;
}

.roundPlayerCard strong {
  font-size: 23px;
}

.roundPlayerScore {
  min-width: 60px;
  text-align: right;
  font-size: 42px;
  font-weight: 850;
  line-height: 1;
}

.autoScore {
  display: block;
  width: fit-content;

  margin-top: 8px;
  padding: 4px 7px;

  border-radius: 6px;

  background: #29313d;
  color: #a8b4c2;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.cardTotal {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-top: 14px;
  padding: 22px 24px;

  border: 1px solid #282f39;
  border-radius: 18px;

  background: #171c24;
}

.cardTotal.valid {
  border-color: #4b9865;
}

.cardTotal > span {
  color: #8993a1;
  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.cardTotal strong {
  font-size: 38px;
}

.cardTotal small {
  color: #798493;
  font-size: 20px;
}

.roundMessage {
  min-height: 22px;
  margin: 12px 4px 0;
  color: #aab3bf;
  font-size: 14px;
}

/* KEYPAD */

.numberPadPanel {
  padding: 18px;

  border: 1px solid #282f39;
  border-radius: 18px;

  background: #171c24;
}

.numberPadPlayer {
  display: flex;
  align-items: baseline;
  justify-content: space-between;

  gap: 12px;
  margin-bottom: 14px;
}

.numberPadPlayer span {
  color: #7e8998;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.numberPadPlayer strong {
  font-size: 20px;
}

.numberPad {
  display: grid;
  grid-template-columns:
    repeat(4, 1fr);

  gap: 9px;
}

.numberPad button {
  min-height: 66px;

  border: 1px solid #303946;
  border-radius: 14px;

  background: #202731;
  color: white;

  font-size: 24px;
  font-weight: 800;
}

.numberPad button:active {
  background: #303a48;
}

.numberPad .numberPadSecondary {
  color: #aab4c1;
  font-size: 19px;
}

.nextScorePlayer {
  width: 100%;
  min-height: 58px;

  margin-top: 11px;

  border: 0;
  border-radius: 14px;

  background: #323b48;
  color: white;

  font-weight: 850;
}

.saveStandardRound {
  width: 100%;
  min-height: 76px;

  margin-top: 18px;

  border: 0;
  border-radius: 18px;

  background: #f2f4f6;
  color: #101419;

  font-size: 18px;
  font-weight: 850;
}

.saveStandardRound:disabled {
  background: #252b34;
  color: #5f6976;
  cursor: not-allowed;
}

/* TIE DIALOG */

.tieOverlay {
  position: fixed;
  inset: 0;
  z-index: 50;

  display: grid;
  place-items: center;

  padding: 24px;

  background:
    rgba(5, 7, 10, 0.84);
}

.tieDialog {
  width: min(
    100%,
    470px
  );

  padding: 28px;

  border: 1px solid #323b47;
  border-radius: 22px;

  background: #171c24;
}

.tieLabel {
  color: #d9ae4b;

  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.tieDialog h2 {
  margin: 8px 0 4px;
  font-size: 32px;
}

.tieDialog p {
  margin: 0 0 20px;
  color: #9aa5b3;
}

.tieChoices {
  display: grid;
  gap: 10px;
}

.tieChoices button {
  min-height: 64px;

  border: 1px solid #323b47;
  border-radius: 14px;

  background: #222a35;
  color: white;

  font-size: 19px;
  font-weight: 800;
}

@media (max-width: 760px) {
  .roundEntryLayout {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .roundPlayers {
    grid-template-columns: 1fr;
  }
}

/* ==============================
   TITLE RACE
================================ */

.raceAction {
  background: #2d3541 !important;
  color: #f5f7fa !important;
}

.racePage {
  max-width: 1200px;
}

.raceHeader {
  display: grid;
  grid-template-columns:
    auto 1fr auto;
  align-items: center;
  gap: 18px;
  margin-bottom: 22px;
}

.raceHeader > div > span {
  color: #7e8998;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.raceHeader h1 {
  margin: 3px 0 0;
  font-size: 34px;
}

.racePlay {
  min-width: 110px;
  min-height: 52px;

  border: 0;
  border-radius: 14px;

  background: #f2f4f6;
  color: #101419;

  font-weight: 850;
}

.racePlay:disabled {
  opacity: 0.35;
}

.raceChart {
  padding: 18px 8px 4px;

  border: 1px solid #282f39;
  border-radius: 20px;

  background: #141920;
}

.raceControls {
  display: grid;
  grid-template-columns:
    1fr auto;
  align-items: center;
  gap: 20px;

  margin-top: 18px;
}

.raceControls input {
  width: 100%;
  accent-color: #f2f4f6;
}

.raceRoundCount {
  min-width: 105px;
  color: #8994a2;
  font-size: 13px;
  font-weight: 800;
  text-align: right;
}

.raceStandings {
  display: grid;
  gap: 8px;

  margin-top: 20px;
}

.raceStanding {
  display: grid;
  grid-template-columns:
    40px 1fr auto;
  align-items: center;

  min-height: 52px;
  padding: 0 16px;

  border-radius: 12px;
  background: #171c24;

  will-change: transform;
}

.raceStanding > span {
  color: #788391;
  font-weight: 900;
}

.raceStanding strong {
  font-size: 16px;
}

.raceStanding b {
  font-size: 20px;
}

.raceEmpty {
  padding: 60px 20px;

  border: 1px dashed #303844;
  border-radius: 18px;

  color: #7f8997;
  text-align: center;
}

@media (max-width: 600px) {
  .gameActions {
    grid-template-columns: 1fr;
  }

  .raceChart {
    padding-left: 0;
    padding-right: 0;
  }

  .raceControls {
    grid-template-columns: 1fr;
  }

  .raceRoundCount {
    text-align: center;
  }
}

.raceHeaderActions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.raceSpeed {
  min-width: 66px;
  min-height: 52px;

  border: 1px solid #303844;
  border-radius: 14px;

  background: #171c24;
  color: #f5f7fa;

  font-weight: 850;
}

.raceSpeed:active {
  background: #252d39;
}

/* ==============================
   DATA / BACKUP
================================ */

.gameHeaderActions,
.setupHeaderActions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.dataButton {
  min-height: 48px;
  padding: 0 18px;

  border: 1px solid #39414c;
  border-radius: 13px;

  background: #171c24;
  color: #f2f4f6;

  font-weight: 800;
}

.dataOverlay {
  position: fixed;
  inset: 0;
  z-index: 100;

  display: grid;
  place-items: center;

  padding: 22px;

  background:
    rgba(4, 6, 9, 0.84);
}

.dataPanel {
  width: min(
    100%,
    620px
  );

  padding: 26px;

  border: 1px solid #303844;
  border-radius: 22px;

  background: #171c24;
}

.dataHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;

  margin-bottom: 22px;
}

.dataHeader span {
  color: #7f8997;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.dataHeader h2 {
  margin: 3px 0 0;
  font-size: 30px;
}

.dataHeader > button {
  width: 46px;
  height: 46px;

  border: 1px solid #303844;
  border-radius: 13px;

  background: #202731;
  color: white;

  font-size: 24px;
}

.dataOption {
  display: grid;
  grid-template-columns:
    minmax(0, 1fr)
    auto;

  align-items: center;
  gap: 20px;

  padding: 20px 0;

  border-top:
    1px solid #29313b;
}

.dataOption strong {
  font-size: 18px;
}

.dataOption p {
  margin: 6px 0 0;

  color: #8994a2;

  font-size: 14px;
  line-height: 1.45;
}

.dataOption > button,
.dataOption > label {
  min-width: 100px;
  min-height: 48px;

  display: grid;
  place-items: center;

  padding: 0 16px;

  border: 0;
  border-radius: 13px;

  background: #f2f4f6;
  color: #101419;

  cursor: pointer;

  font-weight: 850;
}

.dataOption input {
  display: none;
}

.importDisabled {
  opacity: 0.4;
  pointer-events: none;
}

.dataWarning {
  margin: 16px 0 0;

  color: #737f8e;

  font-size: 12px;
}

@media (max-width: 520px) {
  .dataOption {
    grid-template-columns: 1fr;
  }

  .dataOption > button,
  .dataOption > label {
    width: 100%;
  }
}

/* ==============================
   PENALTY
================================ */

.penaltyPanel {
  max-width: 760px;
  margin: 0 auto;
}

.penaltyPrompt {
  margin: 10px 0 16px;

  color: #8994a2;

  font-size: 17px;
  font-weight: 700;
}

.penaltyPlayers {
  display: grid;
  gap: 10px;
}

.penaltyPlayer {
  display: flex;
  align-items: center;
  justify-content: space-between;

  min-height: 84px;
  padding: 15px 20px;

  border: 1px solid #303844;
  border-radius: 16px;

  background: #171c24;
  color: white;

  text-align: left;
}

.penaltyPlayer > div {
  display: grid;
  gap: 5px;
}

.penaltyPlayer strong {
  font-size: 22px;
  font-weight: 700;
}

.penaltyPlayer span {
  color: #858f9c;

  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.penaltyPlayer b {
  font-size: 30px;
}

.penaltyPlayer:active {
  transform: scale(0.985);
}

.penaltyAction {
  background: #47272b !important;
  color: #f1a0a7 !important;
}


/* ==============================
   JIM ROUND
================================ */

.jimRoundPage {
  width: 100%;
  max-width: 1000px;
  margin: 0 auto;
}

.jimPanel {
  width: 100%;
  max-width: 760px;
  margin: 0 auto;

  display: grid;
  gap: 24px;
}

/* ---------- HEADINGS ---------- */

.jimSectionTitle,
.jimCurrentPlayer,
.jimWinTitle {
  display: grid;
  gap: 5px;
}

.jimSectionTitle span,
.jimCurrentPlayer span,
.jimWinTitle > span {
  color: #8290a2;

  font-size: 11px;
  font-weight: 700;

  letter-spacing: 0.08em;
}

.jimSectionTitle h2,
.jimCurrentPlayer h2,
.jimWinTitle h2 {
  margin: 0;

  color: #f5f7fa;

  font-size: 30px;
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.02em;
}

/* ---------- PLAYER CHOICES ---------- */

.jimPlayerChoices {
  width: 100%;

  display: grid !important;

  grid-template-columns:
    repeat(2, minmax(0, 1fr)) !important;

  gap: 12px !important;
}

.jimPlayerChoice {
  width: 100% !important;
  min-width: 0 !important;

  min-height: 82px;

  display: flex;
  align-items: center;
  justify-content: center;

  padding: 14px 18px;

  border: 1px solid #303946 !important;
  border-radius: 16px !important;

  background: #171d25 !important;
  color: #f5f7fa !important;

  font: inherit;
  font-size: 22px !important;
  font-weight: 700 !important;

  text-align: center;

  cursor: pointer;
}

.jimPlayerChoice:hover {
  background: #1d242e !important;
}

.jimPlayerChoice:active {
  transform: scale(0.985);
}

.jimPlayerChoice.selected {
  border-color: #d5ad53 !important;

  background: #332c1f !important;
  color: #f3ce77 !important;
}

/* ---------- PROGRESS ---------- */

.jimProgress {
  width: 100%;

  padding: 24px 20px 22px;

  border: 1px solid #2b333e;
  border-radius: 22px;

  background: #151a21;
}

.jimProgressTop {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;

  gap: 8px;
  margin-bottom: 22px;

  text-align: center;
}

.jimProgressTop span {
  color: #8290a2;

  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.jimProgressTop strong {
  color: #f5f7fa;

  font-size: 38px;
  line-height: 1;
}

/* ---------- SIX JIM STAGES ---------- */

.jimStages {
  width: 100%;

  display: grid !important;

  grid-template-columns:
    repeat(6, minmax(0, 1fr)) !important;

  gap: 12px !important;

  justify-items: center;
  align-items: start;
  padding-bottom: 20px;
}

.jimStage {
  position: relative;

  width: 72px;
  height: 72px;
  min-width: 72px;
  min-height: 72px;

  display: grid;
  place-items: center;

  border: 2px solid #303946;
  border-radius: 999px;

  background: #10151b;
  color: #697585;

  font-size: 22px;
  font-weight: 700;

  box-shadow:
    inset 0 0 0 1px rgba(255,255,255,0.02);
}

.jimStage.survived {
  border-color: #315940;

  background: #1e3828;
  color: #8fd6a3;
}

.jimStage.current {
  border-color: #d6ae55;

  background: #2b2417;
  color: #f1cc74;
}

.jimStage.hidden {
  border-color: #9171c1;

  background: #302640;
  color: #caadf0;
}

.jimStage small {
  position: absolute;

  left: 50%;
  bottom: -18px;

  transform: translateX(-50%);

  padding: 2px 6px;

  border-radius: 999px;

  background: #5a4680;
  color: #f1e9ff;

  text-align: center;

  font-size: 8px;
  font-weight: 900;
  line-height: 1;

  letter-spacing: 0.08em;
  white-space: nowrap;
}
/* ---------- HIDE ---------- */

.jimHideArea {
  width: 100%;
}

.jimHideButton {
  width: 100% !important;

  min-height: 68px;

  border: 1px solid #8867b7 !important;
  border-radius: 15px !important;

  background: #2c233c !important;
  color: #cbb0ef !important;

  font: inherit;
  font-size: 17px !important;
  font-weight: 700 !important;

  letter-spacing: 0.04em;
}

.jimHideButton:disabled {
  border-color: #2b333e !important;

  background: #171c23 !important;
  color: #606c7b !important;
}

.jimHideUsed {
  width: 100%;
  min-height: 68px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  padding: 0 20px;

  border: 1px solid #8867b7;
  border-radius: 15px;

  background: #2c233c;
  color: #cbb0ef;
}

.jimHideUsed span {
  font-size: 11px;
  font-weight: 900;

  letter-spacing: 0.1em;
}

.jimHideUsed strong {
  font-size: 21px;
}

/* ---------- MAIN JIM BUTTONS ---------- */

.jimMainActions {
  width: 100%;

  display: grid !important;

  grid-template-columns:
    2fr 1fr !important;

  gap: 12px !important;
}

.jimSurvivedButton,
.jimCaughtButton,
.jimConfirmButton {
  width: 100% !important;

  min-height: 70px;

  border: 0 !important;
  border-radius: 15px !important;

  font: inherit;
  font-size: 17px !important;
  font-weight: 700 !important;

  cursor: pointer;
}

.jimSurvivedButton {
  background: #f0f2f5 !important;
  color: #101318 !important;
}

.jimCaughtButton {
  background: #47272c !important;
  color: #f1a0a8 !important;
}

/* ---------- RESULT SUMMARY ---------- */

.jimOutcomeSummary {
  width: 100%;

  display: grid !important;

  grid-template-columns:
    repeat(4, minmax(0, 1fr)) !important;

  gap: 10px !important;
}

.jimOutcomeSummary > div {
  min-width: 0;

  padding: 16px;

  border: 1px solid #29313b;
  border-radius: 14px;

  background: #151a21;
}

.jimOutcomeSummary span {
  display: block;

  margin-bottom: 6px;

  color: #7f8b9a;

  font-size: 9px;
  font-weight: 900;

  letter-spacing: 0.09em;
}

.jimOutcomeSummary strong {
  display: block;

  color: #f5f7fa;

  font-size: 22px;
}

/* ---------- CONFIRM ---------- */

.jimConfirmButton {
  background: #eef1f5 !important;
  color: #101318 !important;
}

.jimConfirmButton:disabled {
  opacity: 0.4;
}

.jimWinConfirm {
  background: #d2ab50 !important;
  color: #17130b !important;
}

/* ---------- WIN ---------- */

.jimWinTitle > strong {
  margin-top: 4px;

  color: #d8b45d;

  font-size: 48px;
  line-height: 1;
}

/* ---------- ROTATION NOTE ---------- */

.jimRotationNote {
  margin: 0;

  color: #909ba8;

  font-size: 15px;
}

/* ---------- SMALLER SCREENS ---------- */

@media (max-width: 600px) {
  .jimPanel {
    gap: 18px;
  }

  .jimPlayerChoices {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }

  .jimPlayerChoice {
    min-height: 72px;

    font-size: 19px !important;
  }

  .jimStages {
    gap: 5px !important;
  }

.jimStage {
  width: 56px;
  height: 56px;
  min-width: 56px;
  min-height: 56px;

  font-size: 18px;
}
  .jimOutcomeSummary {
    grid-template-columns:
      repeat(2, minmax(0, 1fr)) !important;
  }

  .jimMainActions {
    grid-template-columns: 1fr !important;
  }
}

/* ==============================
   HISTORY & STATS
================================ */

.historyPage {
  max-width: 1100px;
}

.historyHeader {
  display: flex;
  align-items: center;
  gap: 18px;
  margin-bottom: 26px;
}

.historyHeader > div > span {
  color: #7f8997;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.historyHeader h1 {
  margin: 3px 0 0;
  font-size: 34px;
}

.historyTabs {
  display: grid;
  grid-template-columns:
    repeat(4, 1fr);
  gap: 7px;

  margin-bottom: 22px;
  padding: 6px;

  border-radius: 16px;
  background: #13171d;
}

.historyTabs button {
  min-height: 52px;

  border: 0;
  border-radius: 12px;

  background: transparent;
  color: #7f8997;

  font-weight: 800;
}

.historyTabs button.active {
  background: #29323e;
  color: #f5f7fa;
}

/* SESSION HISTORY */

.historySessionList {
  display: grid;
  gap: 12px;
}

.historySession {
  overflow: hidden;

  border: 1px solid #29313b;
  border-radius: 18px;

  background: #171c24;
}

.historySessionSummary {
  width: 100%;
  min-height: 88px;

  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  padding: 16px 20px;

  border: 0;

  background: transparent;
  color: #f5f7fa;

  text-align: left;
}

.historySessionSummary > div:first-child {
  display: grid;
  gap: 4px;
}

.historySessionSummary > div:first-child strong {
  font-size: 20px;
}

.historySessionSummary > div:first-child span,
.historySessionSummaryRight > span {
  color: #8793a1;
  font-size: 13px;
}

.historySessionSummaryRight {
  display: flex;
  align-items: center;
  gap: 12px;
}

.historySessionSummaryRight b {
  padding: 5px 8px;

  border-radius: 7px;

  background: #29323d;
  color: #9eabb9;

  font-size: 10px;
  letter-spacing: 0.08em;
}

.historySessionSummaryRight b.active {
  background: #20372a;
  color: #81d499;
}

.historySessionDetails {
  padding: 18px 20px 20px;

  border-top: 1px solid #29313b;
}

.historySessionMeta {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 9px;

  margin-bottom: 16px;
}

.historySessionMeta > div {
  min-width: 0;

  padding: 14px;

  border-radius: 13px;

  background: #11151b;
}

.historySessionMeta span {
  display: block;

  margin-bottom: 5px;

  color: #778392;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.historySessionMeta strong {
  display: block;

  overflow: hidden;

  font-size: 18px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.historyStandings {
  display: grid;
  gap: 7px;
}

.historyStanding {
  display: grid;
  grid-template-columns:
    38px minmax(0, 1fr) auto;
  align-items: center;

  min-height: 62px;

  padding: 8px 14px;

  border-radius: 12px;

  background: #202731;
}

.historyStanding > span {
  color: #788391;
  font-weight: 850;
}

.historyStanding > div {
  display: grid;
  gap: 3px;

  min-width: 0;
}

.historyStanding > div > strong {
  overflow: hidden;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.historyStanding small {
  color: #8994a2;
}

.historyStanding > b {
  font-size: 22px;
}

.historyRaceButton {
  width: 100%;
  min-height: 58px;

  margin-top: 14px;

  border: 0;
  border-radius: 14px;

  background: #303946;
  color: #f5f7fa;

  font-weight: 850;
}

.historyEmpty {
  padding: 50px 20px;

  border: 1px dashed #303844;
  border-radius: 17px;

  color: #7f8997;

  text-align: center;
}

/* PLAYER STATS */

.playerStatsList {
  display: grid;
  gap: 14px;
}

.playerStatsCard {
  padding: 20px;

  border: 1px solid #29313b;
  border-radius: 18px;

  background: #171c24;
}

.playerStatsCard > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  margin-bottom: 18px;
}

.playerStatsCard > header > div {
  display: grid;
  gap: 3px;
}

.playerStatsCard h2 {
  margin: 0;

  font-size: 27px;
}

.playerStatsCard > header span {
  color: #8994a2;
  font-size: 13px;
}

.playerStatsCard > header > strong {
  font-size: 21px;
}

.playerStatSectionLabel {
  margin: 17px 2px 8px;

  color: #7c8795;

  font-size: 14px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.playerStatGrid {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.playerStatGrid > div {
  min-width: 0;

  padding: 14px;

  border-radius: 13px;

  background: #11151b;
}

.playerStatGrid span {
  display: block;

  min-height: 24px;
  margin-bottom: 5px;

  color: #778392;

  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.07em;
}

.playerStatGrid strong {
  font-size: 23px;
}

.hideStageBreakdown {
  display: grid;
  grid-template-columns:
    auto repeat(4, 1fr);
  align-items: center;
  gap: 8px;

  margin-top: 10px;
  padding: 11px 13px;

  border: 1px solid #3c3250;
  border-radius: 13px;

  background: #1d1827;
}

.hideStageBreakdown > span {
  color: #a891c5;

  font-size: 13px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.hideStageBreakdown > div {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 5px;
}

.hideStageBreakdown small {
  color: #8f7ba8;
  font-size: 11px;
}

.hideStageBreakdown strong {
  color: #d0b7ef;
}

/* AWARDS */

.historyAwards {
  display: grid;
  gap: 18px;
}

.awardsIntro {
  padding: 5px 2px 2px;
}

.awardsIntro > span {
  color: #d9ae4b;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.awardsIntro h2 {
  margin: 5px 0 6px;

  font-size: 31px;
}

.awardsIntro p {
  max-width: 620px;
  margin: 0;

  color: #8994a2;
  line-height: 1.5;
}

.awardGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.awardCard {
  min-width: 0;

  padding: 20px;

  border: 1px solid #303844;
  border-radius: 18px;

  background: #171c24;
}

.awardCard > span {
  color: #d9ae4b;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.awardCard h3 {
  margin: 8px 0 4px;

  overflow-wrap: anywhere;

  font-size: 27px;
}

.awardCard > strong {
  color: #b5c0cd;

  font-size: 15px;
}

.awardCard p {
  margin: 11px 0 0;

  color: #7f8b99;

  font-size: 13px;
  line-height: 1.4;
}

@media (max-width: 700px) {
  .historySessionMeta {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .playerStatSectionLabel {
    font-size: 13px;
  }

  .playerStatGrid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .playerStatGrid span,
  .hideStageBreakdown > span {
    font-size: 11px;
  }

  .awardGrid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 520px) {
  .historySessionSummary {
    align-items: flex-start;
  }

  .historySessionSummaryRight {
    flex-direction: column;
    align-items: flex-end;
    gap: 5px;
  }

  .hideStageBreakdown {
    grid-template-columns:
      1fr 1fr;
  }

  .hideStageBreakdown > span {
    grid-column: 1 / -1;
  }
}


/* ==============================
   SESSION AWARDS
================================ */

.sessionAwardsSection {
  margin-top: 20px;
  padding-top: 18px;

  border-top: 1px solid #29313b;
}

.sessionAwardsHeader {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;

  margin-bottom: 12px;
}

.sessionAwardsHeader span {
  color: #d9ae4b;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.sessionAwardsHeader strong {
  color: #8994a2;

  font-size: 13px;
}

.sessionAwardGrid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  gap: 9px;
}

.sessionAwardCard {
  padding: 15px;

  background: #141920;
}

.sessionAwardCard > span {
  font-size: 9px;
}

.sessionAwardCard h3 {
  margin: 6px 0 3px;

  font-size: 21px;
}

.sessionAwardCard > strong {
  font-size: 13px;
}

.sessionAwardCard p {
  margin-top: 8px;

  font-size: 12px;
}

@media (max-width: 600px) {
  .sessionAwardGrid {
    grid-template-columns: 1fr;
  }

  .sessionAwardsHeader {
    align-items: flex-start;
    flex-direction: column;
    gap: 3px;
  }
}

/* ==============================
   AWARD COLORS + BIGGER TITLES
   History / Session Awards CSS.
================================ */

.awardCard {
  --award-color: #d9ae4b;

  border-left:
    4px solid var(--award-color);
}

.awardCard > span {
  color: var(--award-color);

  font-size: 15px;
  font-weight: 950;
  letter-spacing: 0.08em;
}

.awardCard > strong {
  color: var(--award-color);
}

/* Session cards are smaller overall,
   but the award name should still
   be obvious at a glance. */

.sessionAwardCard > span {
  font-size: 13px;
}

.sessionAwardCard h3 {
  font-size: 23px;
}

/* Each family title gets its own
   stable visual identity. */

.awardTone-cuci {
  --award-color: #6fc8d4;
}

.awardTone-slayer {
  --award-color: #ef7f89;
}

.awardTone-tuah {
  --award-color: #e0b65c;
}

.awardTone-malang {
  --award-color: #b491df;
}

.awardTone-standard {
  --award-color: #79a7f2;
}

.awardTone-jim {
  --award-color: #e79a61;
}

.awardTone-hide {
  --award-color: #bd8fe9;
}

.awardTone-denda {
  --award-color: #e88b9c;
}

.awardTone-survivor {
  --award-color: #7fcf95;
}

.awardTone-comeback {
  --award-color: #67c5b3;
}

.awardTone-jatuh {
  --award-color: #d7838f;
}

.awardTone-default {
  --award-color: #aab5c2;
}

@media (max-width: 600px) {
  .awardCard > span {
    font-size: 14px;
  }

  .sessionAwardCard > span {
    font-size: 12px;
  }
}

/* ==============================
   HISTORY V3
   History / Awards CSS.
================================ */

/* SESSION DETAILS */

.historySessionMetaExpanded {
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
}

/* PLAYER SORTING */

.playerSortPanel {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;

  margin-bottom: 14px;
  padding: 16px 18px;

  border: 1px solid #29313b;
  border-radius: 16px;

  background: #151a21;
}

.playerSortPanel > div:first-child {
  display: grid;
  gap: 3px;

  flex: 0 0 auto;
}

.playerSortPanel > div:first-child span {
  color: #788493;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.playerSortPanel > div:first-child strong {
  font-size: 17px;
}

.playerSortButtons {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 7px;
}

.playerSortButtons button {
  min-height: 38px;
  padding: 0 12px;

  border: 1px solid #303945;
  border-radius: 10px;

  background: #202630;
  color: #8f9aa7;

  font-size: 11px;
  font-weight: 850;
}

.playerSortButtons button.active {
  border-color: #59697d;

  background: #344152;
  color: #f5f7fa;
}

.playerStatsIdentity {
  display: flex !important;
  align-items: center;
  gap: 13px;
}

.playerStatsRank {
  display: grid !important;
  place-items: center;

  width: 42px;
  height: 42px;

  flex: 0 0 42px;

  border-radius: 12px;

  background: #242c36;
  color: #9ba7b5 !important;

  font-size: 13px !important;
  font-weight: 900;
}

.playerStatsHeadline {
  display: grid;
  justify-items: end;
  gap: 1px;
}

.playerStatsHeadline strong {
  font-size: 25px;
}

.playerStatsHeadline span {
  color: #778391;

  font-size: 8px !important;
  font-weight: 900;
  letter-spacing: 0.09em;
}

/* AWARD SECTIONS */

.awardSection {
  display: grid;
  gap: 13px;

  margin-top: 10px;
}

.awardSection + .awardSection {
  margin-top: 28px;
  padding-top: 27px;

  border-top: 1px solid #29313b;
}

.awardSectionHeader {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 30px;

  padding: 0 2px;
}

.awardSectionHeader > div {
  display: grid;
  gap: 3px;
}

.awardSectionHeader > div > span {
  color: #8a95a3;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.awardSectionHeader h3 {
  margin: 0;

  font-size: 25px;
}

.awardSectionHeader p {
  max-width: 420px;
  margin: 0;

  color: #74808e;

  font-size: 12px;
  line-height: 1.45;
  text-align: right;
}

.awardRecordNote {
  display: block;

  margin-top: 5px;

  color: #8995a3;

  font-size: 11px;
  font-weight: 800;
}

.rateAwardCard {
  min-height: 180px;
}

/* Updated award tones */

.awardTone-denda {
  --award-color: #df8a72;
}

.awardTone-duration {
  --award-color: #70b8d9;
}

.awardTone-rounds {
  --award-color: #8ca8e8;
}

/* Bigger award identity */

.awardCard > span {
  font-size: 25px;
}

.awardCard h3 {
  margin-top: 10px;

  font-size: 28px;
}

.awardCard > strong {
  font-size: 17px;
}

/* Mobile */

@media (max-width: 800px) {
  .playerSortPanel {
    align-items: flex-start;
    flex-direction: column;
  }

  .playerSortButtons {
    justify-content: flex-start;

    width: 100%;
  }

  .historySessionMetaExpanded {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .awardSectionHeader {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }

  .awardSectionHeader p {
    max-width: none;

    text-align: left;
  }
}

@media (max-width: 520px) {
  .playerSortButtons {
    display: grid;
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .playerSortButtons button {
    width: 100%;
  }

  .playerStatsCard > header {
    align-items: flex-start;
  }

  .playerStatsHeadline {
    min-width: 70px;
  }

  .historySessionMetaExpanded {
    grid-template-columns: 1fr 1fr;
  }

  .awardCard > span {
    font-size: 25px;
  }

  .awardCard h3 {
    font-size: 23px;
  }
}

/* ==============================
   COMBINED ALL-TIME AWARDS
================================ */

.combinedAwardCard {
  grid-column: span 1;

  padding: 22px;
}

.combinedAwardDescription {
  margin: 8px 0 17px !important;

  color: #7f8b99 !important;

  font-size: 12px !important;
  line-height: 1.45 !important;
}

.combinedAwardMetrics {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  overflow: hidden;

  border: 1px solid #2b343f;
  border-radius: 14px;

  background: #11151b;
}

.combinedAwardMetric {
  min-width: 0;

  padding: 15px 16px;
}

.combinedAwardMetric +
.combinedAwardMetric {
  border-left:
    1px solid #2b343f;
}

.combinedAwardMetric small {
  display: block;

  margin-bottom: 6px;

  color: var(--award-color);

  font-size: 9px;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.09em;
}

.combinedAwardMetric h3 {
  margin: 0 0 3px;

  overflow-wrap: anywhere;

  font-size: 23px;
}

.combinedAwardMetric strong {
  display: block;

  color: var(--award-color);

  font-size: 15px;
}

.combinedAwardMetric em {
  display: block;

  margin-top: 5px;

  color: #778493;

  font-size: 10px;
  font-style: normal;
  font-weight: 750;
}

/* Raja Session */
.awardTone-session {
  --award-color: #75c6a7;
}

@media (max-width: 620px) {
  .combinedAwardMetrics {
    grid-template-columns: 1fr;
  }

  .combinedAwardMetric +
  .combinedAwardMetric {
    border-top:
      1px solid #2b343f;

    border-left: 0;
  }

  .combinedAwardMetric h3 {
    font-size: 21px;
  }
}

/* ==============================
   CLEAN SINGLE-SESSION WINNERS
================================ */

.sessionRecordWinners {
  display: grid;
  gap: 7px;

  margin: 10px 0 8px;
}

.sessionRecordWinner {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;

  min-width: 0;

  padding: 9px 11px;

  border-radius: 10px;

  background: #11151b;
}

.sessionRecordWinner h3 {
  min-width: 0;
  margin: 0;

  overflow: hidden;

  font-size: 22px;
  line-height: 1.15;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.sessionRecordWinner > span {
  flex: 0 0 auto;

  color: #82909f;

  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}

/* Keep the record value visually
   separate from the winner rows. */
.rateAwardCard > .sessionRecordWinners + strong {
  display: block;

  margin-top: 7px;
}

/* On small screens, let the date sit
   underneath instead of crushing names. */
@media (max-width: 520px) {
  .sessionRecordWinner {
    align-items: flex-start;
    flex-direction: column;
    gap: 2px;
  }

  .sessionRecordWinner h3 {
    width: 100%;

    overflow: visible;
    white-space: normal;
  }
}

/* ==============================
   CLEAN ALL-TIME TIED WINNERS
   combined award CSS.
================================ */

.combinedWinnerList {
  display: grid;
  gap: 5px;

  margin: 2px 0 7px;
}

.combinedWinnerRow {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;

  min-width: 0;
}

.combinedWinnerRow h3 {
  min-width: 0;
  margin: 0;

  overflow: hidden;

  font-size: 22px;
  line-height: 1.18;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.combinedWinnerRow > span {
  flex: 0 0 auto;

  color: #7f8b99;

  font-size: 10px;
  font-weight: 800;
  white-space: nowrap;
}

/* Keep the shared record value
   visually separate from tied names. */

.combinedAwardMetric >
.combinedWinnerList + strong {
  margin-top: 5px;
}

/* If many people share a record,
   the card grows vertically instead
   of forcing names onto one line. */

@media (max-width: 520px) {
  .combinedWinnerRow {
    align-items: flex-start;
    flex-direction: column;
    gap: 1px;
  }

  .combinedWinnerRow h3 {
    width: 100%;

    overflow: visible;
    white-space: normal;
  }
}

/* ==============================
   PER-SESSION AWARDS
================================ */

.historySessionActions {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 10px;

  margin-top: 14px;
}

.historySessionActions
.historyRaceButton,
.historySessionActions
.historyAwardsButton {
  width: 100%;
  min-height: 58px;
  margin-top: 0;

  border: 0;
  border-radius: 14px;

  font-weight: 850;
}

.historyAwardsButton {
  background: #26382f;
  color: #91d5aa;
}

.historyAwardsButton:hover {
  background: #2d4437;
}

.sessionAwardsPage {
  max-width: 1100px;
}

.sessionAwardsSummary {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 10px;

  margin-bottom: 18px;
}

.sessionAwardsSummary > div {
  padding: 15px 17px;

  border: 1px solid #29313b;
  border-radius: 14px;

  background: #151a21;
}

.sessionAwardsSummary span {
  display: block;

  margin-bottom: 4px;

  color: #788493;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.sessionAwardsSummary strong {
  font-size: 20px;
}

.sessionOwnAwardGrid {
  margin-top: 2px;
}

.sessionOwnAwardGrid
.awardCard {
  min-height: 190px;
}

@media (max-width: 600px) {
  .historySessionActions {
    grid-template-columns: 1fr;
  }

  .sessionAwardsSummary {
    grid-template-columns: 1fr 1fr;
  }
}

/* ==============================
   PLAYER SORT STAT HIGHLIGHT
================================ */

/* Grid statistic selected by the
   active player-sort button. */
.playerStatGrid > div.sortStatHighlight {
  position: relative;

  border:
    1px solid rgba(222, 181, 88, 0.62);

  background:
    linear-gradient(
      135deg,
      rgba(222, 181, 88, 0.11),
      #11151b 62%
    );

  box-shadow:
    inset 0 0 0 1px
      rgba(222, 181, 88, 0.05);
}

.playerStatGrid >
div.sortStatHighlight > span {
  color: #c7a755;
}

.playerStatGrid >
div.sortStatHighlight > strong {
  color: #f0c75e;
}

/* TOTAL PTS lives in the card header
   rather than the stat grid. */
.playerStatsHeadline.sortStatHighlight {
  min-width: 92px;
  padding: 9px 11px;

  border:
    1px solid rgba(222, 181, 88, 0.62);
  border-radius: 12px;

  background:
    linear-gradient(
      135deg,
      rgba(222, 181, 88, 0.12),
      rgba(17, 21, 27, 0.78)
    );
}

.playerStatsHeadline.sortStatHighlight
strong {
  color: #f0c75e;
}

.playerStatsHeadline.sortStatHighlight
span {
  color: #c7a755;
}

/* ==============================
   MVP TAB
================================ */

.mvpPage {
  display: grid;
  gap: 18px;
}

.mvpIntro {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 30px;

  padding: 4px 2px 2px;
}

.mvpIntro > div:first-child > span {
  color: #e0b65c;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.mvpIntro h2 {
  margin: 5px 0 6px;

  font-size: 31px;
}

.mvpIntro p {
  max-width: 650px;
  margin: 0;

  color: #8994a2;
  line-height: 1.5;
}

.mvpFormula {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, auto));
  gap: 6px 14px;

  padding: 14px 16px;

  border: 1px solid #303844;
  border-radius: 14px;

  background: #151a21;
}

.mvpFormula > span {
  grid-column: 1 / -1;

  color: #7c8795;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.mvpFormula strong {
  color: #c9d2dc;

  font-size: 12px;
}

.mvpEligibility {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 22px;

  padding: 14px 16px;

  border: 1px solid #3a3322;
  border-radius: 14px;

  background: #1b1913;
}

.mvpEligibility span {
  flex: 0 0 auto;

  color: #d9ae4b;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.mvpEligibility p {
  margin: 0;

  color: #9a8d6c;

  font-size: 12px;
  line-height: 1.45;
  text-align: right;
}

.mvpLeaderboard {
  display: grid;
  gap: 13px;
}

.mvpCard {
  padding: 20px;

  border: 1px solid #2d3641;
  border-radius: 18px;

  background: #171c24;
}

.mvpCard.mvpLeader {
  border-color: #5d4d27;

  box-shadow:
    inset 4px 0 0 #d9ae4b;
}

.mvpCard > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;

  margin-bottom: 16px;
}

.mvpIdentity {
  display: flex;
  align-items: center;
  gap: 13px;
}

.mvpIdentity > span {
  display: grid;
  place-items: center;

  width: 42px;
  height: 42px;

  border-radius: 12px;

  background: #252d37;
  color: #9aa6b5;

  font-size: 13px;
  font-weight: 900;
}

.mvpIdentity h3 {
  margin: 0 0 3px;

  font-size: 26px;
}

.mvpIdentity small {
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.09em;
}

.mvpProvisional {
  color: #c99963;
}

.mvpQualified {
  color: #75c895;
}

.mvpScore {
  display: grid;
  justify-items: end;
}

.mvpScore strong {
  color: #e0b65c;

  font-size: 36px;
  line-height: 1;
}

.mvpScore span {
  margin-top: 3px;

  color: #9d8245;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.mvpComponents {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.mvpComponents > div {
  min-width: 0;

  padding: 14px;

  border-radius: 13px;

  background: #11151b;
}

.mvpComponents span {
  display: block;

  margin-bottom: 5px;

  color: #788493;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.09em;
}

.mvpComponents strong {
  display: block;

  margin-bottom: 4px;

  font-size: 23px;
}

.mvpComponents small {
  color: #7f8b99;

  font-size: 10px;
  line-height: 1.35;
}

.mvpSample {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;

  margin-top: 11px;
}

.mvpSample span {
  padding: 5px 8px;

  border-radius: 8px;

  background: #222a34;
  color: #8d99a7;

  font-size: 10px;
  font-weight: 800;
}

.mvpMethodNote {
  padding: 15px 17px;

  border: 1px solid #2c3540;
  border-radius: 14px;

  background: #131820;
}

.mvpMethodNote strong {
  color: #9aa6b5;

  font-size: 10px;
  letter-spacing: 0.09em;
}

.mvpMethodNote p {
  margin: 6px 0 0;

  color: #778493;

  font-size: 12px;
  line-height: 1.5;
}

@media (max-width: 850px) {
  .mvpIntro {
    align-items: flex-start;
    flex-direction: column;
  }

  .mvpComponents {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .mvpEligibility {
    align-items: flex-start;
    flex-direction: column;
  }

  .mvpEligibility p {
    text-align: left;
  }
}

@media (max-width: 600px) {
  .historyTabs {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .mvpComponents {
    grid-template-columns: 1fr;
  }

  .mvpCard > header {
    align-items: flex-start;
  }

  .mvpScore strong {
    font-size: 30px;
  }
}

/* ==============================
   MVP QUALIFICATION TICKS
================================ */

.mvpSample span.complete {
  background: #1d3025;
  color: #7fd19a;
}

/* ==============================
   MVP PODIUM
================================ */

.mvpPodiumSection {
  padding: 22px 22px 0;

  border: 1px solid #303844;
  border-radius: 18px;

  background:
    radial-gradient(
      circle at 50% 0%,
      rgba(217, 174, 75, 0.11),
      transparent 46%
    ),
    #151a21;
}

.mvpPodiumHeader {
  text-align: center;
}

.mvpPodiumHeader > span,
.mvpLeaderboardHeader > span {
  color: #d9ae4b;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.mvpPodiumHeader h3,
.mvpLeaderboardHeader h3 {
  margin: 4px 0 0;

  font-size: 25px;
}

.mvpPodium {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
  align-items: end;
  gap: 14px;

  max-width: 900px;
  margin: 30px auto 0;
}

.mvpPodiumSlot {
  display: grid;
  grid-template-rows:
    auto auto auto;
  align-items: end;

  min-width: 0;
}

.mvpPodiumPlayer {
  position: relative;

  display: grid;
  justify-items: center;
  gap: 4px;

  padding: 17px 12px 14px;

  border: 1px solid #313a46;
  border-radius: 15px 15px 0 0;

  background: #1b212a;

  text-align: center;
}

.mvpPodiumPlayer > strong {
  max-width: 100%;

  overflow: hidden;

  font-size: 22px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mvpPodiumPlayer > small {
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.09em;
}

.mvpMedal {
  display: grid;
  place-items: center;

  width: 38px;
  height: 38px;

  margin-top: -37px;

  border: 3px solid #151a21;
  border-radius: 50%;

  background: #596473;
  color: #f5f7fa;

  font-size: 16px;
