  background:
    linear-gradient(
      180deg,
      #262317,
      #1d1d1b
    );
}

.mvpPodiumSlot.rank1
.mvpMedal {
  background: #d9ae4b;
  color: #1a160b;
}

.mvpPodiumSlot.rank1
.mvpPodiumScore strong {
  color: #e8bd57;
}

.mvpPodiumSlot.rank1
.mvpPodiumBlock {
  min-height: 190px;

  background:
    linear-gradient(
      180deg,
      #6c5624,
      #3c311b
    );
}

.mvpPodiumSlot.rank1
.mvpPodiumBlock span {
  color: #f1c969;
}

/* #2 silver */

.mvpPodiumSlot.rank2
.mvpMedal {
  background: #9ca8b5;
  color: #171b20;
}

.mvpPodiumSlot.rank2
.mvpPodiumScore strong {
  color: #c8d0d9;
}

.mvpPodiumSlot.rank2
.mvpPodiumBlock {
  min-height: 145px;

  background:
    linear-gradient(
      180deg,
      #48535f,
      #303a45
    );
