/* #3 bronze */

.mvpPodiumSlot.rank3
.mvpMedal {
  background: #ba8058;
  color: #1b120c;
}

.mvpPodiumSlot.rank3
.mvpPodiumScore strong {
  color: #d69a70;
}

.mvpPodiumSlot.rank3
.mvpPodiumBlock {
  min-height: 112px;

  background:
    linear-gradient(
      180deg,
      #5d4031,
      #352a25
    );
}

.mvpLeaderboardSection {
  display: grid;
  gap: 13px;

  margin-top: 2px;
}

.mvpLeaderboardHeader {
  padding: 0 2px;
}

/* Make the #1 detailed card a little
   quieter now that the podium is the hero. */

.mvpCard.mvpLeader {
  border-color: #3c4652;

  box-shadow: none;
}

/* Tablet / phone */

@media (max-width: 760px) {
  .mvpPodiumSection {
    padding: 18px 12px 0;
  }

  .mvpPodium {
    gap: 7px;

    margin-top: 28px;
  }

