/* ==============================
   STANDARD ROUND — QUICK RANK
   Round CSS.
================================ */

.standardModeBar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;

  max-width: 760px;
  margin: 0 auto 18px;
  padding: 14px 16px;

  border: 1px solid #2c3540;
  border-radius: 15px;

  background: #151a21;
}

.standardModeBar > div {
  display: grid;
  gap: 3px;
}

.standardModeBar > div > span {
  color: #7f8b99;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.standardModeBar > div > strong {
  font-size: 16px;
}

.standardModeButton {
  flex: 0 0 auto;

  min-height: 40px;
  padding: 0 14px;

  border: 1px solid #3a4552;
  border-radius: 10px;

  background: #252d38;
  color: #dfe5eb;

  font-size: 11px;
  font-weight: 850;
}

.quickRankPanel {
  position: relative;

  max-width: 760px;
  margin: 0 auto 18px;
}

.quickRankList {
  display: grid;

  margin: 0;
  padding: 0;

  list-style: none;
}

.quickRankItem {
  position: relative;

  margin: 0;
  padding: 0;

  list-style: none;

  touch-action: none;
}

.quickRankCard {
  display: grid;
  grid-template-columns:
    54px minmax(0, 1fr) auto 30px;
  align-items: center;
  gap: 13px;

  min-height: 84px;
  padding: 12px 16px;

  border: 1px solid #303a46;
  border-radius: 16px;

  background: #1a2028;

  cursor: grab;
  user-select: none;
}

.quickRankCard:active {
  cursor: grabbing;
}

.quickRankNumber {
  display: grid;
  place-items: center;

  width: 42px;
  height: 42px;

  border-radius: 12px;

  background: #252e39;
  color: #9ba8b6;

  font-size: 17px;
  font-weight: 950;
}

.quickRankPlayer {
  display: grid;
  gap: 3px;

  min-width: 0;
}

.quickRankPlayer strong {
  overflow: hidden;

  font-size: 22px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.quickRankPlayer span {
  color: #778493;

  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.quickRankPoints {
  display: grid;
  justify-items: end;
}

.quickRankPoints strong {
  font-size: 25px;
}

.quickRankPoints span {
  color: #788493;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.quickRankDrag {
  color: #647181;

  font-size: 20px;
  font-weight: 900;
}

/*
  The small divider between cards is
  the "connect these two" control.
*/
.rankTieConnector {
  position: relative;
  z-index: 3;

  display: grid;
  place-items: center;

  width: calc(100% - 36px);
  height: 24px;
  margin: -1px 18px;

  border: 0;

  background: transparent;
}

.rankTieConnector::before {
  content: '';

  position: absolute;

  left: 0;
  right: 0;
  top: 50%;

  height: 1px;

  background: #27303a;
}

.rankTieConnector > span {
  position: relative;
  z-index: 1;

  display: grid;
  place-items: center;

  min-width: 30px;
  height: 20px;
  padding: 0 7px;

  border: 1px solid #34404d;
  border-radius: 999px;

  background: #11161c;
  color: #7e8997;

  font-size: 10px;
  font-weight: 950;
  letter-spacing: 0.05em;
}

.rankTieConnector.active {
  height: 30px;

  margin-top: -4px;
  margin-bottom: -4px;

  border-right: 2px solid #856fd0;
  border-left: 2px solid #856fd0;

  background:
    rgba(133, 111, 208, 0.08);
}

.rankTieConnector.active::before {
  background: #856fd0;
}

.rankTieConnector.active > span {
  border-color: #856fd0;

  background: #302747;
  color: #c9b8f3;
}

.quickRankCard.tiedWithNext,
.quickRankCard.tiedWithPrevious {
  border-color: #6757a1;

  background:
    linear-gradient(
      90deg,
      rgba(116, 91, 180, 0.08),
      #1a2028 45%
    );
}

.quickRankCard.tiedWithNext {
  border-bottom-right-radius: 8px;
  border-bottom-left-radius: 8px;
}

.quickRankCard.tiedWithPrevious {
  border-top-right-radius: 8px;
  border-top-left-radius: 8px;
}

.quickRankCard.tiedWithNext
.quickRankPlayer span,
.quickRankCard.tiedWithPrevious
.quickRankPlayer span {
  color: #aa98db;
}

.quickRankHint {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px 16px;

  margin-top: 13px;

  color: #74808e;

  font-size: 10px;
  font-weight: 750;
}

.quickRankToast {
  position: sticky;
  bottom: 18px;
  z-index: 10;

  width: fit-content;
  max-width: calc(100% - 24px);

  margin: 14px auto 0;
  padding: 9px 13px;

  border: 1px solid #5d4b8d;
  border-radius: 999px;

  background: #251f34;
  color: #cdbcf3;

  font-size: 11px;
  font-weight: 850;
  text-align: center;
}

/* The old exact-score mode remains
   secondary, not the default. */

.nextScorePlayer:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

@media (max-width: 620px) {
  .standardModeBar {
    align-items: flex-start;
    flex-direction: column;
  }

  .standardModeButton {
    width: 100%;
  }

  .quickRankCard {
    grid-template-columns:
      44px minmax(0, 1fr) auto 24px;

    min-height: 76px;
    padding: 10px 12px;
  }

  .quickRankNumber {
    width: 36px;
    height: 36px;

    font-size: 15px;
  }

  .quickRankPlayer strong {
    font-size: 18px;
  }

  .quickRankPoints strong {
    font-size: 21px;
  }
}

/* ==============================
   PENALTY CONFIRMATION MODAL
================================ */

.penaltyConfirmOverlay {
  position: fixed;
  inset: 0;
  z-index: 1000;

  display: grid;
  place-items: center;

  padding: 22px;

  background: rgba(5, 8, 12, 0.76);
  backdrop-filter: blur(8px);
}

.penaltyConfirmDialog {
  width: min(100%, 520px);
  padding: 28px;

  border: 1px solid #4a3035;
  border-radius: 22px;

  background: #171c24;

  box-shadow:
    0 24px 70px rgba(0, 0, 0, 0.45);
}

.penaltyConfirmLabel {
  color: #dc7d87;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.penaltyConfirmDialog h2 {
  margin: 8px 0 22px;

  font-size: 30px;
  line-height: 1.15;
}

.penaltyConfirmPoints {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 12px;

  margin-bottom: 22px;
}

.penaltyConfirmPoints > div:not(
  .penaltyConfirmArrow
) {
  padding: 16px;

  border-radius: 14px;

  background: #11151b;
}

.penaltyConfirmPoints span {
  display: block;

  margin-bottom: 5px;

  color: #7e8997;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.penaltyConfirmPoints strong {
  font-size: 30px;
}

.penaltyConfirmArrow {
  color: #697583;

  font-size: 22px;
  font-weight: 900;
}

.penaltyConfirmActions {
  display: grid;
  grid-template-columns: 1fr 1.4fr;
  gap: 10px;
}

.penaltyConfirmActions button {
  min-height: 58px;

  border-radius: 14px;

  font-size: 15px;
  font-weight: 850;
}

.penaltyCancelButton {
  border: 1px solid #39434f;

  background: #232a33;
  color: #b5bfca;
}

.penaltyConfirmButton {
  border: 0;

  background: #6a3037;
  color: #f4dfe2;
}

.penaltyConfirmButton:hover {
  background: #793740;
}

.penaltyConfirmActions button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

@media (max-width: 520px) {
  .penaltyConfirmDialog {
    padding: 22px;
  }

  .penaltyConfirmDialog h2 {
    font-size: 25px;
  }

  .penaltyConfirmActions {
    grid-template-columns: 1fr;
  }
}

/* ==============================
   MAIN SCOREBOARD POLISH
================================ */

/* ---------- HEADER ---------- */

.gameHeader.gameHeaderPolished {
  display: grid;
  grid-template-columns:
    minmax(190px, 1fr)
    auto
    minmax(190px, 1fr);

  align-items: center;
  gap: 24px;

  margin-bottom: 30px;
}

.gameRoundHero {
  display: flex;
  align-items: baseline;
  gap: 11px;

  justify-self: start;
}

.gameRoundHero > span {
  color: #758292;

  font-size: 11px;
  font-weight: 950;
  letter-spacing: 0.14em;
}

.gameRoundHero > strong {
  color: #f5f7fa;

  font-size: 48px;
  font-weight: 950;
  line-height: 0.95;
  letter-spacing: -0.045em;
}

.gameBrand {
  justify-self: center;

  text-align: center;
}

.gameBrand h1 {
  margin: 0 !important;

  font-size: 45px !important;
  font-weight: 950;
  line-height: 1 !important;
  letter-spacing: -0.045em !important;
}

.gameHeaderPolished
.gameHeaderActions {
  justify-self: end;

  display: flex;
  align-items: center;
  gap: 9px;
}

.gameHeaderPolished
.gameHeaderActions button {
  min-height: 46px;
  padding: 0 17px;

  border-radius: 13px;

  font-size: 13px;
  font-weight: 800;
}

/* ---------- SCOREBOARD ---------- */

.standingRow.leader {
  border-color: #4b4330;

  background:
    linear-gradient(
      90deg,
      rgba(215, 174, 81, 0.075),
      #171c24 25%
    );
}

.standingRow.leader::before {
  content: '';

  position: absolute;
  top: 17px;
  bottom: 17px;
  left: -1px;

  width: 4px;

  border-radius: 0 999px 999px 0;

  background: #d9ae4b;
}

.standingRow.leader
.standingRank {
  background: #342d1e;
  color: #e0b75b;
}

.standingNameLine {
  display: flex;
  align-items: center;
  gap: 10px;

  min-width: 0;
}

.standingNameLine h2 {
  margin: 0;

  overflow: hidden;

  font-size: 26px;

  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---------- WAITING ---------- */

.gameWaiting {
  min-height: 56px;

  margin-top: 12px;
  padding: 13px 18px;

  border-radius: 13px;
}

.gameWaiting span {
  font-size: 10px;
}

.gameWaiting strong {
  color: #aeb8c4;

  font-size: 14px;
}

/* ---------- MAIN ACTIONS ---------- */

.gameActions > button {
  min-height: 72px;

  border-radius: 17px;

  font-size: 17px;
  font-weight: 900;
}

.gameActions .penaltyAction {
  grid-column: 3;

  justify-self: end;

  width: min(100%, 185px);
  min-height: 48px;

  margin-top: 2px;

  border-radius: 13px;

  font-size: 13px;
}

/* ---------- NEW SESSION BRAND ---------- */

/* ---------- TABLET / MOBILE ---------- */

@media (max-width: 820px) {
  .gameHeader.gameHeaderPolished {
    grid-template-columns:
      1fr auto;
    gap: 16px;
  }

  .gameBrand {
    grid-column: 1 / -1;
    grid-row: 1;

    justify-self: center;
  }

  .gameRoundHero {
    grid-column: 1;
    grid-row: 2;
  }

  .gameHeaderPolished
  .gameHeaderActions {
    grid-column: 2;
    grid-row: 2;
  }

  .gameBrand h1 {
    font-size: 39px !important;
  }

  .gameRoundHero > strong {
    font-size: 40px;
  }
}

@media (max-width: 620px) {
  .gameHeaderPolished
  .gameHeaderActions {
    gap: 5px;
  }

  .gameHeaderPolished
  .gameHeaderActions button {
    min-height: 40px;
    padding: 0 10px;

    font-size: 11px;
  }

  .standingRow {
    grid-template-columns:
      42px minmax(0, 1fr) 72px;

    min-height: 90px;
    padding: 13px;
  }

  .standingRank {
    width: 33px;
    height: 33px;

    font-size: 15px;
  }

  .standingNameLine {
    gap: 6px;
  }

  .standingNameLine h2 {
    font-size: 20px;
  }

  .standingPlayer p {
    font-size: 9px;
  }

  .standingPoints strong {
    font-size: 38px;
  }

  .gameActions {
    grid-template-columns:
      1fr !important;
  }

  .gameActions .penaltyAction {
    grid-column: 1;

    justify-self: stretch;

    width: 100%;
  }
}

