  gap: 7px;

  margin: 10px 0 8px;
}

.sessionRecordWinner {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;

  min-width: 0;

  padding: 9px 11px;

  border-radius: 10px;

  background: #11151b;
