.sessionRecordWinner h3 {
  min-width: 0;
  margin: 0;

  overflow: hidden;

  font-size: 22px;
  line-height: 1.15;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.sessionRecordWinner > span {
  flex: 0 0 auto;

  color: #82909f;

  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
