  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 10px;

  margin-top: 14px;
}

.historySessionActions
.historyRaceButton,
.historySessionActions
.historyAwardsButton {
  width: 100%;
  min-height: 58px;
  margin-top: 0;

  border: 0;
