  margin-bottom: 4px;

  color: #788493;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.sessionAwardsSummary strong {
  font-size: 20px;
}

.sessionOwnAwardGrid {
  margin-top: 2px;
}

.sessionOwnAwardGrid
.awardCard {
