  stroke-width: 13px !important;
  stroke-linecap: butt !important;
}

/* The SVG itself now owns the center circle */
.jimModeEmblem {
  width: 58% !important;
  aspect-ratio: 1 !important;

  border: none !important;
  border-radius: 0 !important;

  background: transparent !important;

  box-shadow: none !important;

  overflow: visible !important;
}

/* Center the complete SVG exactly */
.jimModeLogo {
  inset: auto !important;

  top: 50% !important;
  left: 50% !important;

  width: 100% !important;
  height: 100% !important;

  transform:
    translate(-50%, -50%) !important;

  object-fit: contain !important;
}

/* Unfinished/background copy */
.jimModeLogoGhost {
  opacity: 0.12 !important;
}

/* Current stage bar stays neutral until survived */

.jimWheelSegment.current {
  stroke: #303946 !important;
  opacity: 0.9 !important;
  filter: none !important;
}

/* Current stage NUMBER can still show where you are */
.jimWheelNumber.current {
