}

/* Completed stages are gold */
.jimWheelSegment.survived {
  stroke: #d5a738 !important;
  opacity: 1 !important;

  filter:
    drop-shadow(
      0 0 5px
      rgba(213, 167, 56, 0.22)
    ) !important;
}

/* Stage numbers only turn gold AFTER survival */

.jimWheelNumber.current {
  fill: #718093 !important;
}

.jimWheelNumber.survived {
  fill: #e4bd62 !important;
}

/* Keep Hide stage purple */
.jimWheelNumber.hidden {
  fill: #d3b8f2 !important;
}

/* ==================================================
   JIM MODE — WIN / CAUGHT OUTCOME WHEEL
   Append at the VERY BOTTOM of index.css
================================================== */

/* Failed current stage turns red only after
   a catcher has been selected. */
.jimWheelSegment.failed {
  stroke: #b95660 !important;
  opacity: 1 !important;

  filter:
    drop-shadow(
      0 0 5px
      rgba(185, 86, 96, 0.28)
    ) !important;
}

.jimWheelNumber.failed {
  fill: #ef9aa2 !important;
}

/* Caught state: give the central Jim a soft red tint. */
.jimWheel.outcome-caught .jimModeLogo {
  filter:
    brightness(0)
    saturate(100%)
    invert(70%)
    sepia(18%)
    saturate(1450%)
    hue-rotate(305deg)
    brightness(96%)
    contrast(92%) !important;
}

.jimWheel.outcome-caught .jimModeLogoGhost {
  opacity: 0.20 !important;
}

.jimWheel.outcome-caught .jimModeEmblem {
  filter:
    drop-shadow(
      0 0 8px
      rgba(185, 86, 96, 0.10)
    );
}

/* Full-survival state: keep all six completed
   stages gold and give the emblem a subtle finish. */
.jimWheel.outcome-win .jimModeLogoBand {
  filter:
    brightness(0)
    invert(1)
    drop-shadow(
      0 0 5px
      rgba(224, 180, 71, 0.16)
    ) !important;
}

.jimWheel.outcome-win .jimModeEmblem {
  filter:
    drop-shadow(
      0 0 8px
      rgba(224, 180, 71, 0.14)
    );
}

