/* ==============================
   AWARD COLORS + BIGGER TITLES
   History / Session Awards CSS.
================================ */

.awardCard {
  --award-color: #d9ae4b;

  border-left:
    4px solid var(--award-color);
}

.awardCard > span {
  color: var(--award-color);

  font-size: 15px;
  font-weight: 950;
  letter-spacing: 0.08em;
}

.awardCard > strong {
  color: var(--award-color);
}

/* Session cards are smaller overall,
   but the award name should still
   be obvious at a glance. */

.sessionAwardCard > span {
  font-size: 13px;
}

.sessionAwardCard h3 {
  font-size: 23px;
}

/* Each family title gets its own
   stable visual identity. */

.awardTone-cuci {
  --award-color: #6fc8d4;
}

.awardTone-slayer {
  --award-color: #ef7f89;
}

.awardTone-tuah {
  --award-color: #e0b65c;
}

.awardTone-malang {
  --award-color: #b491df;
}

.awardTone-standard {
  --award-color: #79a7f2;
}

.awardTone-jim {
  --award-color: #e79a61;
}

.awardTone-hide {
  --award-color: #bd8fe9;
}

.awardTone-denda {
  --award-color: #e88b9c;
}

.awardTone-survivor {
  --award-color: #7fcf95;
}

.awardTone-comeback {
  --award-color: #67c5b3;
}

.awardTone-jatuh {
  --award-color: #d7838f;
}

.awardTone-default {
  --award-color: #aab5c2;
}

@media (max-width: 600px) {
  .awardCard > span {
    font-size: 14px;
  }

  .sessionAwardCard > span {
    font-size: 12px;
  }
}

/* ==============================
   HISTORY V3
   History / Awards CSS.
================================ */

/* SESSION DETAILS */

.historySessionMetaExpanded {
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
}

/* PLAYER SORTING */

.playerSortPanel {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;

  margin-bottom: 14px;
  padding: 16px 18px;

  border: 1px solid #29313b;
  border-radius: 16px;

  background: #151a21;
}

.playerSortPanel > div:first-child {
  display: grid;
  gap: 3px;

  flex: 0 0 auto;
}

.playerSortPanel > div:first-child span {
  color: #788493;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.playerSortPanel > div:first-child strong {
  font-size: 17px;
}

.playerSortButtons {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 7px;
}

.playerSortButtons button {
  min-height: 38px;
  padding: 0 12px;

  border: 1px solid #303945;
  border-radius: 10px;

  background: #202630;
  color: #8f9aa7;

  font-size: 11px;
  font-weight: 850;
}

.playerSortButtons button.active {
  border-color: #59697d;

  background: #344152;
  color: #f5f7fa;
}

.playerStatsIdentity {
  display: flex !important;
  align-items: center;
  gap: 13px;
}

.playerStatsRank {
  display: grid !important;
  place-items: center;

  width: 42px;
  height: 42px;

  flex: 0 0 42px;

  border-radius: 12px;

  background: #242c36;
  color: #9ba7b5 !important;

  font-size: 13px !important;
  font-weight: 900;
}

.playerStatsHeadline {
  display: grid;
  justify-items: end;
  gap: 1px;
}

.playerStatsHeadline strong {
  font-size: 25px;
}

.playerStatsHeadline span {
  color: #778391;

  font-size: 8px !important;
  font-weight: 900;
  letter-spacing: 0.09em;
}

/* AWARD SECTIONS */

.awardSection {
  display: grid;
  gap: 13px;

  margin-top: 10px;
}

.awardSection + .awardSection {
  margin-top: 28px;
  padding-top: 27px;

  border-top: 1px solid #29313b;
}

.awardSectionHeader {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 30px;

  padding: 0 2px;
}

.awardSectionHeader > div {
  display: grid;
  gap: 3px;
}

.awardSectionHeader > div > span {
  color: #8a95a3;

  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.awardSectionHeader h3 {
  margin: 0;

  font-size: 25px;
}

.awardSectionHeader p {
  max-width: 420px;
  margin: 0;

  color: #74808e;

  font-size: 12px;
  line-height: 1.45;
  text-align: right;
}

.awardRecordNote {
  display: block;

  margin-top: 5px;

  color: #8995a3;

  font-size: 11px;
  font-weight: 800;
}

.rateAwardCard {
  min-height: 180px;
}

/* Updated award tones */

.awardTone-denda {
  --award-color: #df8a72;
}

.awardTone-duration {
  --award-color: #70b8d9;
}

.awardTone-rounds {
  --award-color: #8ca8e8;
}

/* Bigger award identity */

.awardCard > span {
  font-size: 25px;
}

.awardCard h3 {
  margin-top: 10px;

  font-size: 28px;
}

.awardCard > strong {
  font-size: 17px;
}

/* Mobile */

@media (max-width: 800px) {
  .playerSortPanel {
    align-items: flex-start;
    flex-direction: column;
  }

  .playerSortButtons {
    justify-content: flex-start;

    width: 100%;
  }

  .historySessionMetaExpanded {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .awardSectionHeader {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }

  .awardSectionHeader p {
    max-width: none;

    text-align: left;
  }
}

@media (max-width: 520px) {
  .playerSortButtons {
    display: grid;
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .playerSortButtons button {
    width: 100%;
  }

  .playerStatsCard > header {
    align-items: flex-start;
  }

  .playerStatsHeadline {
    min-width: 70px;
  }

  .historySessionMetaExpanded {
    grid-template-columns: 1fr 1fr;
  }

  .awardCard > span {
    font-size: 25px;
  }

  .awardCard h3 {
    font-size: 23px;
  }
}

/* ==============================
   COMBINED ALL-TIME AWARDS
================================ */

.combinedAwardCard {
  grid-column: span 1;

  padding: 22px;
}

.combinedAwardDescription {
  margin: 8px 0 17px !important;

  color: #7f8b99 !important;

  font-size: 12px !important;
  line-height: 1.45 !important;
}

.combinedAwardMetrics {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));

  overflow: hidden;

  border: 1px solid #2b343f;
  border-radius: 14px;

  background: #11151b;
}

.combinedAwardMetric {
  min-width: 0;

  padding: 15px 16px;
}

.combinedAwardMetric +
.combinedAwardMetric {
  border-left:
    1px solid #2b343f;
}

.combinedAwardMetric small {
  display: block;

  margin-bottom: 6px;

  color: var(--award-color);

  font-size: 9px;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.09em;
}

.combinedAwardMetric h3 {
  margin: 0 0 3px;

  overflow-wrap: anywhere;

  font-size: 23px;
}

.combinedAwardMetric strong {
  display: block;

  color: var(--award-color);

  font-size: 15px;
}

.combinedAwardMetric em {
  display: block;

  margin-top: 5px;

  color: #778493;

  font-size: 10px;
  font-style: normal;
  font-weight: 750;
}

/* Raja Session */
.awardTone-session {
  --award-color: #75c6a7;
}

@media (max-width: 620px) {
  .combinedAwardMetrics {
    grid-template-columns: 1fr;
  }

  .combinedAwardMetric +
  .combinedAwardMetric {
    border-top:
      1px solid #2b343f;

    border-left: 0;
  }

  .combinedAwardMetric h3 {
    font-size: 21px;
  }
}

/* ==============================
   CLEAN SINGLE-SESSION WINNERS
================================ */

.sessionRecordWinners {
  display: grid;
  gap: 7px;

  margin: 10px 0 8px;
}

.sessionRecordWinner {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;

  min-width: 0;

  padding: 9px 11px;

  border-radius: 10px;

  background: #11151b;
}

.sessionRecordWinner h3 {
  min-width: 0;
  margin: 0;

  overflow: hidden;

  font-size: 22px;
  line-height: 1.15;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.sessionRecordWinner > span {
  flex: 0 0 auto;

  color: #82909f;

  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}

/* Keep the record value visually
   separate from the winner rows. */
.rateAwardCard > .sessionRecordWinners + strong {
  display: block;

  margin-top: 7px;
}

/* On small screens, let the date sit
   underneath instead of crushing names. */
@media (max-width: 520px) {
  .sessionRecordWinner {
    align-items: flex-start;
    flex-direction: column;
    gap: 2px;
  }

  .sessionRecordWinner h3 {
    width: 100%;

    overflow: visible;
    white-space: normal;
  }
}

/* ==============================
   CLEAN ALL-TIME TIED WINNERS
   combined award CSS.
================================ */

.combinedWinnerList {
  display: grid;
  gap: 5px;

  margin: 2px 0 7px;
}

.combinedWinnerRow {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;

  min-width: 0;
}

.combinedWinnerRow h3 {
  min-width: 0;
  margin: 0;

  overflow: hidden;

  font-size: 22px;
  line-height: 1.18;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.combinedWinnerRow > span {
  flex: 0 0 auto;

  color: #7f8b99;

  font-size: 10px;
  font-weight: 800;
  white-space: nowrap;
}

/* Keep the shared record value
   visually separate from tied names. */

.combinedAwardMetric >
.combinedWinnerList + strong {
  margin-top: 5px;
}

/* If many people share a record,
   the card grows vertically instead
   of forcing names onto one line. */

@media (max-width: 520px) {
  .combinedWinnerRow {
    align-items: flex-start;
    flex-direction: column;
    gap: 1px;
  }

  .combinedWinnerRow h3 {
    width: 100%;

    overflow: visible;
    white-space: normal;
  }
}

/* ==============================
   PER-SESSION AWARDS
================================ */

.historySessionActions {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 10px;

  margin-top: 14px;
}

.historySessionActions
.historyRaceButton,
.historySessionActions
.historyAwardsButton {
  width: 100%;
  min-height: 58px;
  margin-top: 0;

  border: 0;
  border-radius: 14px;

  font-weight: 850;
}

.historyAwardsButton {
  background: #26382f;
  color: #91d5aa;
}

.historyAwardsButton:hover {
  background: #2d4437;
}

.sessionAwardsPage {
  max-width: 1100px;
}

.sessionAwardsSummary {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 10px;

  margin-bottom: 18px;
}

.sessionAwardsSummary > div {
  padding: 15px 17px;

  border: 1px solid #29313b;
  border-radius: 14px;

  background: #151a21;
}

.sessionAwardsSummary span {
  display: block;

  margin-bottom: 4px;

  color: #788493;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.sessionAwardsSummary strong {
  font-size: 20px;
}

.sessionOwnAwardGrid {
  margin-top: 2px;
}

.sessionOwnAwardGrid
.awardCard {
  min-height: 190px;
}

@media (max-width: 600px) {
  .historySessionActions {
    grid-template-columns: 1fr;
  }

  .sessionAwardsSummary {
    grid-template-columns: 1fr 1fr;
  }
}

/* ==============================
   PLAYER SORT STAT HIGHLIGHT
================================ */

/* Grid statistic selected by the
   active player-sort button. */
.playerStatGrid > div.sortStatHighlight {
  position: relative;

  border:
    1px solid rgba(222, 181, 88, 0.62);

  background:
    linear-gradient(
      135deg,
      rgba(222, 181, 88, 0.11),
      #11151b 62%
    );

  box-shadow:
    inset 0 0 0 1px
      rgba(222, 181, 88, 0.05);
}

.playerStatGrid >
div.sortStatHighlight > span {
  color: #c7a755;
}

.playerStatGrid >
div.sortStatHighlight > strong {
  color: #f0c75e;
}

/* TOTAL PTS lives in the card header
   rather than the stat grid. */
.playerStatsHeadline.sortStatHighlight {
  min-width: 92px;
  padding: 9px 11px;

  border:
    1px solid rgba(222, 181, 88, 0.62);
