  overflow: hidden;

  font-size: 22px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mvpPodiumPlayer > small {
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.09em;
}

.mvpMedal {
