  background: #596473;
  color: #f5f7fa;

  font-size: 16px;
  font-weight: 950;
}

.mvpPodiumScore {
  display: grid;
  justify-items: center;

  padding: 13px 10px;

  border-right: 1px solid #313a46;
  border-left: 1px solid #313a46;

  background: #11151b;
}

.mvpPodiumScore strong {
  font-size: 31px;
  line-height: 1;
}

.mvpPodiumScore span {
  margin-top: 4px;

  color: #7e8997;

  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.mvpPodiumBlock {
  display: grid;
  place-items: center;

