  gap: 18px;
}

.awardsIntro {
  padding: 5px 2px 2px;
}

.awardsIntro > span {
  color: #d9ae4b;

  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.awardsIntro h2 {
  margin: 5px 0 6px;

  font-size: 31px;
}

.awardsIntro p {
  max-width: 620px;
  margin: 0;

  color: #8994a2;
  line-height: 1.5;
}

