  font-size: 27px;
}

.awardCard > strong {
  color: #b5c0cd;

  font-size: 15px;
}

.awardCard p {
  margin: 11px 0 0;

  color: #7f8b99;

  font-size: 13px;
  line-height: 1.4;
}

@media (max-width: 700px) {
  .historySessionMeta {
    grid-template-columns:
      repeat(2, 1fr);
  }

  .playerStatSectionLabel {
    font-size: 13px;
  }

  .playerStatGrid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

