  color: #91d5aa;
}

.historyAwardsButton:hover {
  background: #2d4437;
}

.sessionAwardsPage {
  max-width: 1100px;
}

.sessionAwardsSummary {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 10px;

  margin-bottom: 18px;
}

.sessionAwardsSummary > div {
  padding: 15px 17px;

  border: 1px solid #29313b;
  border-radius: 14px;

  background: #151a21;
}

.sessionAwardsSummary span {
  display: block;

  margin-bottom: 4px;

  color: #788493;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.sessionAwardsSummary strong {
  font-size: 20px;
}

.sessionOwnAwardGrid {
  margin-top: 2px;
}

.sessionOwnAwardGrid
.awardCard {
  min-height: 190px;
}

@media (max-width: 600px) {
  .historySessionActions {
    grid-template-columns: 1fr;
  }

  .sessionAwardsSummary {
    grid-template-columns: 1fr 1fr;
  }
}

/* ==============================
