  border-radius: 11px;

  background: #202936;
  color: #eef3f8;

  font-size: 11px;
  font-weight: 900;
}

/* ---------- BOARD ---------- */

.cleanTransitionBoard {
  position: relative;

  width: 100%;
}

.cleanTransitionRow {
  position: absolute;
  left: 0;
  right: 0;

  box-sizing: border-box;

  display: grid;
  grid-template-columns:
    50px
    minmax(0, 1fr)
    92px;

  align-items: center;
  gap: 16px;

  height: 94px;
  padding: 15px 20px;

  overflow: visible;

  border: 1px solid #2a3441;
  border-radius: 17px;

  background: #171e27;

  transition:
    top 900ms
      cubic-bezier(
        0.22,
        1,
        0.36,
        1
      ),
    border-color
      300ms ease,
    transform
      300ms ease;
}

.cleanTransitionRow.settled {
  border-color: #344151;
}

.cleanTransitionRank {
  color: #8291a5;

  font-size: 23px;
