/* =========================================
   ANDROID APP POLISH
========================================= */

/* Let the Android status-bar safe area
   blend into the JIMRAMI background */
html,
body,
#root {
  background-color: #0d1015 !important;
}

/* Remove Android/WebView blue tap flash */
button,
a,
input,
select,
textarea,
[role="button"] {
  -webkit-tap-highlight-color: transparent;
}

/* Don't leave a focus rectangle after touch */
button:focus:not(:focus-visible),
a:focus:not(:focus-visible),
[role="button"]:focus:not(:focus-visible) {
  outline: none;
}

/* =========================================
   ANDROID — DOUBLE BACK TO EXIT
========================================= */

.androidExitHint {
  position: fixed;
  left: 50%;
  bottom: calc(24px + env(safe-area-inset-bottom));
  z-index: 9999;

  transform: translateX(-50%);

  padding: 10px 16px;
  border: 1px solid #2f3945;
  border-radius: 999px;

  background: rgba(18, 24, 31, 0.96);
  color: #dbe3ec;

  font-size: 12px;
  font-weight: 800;
  line-height: 1;
  white-space: nowrap;

  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.28);

  pointer-events: none;
}

/* =========================================
   JIMRAMI — PAGE TRANSITIONS
========================================= */

@keyframes jimPageEnter {
  from {
    opacity: 0;
    transform: translateY(6px) scale(0.995);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.app {
  animation:
    jimPageEnter
    180ms
    cubic-bezier(0.22, 1, 0.36, 1);
}

/* Respect Android accessibility settings */
@media (prefers-reduced-motion: reduce) {
  .app {
    animation: none;
  }
}

/* =========================================
   JIMRAMI — PAGE TRANSITIONS V2
========================================= */

/* History tabs:
   keep the header/tab bar still, animate only
   the content underneath it. */
@keyframes jimHistoryTabEnter {
  from {
    opacity: 0;
    transform: translateY(8px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.historyTabPage {
  animation:
    jimHistoryTabEnter
    200ms
    cubic-bezier(0.22, 1, 0.36, 1)
    both;
}


/* Score Transition gets a slightly clearer
   full-page entrance than ordinary pages. */
@keyframes jimScoreTransitionEnter {
  from {
    opacity: 0;
    transform:
      translateY(10px)
      scale(0.992);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }
}

@keyframes jimScoreTransitionExit {
  from {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }

  to {
    opacity: 0;
    transform:
      translateY(-6px)
      scale(0.996);
  }
}

.scoreTransitionShell
  > .cleanTransitionPage {
  animation:
    jimScoreTransitionEnter
    220ms
    cubic-bezier(0.22, 1, 0.36, 1)
    both !important;
}

.scoreTransitionShell.leaving
  > .cleanTransitionPage {
  animation:
    jimScoreTransitionExit
    160ms
    ease-in
    forwards !important;

  pointer-events: none;
}


/* Accessibility */
@media (prefers-reduced-motion: reduce) {
  .historyTabPage,
  .scoreTransitionShell
    > .cleanTransitionPage,
  .scoreTransitionShell.leaving
    > .cleanTransitionPage {
    animation: none !important;
  }
}

/* =========================================
   JIM ROUND — INTERNAL PHASE TRANSITIONS
========================================= */

@keyframes jimPhaseEnter {
  from {
    opacity: 0;
    transform:
      translateY(8px)
      scale(0.995);
  }

  to {
    opacity: 1;
    transform:
      translateY(0)
      scale(1);
  }
}

.jimPhasePage {
  animation:
    jimPhaseEnter
    200ms
    cubic-bezier(0.22, 1, 0.36, 1)
    both;
}

@media (prefers-reduced-motion: reduce) {
  .jimPhasePage {
    animation: none;
  }
}

/* =========================================
   JIMRAMI — APP LAUNCH INTRO
========================================= */

