/* A shared dark tooltip. Browser title attributes are removed in TSX. */
.mvpRadarViewButton[data-tooltip]::after,
.mvpRadarVisibility[data-tooltip]::after,
.mvpRadarRemove[data-tooltip]::after {
  content: attr(data-tooltip);
  position: absolute;
  top: calc(100% + 10px);
  left: 0;
  width: max-content;
  max-width: min(230px, 72vw);
  box-sizing: border-box;
  padding: 8px 11px;
  border: 1px solid #4a586a;
  border-left: 3px solid #deb66c;
  border-radius: 8px;
  background: #1b2532;
  color: #f0f3f8;
  box-shadow: 0 9px 26px rgba(0, 0, 0, .35);
  font-family: inherit;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.4;
  text-align: left;
  white-space: normal;
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-4px);
  transition: opacity .14s ease, transform .14s ease, visibility .14s ease;
  z-index: 200;
}

.mvpRadarViewButton[data-tooltip]::before,
.mvpRadarVisibility[data-tooltip]::before,
.mvpRadarRemove[data-tooltip]::before {
  content: '';
  position: absolute;
  left: 13px;
  top: calc(100% + 5px);
  width: 8px;
  height: 8px;
  background: #1b2532;
  border-top: 1px solid #4a586a;
  border-left: 1px solid #4a586a;
  transform: translateY(-4px) rotate(45deg);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  z-index: 201;
  transition: opacity .14s ease, visibility .14s ease;
}

@media (hover: hover) and (pointer: fine) {
  .mvpRadarViewButton[data-tooltip]:hover::after,
  .mvpRadarVisibility[data-tooltip]:hover::after,
  .mvpRadarRemove[data-tooltip]:hover::after,
  .mvpRadarViewButton[data-tooltip]:hover::before,
  .mvpRadarVisibility[data-tooltip]:hover::before,
  .mvpRadarRemove[data-tooltip]:hover::before {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
  }
  .mvpRadarViewButton[data-tooltip]:hover::before,
  .mvpRadarVisibility[data-tooltip]:hover::before,
  .mvpRadarRemove[data-tooltip]:hover::before {
    transform: rotate(45deg);
  }
}

.mvpRadarViewButton[data-tooltip]:focus-visible::after,
.mvpRadarVisibility[data-tooltip]:focus-visible::after,
.mvpRadarRemove[data-tooltip]:focus-visible::after,
.mvpRadarViewButton[data-tooltip]:focus-visible::before,
.mvpRadarVisibility[data-tooltip]:focus-visible::before,
.mvpRadarRemove[data-tooltip]:focus-visible::before {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}
.mvpRadarViewButton[data-tooltip]:focus-visible::before,
.mvpRadarVisibility[data-tooltip]:focus-visible::before,
.mvpRadarRemove[data-tooltip]:focus-visible::before {
  transform: rotate(45deg);
}

/* Keep right-edge hints inside the phone viewport. */
.mvpRadarViewButton[data-tooltip]:last-child::after,
.mvpRadarRemove[data-tooltip]::after {
  left: auto;
  right: 0;
}
.mvpRadarViewButton[data-tooltip]:last-child::before,
.mvpRadarRemove[data-tooltip]::before {
  left: auto;
  right: 13px;
}

/* Hidden players are dimmed; the tooltip stays readable. */
.mvpRadarChip.is-hidden:hover,
.mvpRadarChip.is-hidden:focus-within { opacity: 1; }

@media (prefers-reduced-motion: reduce) {
  .mvpRadarViewButton[data-tooltip]::after,
  .mvpRadarVisibility[data-tooltip]::after,
  .mvpRadarRemove[data-tooltip]::after,
  .mvpRadarViewButton[data-tooltip]::before,
  .mvpRadarVisibility[data-tooltip]::before,
  .mvpRadarRemove[data-tooltip]::before { transition: none; }
}

