  line-height: 1;
  box-shadow: inset 0 1px 0 #9b6e32;
}

.goalpostDialog .goalpostWinnerIdentity {
  grid-area: auto;
  min-width: 0;
  align-self: center;
  justify-content: center;
  gap: 0;
  padding: 0;
}

/* Crown belongs to the winner label, not above it. */
.goalpostDialog .goalpostFeatureHeadline {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px 9px;
  min-width: 0;
}
.goalpostDialog .goalpostFeatureCrown {
  display: inline-block;
  flex: none;
  margin: 0;
  color: #edb953;
  font-size: 26px;
  line-height: 1;
}
.goalpostDialog .goalpostFeatureWinnerTag {
  padding: 4px 9px;
  border: 1px solid #765425;
  border-radius: 99px;
  color: #e9b754;
  background: #292216;
  font-size: 9px;
  letter-spacing: .1em;
}
.goalpostDialog .goalpostWinnerIdentity .goalpostFeatureName {
  margin: 7px 0 0;
  color: #fff4df;
  font-size: clamp(26px, 3.5vw, 36px);
  font-weight: 950;
  letter-spacing: -.035em;
  line-height: 1.13;
  text-align: left;
  overflow-wrap: anywhere;
}

/* Achievements remain with the name, never floating at the far right. */
.goalpostDialog .goalpostWinnerMeta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 5px 12px;
  min-width: 0;
  margin-top: 9px;
}
.goalpostDialog .goalpostWinnerMeta .goalpostRankingAccolades {
  width: auto;
  margin: 0;
  min-height: 18px;
  justify-content: flex-start;
  gap: 5px 9px;
}
.goalpostDialog .goalpostWinnerMeta .goalpostFeatureTarget {
  display: inline-flex;
  align-items: center;
  align-self: center;
  margin: 0;
  padding: 5px 9px;
  border-radius: 99px;
  font-size: 9px;
  white-space: nowrap;
}
.goalpostDialog .goalpostWinnerMeta .goalpostFeatureTarget strong {
  margin-left: 4px;
}

/* Large points are still prominent, without another tall, boxed column. */
.goalpostDialog .goalpostWinnerScoreBlock {
  grid-area: auto;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: center;
  min-width: 0;
  height: auto;
  padding: 8px 0 8px 11px;
  border: 0;
  border-left: 1px solid #655133;
  border-radius: 0;
  background: transparent;
  text-align: right;
}
.goalpostDialog .goalpostWinnerScoreBlock > strong {
  color: #f3c166;
  font-size: clamp(37px, 5vw, 49px);
  line-height: 1;
  font-weight: 950;
  font-variant-numeric: tabular-nums;
}
.goalpostDialog .goalpostWinnerScoreBlock > span {
  margin-top: 8px;
  color: #cba65d;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .12em;
}

/* Tablet and phone layouts keep all three elements in a neat row. */
@media (max-width: 600px) {
  .goalpostDialog .goalpostWinnerFeature {
    grid-template-columns: 47px minmax(0, 1fr) 59px;
    grid-template-areas: none;
    gap: 10px;
    min-height: 116px;
    padding: 13px 10px;
    margin: 11px 0 15px;
  }
  .goalpostDialog .goalpostWinnerRankBlock,
  .goalpostDialog .goalpostWinnerIdentity,
  .goalpostDialog .goalpostWinnerScoreBlock { grid-area: auto; }
  .goalpostDialog .goalpostWinnerRankBlock,
  .goalpostDialog .goalpostWinnerRankBlock > span {
    width: 47px;
    height: 47px;
  }
  .goalpostDialog .goalpostWinnerRankBlock > span {
    min-height: 0;
    font-size: 33px;
    border-radius: 10px;
  }
  .goalpostDialog .goalpostFeatureCrown { font-size: 22px; }
  .goalpostDialog .goalpostFeatureHeadline { gap: 5px; }
  .goalpostDialog .goalpostFeatureWinnerTag { padding: 3px 6px; font-size: 8px; }
  .goalpostDialog .goalpostWinnerIdentity .goalpostFeatureName {
    font-size: clamp(21px, 5.5vw, 29px);
    margin-top: 6px;
  }
  .goalpostDialog .goalpostWinnerMeta { gap: 5px 7px; margin-top: 7px; }
  .goalpostDialog .goalpostWinnerMeta .goalpostFeatureTarget {
    font-size: 8px;
    padding: 4px 7px;
  }
  .goalpostDialog .goalpostWinnerScoreBlock { padding-left: 7px; }
  .goalpostDialog .goalpostWinnerScoreBlock > strong { font-size: 34px; }
  .goalpostDialog .goalpostWinnerScoreBlock > span { font-size: 8px; }
}

@media (max-width: 360px) {
  .goalpostDialog .goalpostWinnerFeature {
    grid-template-columns: 39px minmax(0, 1fr) 50px;
    gap: 7px;
    padding: 11px 8px;
  }
  .goalpostDialog .goalpostWinnerRankBlock,
  .goalpostDialog .goalpostWinnerRankBlock > span { width: 39px; height: 39px; }
  .goalpostDialog .goalpostWinnerRankBlock > span { font-size: 28px; }
  .goalpostDialog .goalpostWinnerScoreBlock > strong { font-size: 30px; }
  .goalpostDialog .goalpostWinnerIdentity .goalpostFeatureName { font-size: 21px; }
}

/* JIMRAMI - Goalpost banner position refinement.
   APPEND to the bottom of src/index.css (after previous Goalpost CSS). */

/* The result type and target belong together at the top of the screen. */
.goalpostDialog.reached > .goalpostEyebrow,
.goalpostDialog.complete > .goalpostEyebrow {
  display: block;
  text-align: center;
}
.goalpostDialog .goalpostHeaderTarget {
  display: flex;
  justify-content: center;
  align-items: baseline;
  gap: 5px;
  width: fit-content;
  max-width: 100%;
  margin: 8px auto 18px;
  padding: 6px 11px;
  border: 1px solid #6d4e21;
  border-radius: 999px;
  background: #292215;
  color: #ddb35b;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .07em;
  line-height: 1.1;
  white-space: nowrap;
}
.goalpostDialog .goalpostHeaderTarget strong { color: #f2c466; font-size: inherit; }

/* Tighten the winner card now that the target is above it. */
.goalpostDialog .goalpostWinnerFeature {
  margin-top: 0;
  min-height: 126px;
}
.goalpostDialog .goalpostWinnerIdentity { min-width: 0; }
.goalpostDialog .goalpostFeatureHeadline { margin-bottom: 7px; }
.goalpostDialog .goalpostFeatureNameLine {
  width: min(100%, 300px);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  min-width: 0;
}
.goalpostDialog .goalpostFeatureNameLine .goalpostFeatureName {
  flex: 0 1 auto;
  min-width: 0;
  margin: 0;
}
/* Same name line, but visually separated from the lettering. */
.goalpostDialog .goalpostFeatureNameLine .goalpostFeatureCrown {
  display: block;
  flex: 0 0 auto;
  margin-left: auto;
  font-size: 27px;
  line-height: 1;
}
.goalpostDialog .goalpostWinnerMeta { margin-top: 9px; }

@media (max-width: 600px) {
  .goalpostDialog .goalpostHeaderTarget {
    margin: 7px auto 14px;
    font-size: 9px;
  }
  .goalpostDialog .goalpostWinnerFeature { min-height: 110px; }
  .goalpostDialog .goalpostFeatureNameLine { gap: 9px; }
  .goalpostDialog .goalpostFeatureNameLine .goalpostFeatureCrown { font-size: 22px; }
}

/* JIMRAMI — larger crown beside winner's name */
.goalpostDialog .goalpostFeatureNameLine .goalpostFeatureCrown {
  font-size: 50px;
}

@media (max-width: 600px) {
  .goalpostDialog .goalpostFeatureNameLine .goalpostFeatureCrown {
    font-size: 50px;
  }
}

/* SCORE TRANSITION — JIM win ring colors
   Purple ring = JIM won using Hide (existing styling).
   Gold ring = perfect JIM, won without Hide.
   Append to the bottom of src/index.css. */

/* JIM stars shown below the player name after score animation. */
.scoreJimStars > .scoreJimStar.hideless {
  border: 1px solid #e3b64b;
  border-radius: 50%;
  background: rgba(227, 182, 75, 0.065);
  box-shadow: inset 0 0 0 1px rgba(227, 182, 75, 0.06);
}

/* JIM star inside the temporary +points reward bubble. */
.cleanRewardBubble .rewardStar.hideless {
  border: 1px solid #e3b64b;
  border-radius: 50%;
  background: rgba(227, 182, 75, 0.065);
  box-shadow: inset 0 0 0 1px rgba(227, 182, 75, 0.06);
}

/* JIMRAMI — one-time gold fireworks on Session Complete only.
   APPEND to the bottom of src/index.css. */
.goalpostDialog.complete {
  position: relative;
  isolation: isolate;
}

/* Draw sparks into the dialog background, not on top of the labels or controls. */
.goalpostDialog.complete > .goalpostGoldFireworks {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  /* Above opaque card surfaces, but below important text and controls. */
  z-index: 2;
  pointer-events: none;
  user-select: none;
  opacity: 0.92;
}

.goalpostDialog.complete > :not(.goalpostGoldFireworks) {
  position: relative;
  z-index: 3;
}

/* Let the particles glimmer across the winner card's surface,
   with the name, crown and points always above the particles. */
.goalpostDialog.complete > .goalpostWinnerFeature {
  z-index: auto;
}
.goalpostDialog.complete > .goalpostWinnerFeature > * {
  position: relative;
  z-index: 3;
}

/* Put the goalpost winner crown directly next to the player's name. */
.goalpostDialog .goalpostFeatureNameLine {
  width: auto;
  max-width: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
}

.goalpostDialog .goalpostFeatureNameLine .goalpostFeatureName {
  flex: 0 1 auto;
}

.goalpostDialog .goalpostFeatureNameLine .goalpostFeatureCrown {
  margin-left: 0 !important;
  flex: 0 0 auto;
}

@media (max-width: 600px) {
  .goalpostDialog .goalpostFeatureNameLine {
    gap: 8px;
  }
}


/* PREVIOUS WINNER — Gold ring for JIM without Hide */

.previousWinnerIcon.jim:not(.usedHide):not(.caught) {
  position: relative;
}

.previousWinnerIcon.jim:not(.usedHide):not(.caught)::after {
  content: '';
  position: absolute;
  inset: 5px;
  border: 1px solid #e3b64b;
  border-radius: 50%;
  background: rgba(227, 182, 75, 0.035);
  box-shadow: inset 0 0 0 1px rgba(227, 182, 75, 0.06);
  pointer-events: none;
}
